local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local ipairs = ipairs
local pcall = pcall

local Players = game:GetService("Players")
local env = type(getgenv) == "function" and getgenv() or _G

-- DepHub bundled build. Source revision 0.1.26.
-- Generated by tools/bundle.js. Do not edit by hand.
local BUNDLED_SOURCES = {
    ["src/core/anti-afk.lua"] = [[
local Players = game:GetService("Players")
local VirtualUser = game:GetService("VirtualUser")

local AntiAFK = {
    Enabled = false,
    Connection = nil
}

function AntiAFK.Start()
    if AntiAFK.Enabled then return end
    AntiAFK.Enabled = true

    if AntiAFK.Connection then
        pcall(function()
            AntiAFK.Connection:Disconnect()
        end)
    end

    AntiAFK.Connection = Players.LocalPlayer.Idled:Connect(function()
        if not AntiAFK.Enabled then return end
        pcall(function()
            VirtualUser:CaptureController()
            VirtualUser:ClickButton2(Vector2.new(0, 0))
        end)
    end)
end

function AntiAFK.Stop()
    AntiAFK.Enabled = false
    if AntiAFK.Connection then
        pcall(function()
            AntiAFK.Connection:Disconnect()
        end)
        AntiAFK.Connection = nil
    end
end

function AntiAFK.Toggle(state)
    if state then
        AntiAFK.Start()
    else
        AntiAFK.Stop()
    end
end

AntiAFK.Set = AntiAFK.Toggle

return AntiAFK

]],
    ["src/core/dashboard.lua"] = [[
local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local pcall = pcall
local os_clock = os.clock
local math_floor = math.floor
local string_match = string.match

local GetService = game.GetService
local Players = GetService(game, "Players")
local Stats = GetService(game, "Stats")
local RunService = GetService(game, "RunService")

local Dashboard = {}
Dashboard.__index = Dashboard

local sourceBase = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local RELEASES_BASE_URL = sourceBase .. "src/games/updates/"

local function safeCall(callback, fallback)
    local ok, result = pcall(callback)
    if ok then
        return result
    end
    return fallback
end

local function httpGet(url)
    local ok, result = pcall(function()
        return __dephubHttpGet(url)
    end)
    if ok and type(result) == "string" and #result > 0 then
        return true, result
    end
    return false, nil
end

local function getPing()
    return safeCall(function()
        local network = Stats:FindFirstChild("Network")
        local serverStats = network and network:FindFirstChild("ServerStatsItem")
        local ping = serverStats and (serverStats:FindFirstChild("Data Ping") or serverStats:FindFirstChild("Ping"))
        if not ping then
            return nil
        end
        local raw = ping:GetValueString()
        return math_floor((tonumber(string_match(raw, "[%d%.]+")) or 0) + 0.5)
    end, nil)
end

local function detectExecutor()
    return safeCall(function()
        if type(identifyexecutor) ~= "function" then
            return "Unknown"
        end
        local name, version = identifyexecutor()
        if name and version then
            return tostring(name) .. " " .. tostring(version)
        end
        return name and tostring(name) or "Unknown"
    end, "Unknown")
end

local function parseUpdates(source)
    local updates = {}
    if type(source) ~= "string" then
        return updates
    end

    for line in source:gmatch("[^\r\n]+") do
        line = line:gsub("^%s+", ""):gsub("%s+$", "")
        if line ~= "" then
            local version, change = line:match("^([^|]+)|(.+)$")
            if version and change then
                updates[#updates + 1] = {
                    Version = version:gsub("^%s+", ""):gsub("%s+$", ""),
                    Date = "",
                    Changes = {change:gsub("^%s+", ""):gsub("%s+$", "")}
                }
            else
                updates[#updates + 1] = {
                    Version = line,
                    Date = "",
                    Changes = {}
                }
            end
        end
    end

    return updates
end

local function getRecentUpdates(placeId)
    local ok, source = httpGet(RELEASES_BASE_URL .. tostring(placeId) .. ".txt?dephubupdates=" .. tostring(math_floor(os_clock() * 1000000)))
    if not ok then
        return {}, "Unknown"
    end

    local updates = parseUpdates(source)
    return updates, updates[1] and updates[1].Version or "Unknown"
end

function Dashboard.new(options)
    options = options or {}

    local self = setmetatable({}, Dashboard)
    self.Destroyed = false
    self.Started = false
    self.Interval = math.max(tonumber(options.Interval) or 1, 0.25)
    self.ManifestInterval = math.max(tonumber(options.ManifestInterval) or 30, 5)
    self.Executor = detectExecutor()
    self.ScriptVersion = options.ScriptVersion and tostring(options.ScriptVersion) or nil
    self.FPS = 0
    self.Ping = nil
    self.LastUpdate = 0
    self.LastReleaseCheck = 0
    self.Connections = {}
    self.StartedAt = os_clock()
    self.Data = {}
    self.OnUpdate = options.OnUpdate
    self.RecentUpdates = {}
    return self
end

function Dashboard:RefreshUpdates(force)
    local now = os_clock()
    if not force and now - self.LastReleaseCheck < self.ManifestInterval then
        return
    end

    local updates, version = getRecentUpdates(game.PlaceId)
    self.RecentUpdates = updates
    self.ScriptVersion = version
    self.LastReleaseCheck = now
end

function Dashboard:Collect()
    if self.Destroyed then
        return nil
    end

    self:RefreshUpdates(false)

    local playerCount = safeCall(function()
        return #Players:GetPlayers()
    end, 0)

    local maxPlayers = safeCall(function()
        return Players.MaxPlayers
    end, 0)

    local data = {
        Executor = self.Executor,
        Ping = getPing(),
        FPS = self.FPS,
        PlaceId = tostring(game.PlaceId),
        GameId = tostring(game.GameId),
        JobId = tostring(game.JobId),
        GameName = tostring(game.Name),
        ScriptVersion = self.ScriptVersion or "Unknown",
        RecentUpdates = self.RecentUpdates,
        Players = playerCount,
        MaxPlayers = maxPlayers,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        Timestamp = os_clock()
    }

    self.Ping = data.Ping
    self.LastUpdate = data.Timestamp
    self.Data = data

    if self.OnUpdate then
        pcall(self.OnUpdate, data)
    end

    return data
end

function Dashboard:Start()
    if self.Destroyed or self.Started then
        return not self.Destroyed
    end

    self.Started = true
    self:RefreshUpdates(true)
    self:Collect()

    self.Connections[#self.Connections + 1] = RunService.Heartbeat:Connect(function(deltaTime)
        if deltaTime > 0 then
            local instant = 1 / deltaTime
            self.FPS = math_floor((self.FPS * 0.85) + (instant * 0.15) + 0.5)
        end
    end)

    task.spawn(function()
        while not self.Destroyed do
            task.wait(self.Interval)
            if not self.Destroyed then
                self:Collect()
            end
        end
    end)

    return true
end

function Dashboard:Get()
    return self.Data
end

function Dashboard:GetSnapshot()
    local snapshot = {}
    for key, value in pairs(self.Data) do
        snapshot[key] = value
    end
    return snapshot
end

function Dashboard:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false

    for _, connection in ipairs(self.Connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    self.Connections = {}
    self.Data = {}
end

return Dashboard


]],
    ["src/core/demon-ui.lua"] = [[
-- Shared DepHub shell, backed by the vendored RedzLib (src/dephubv2lib.lua).
--
-- Every game gets the exact same interface: the same library, the same size, the
-- same tab/section/control API. The backend of each game fills that shell with
-- its own tabs and controls -- the shell itself never knows which game it is
-- running and never adds anything game-specific.
--
-- RedzLib's own API is lower level than what the backends were written against:
--   * it has no "category" concept (DepHub groups tabs by purpose),
--   * `Tab:AddSection(title)` takes a bare string and is only a visual header --
--     controls are always appended to the TAB, not to the section,
--   * there is no row/stack container, no `Toggle()` and no dashboard builder.
--
-- This module is the adapter: it loads RedzLib and presents the stable DepHub
-- contract the backends, ui-kit, diagnostics and the loader already use, mapping
-- each call onto the RedzLib call that produces the same result.
--
-- Stable API handed to every backend through env.__DEPHUB.UI:
--   UI:CreateCategory(name, icon)          -- groups tabs by purpose
--   UI:CreateTab(name, category)           -- returns a tab wrapper or nil
--   tab:CreateSection(title, column)       -- "Left" (default) or "Right"
--   section:CreateToggle/Slider/Dropdown/Button/Input/Paragraph(...)
--   section:CreateRow() / section:CreateStack()   -- grouping handles
--   UI:Notify(title, message, kind)
--   UI:SetCurrentSea(sea)                  -- kept for compatibility; no-op filter
--   UI:Destroy()

local DemonUI = {}
DemonUI.__index = DemonUI

-- Window options shared by every game so the interface is identical everywhere.
-- Changing anything here changes it for all games at once.
local WINDOW_OPTIONS = {
    Title = "DepHub",
    SubTitle = "DepHub",
    Size = UDim2.fromOffset(900, 580),
    -- The global open/close key. RedzLib has no key toggle of its own, so the
    -- adapter binds this: N by default, rebindable per run through `options`.
    ToggleKey = Enum.KeyCode.N
}

-- The one category every game has. Backends that want more (the Blox Fruits
-- purpose groups) create them explicitly through CreateCategory.
local DEFAULT_CATEGORY = "General"

-- RedzLib lives in the repository as a normal, editable source file. It is not
-- fetched from a third-party URL: it is loaded through the same module path
-- everything else uses, so editing src/dephubv2lib.lua is editing the UI.
local LIBRARY_PATHS = {
    "src/dephubv2lib.lua",
    "dephubv2lib.lua"
}

local function fetchLibrarySource()
    local env = type(getgenv) == "function" and getgenv() or _G
    local resolver = (type(env.__dephubHttpGet) == "function" and env.__dephubHttpGet)
        or (type(env.__DEPHUB_HTTP_GET) == "function" and env.__DEPHUB_HTTP_GET)
        or (type(_G.__dephubHttpGet) == "function" and _G.__dephubHttpGet)
        or (type(_G.__DEPHUB_HTTP_GET) == "function" and _G.__DEPHUB_HTTP_GET)
    local base = (env.__DEPHUB and env.__DEPHUB.SourceBaseURL) or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
    for _, path in ipairs(LIBRARY_PATHS) do
        if resolver then
            local ok, source = pcall(resolver, base .. path)
            if ok and type(source) == "string" and #source > 0 then return source end
        end
        local ok, source = pcall(function() return __dephubHttpGet(base .. path) end)
        if ok and type(source) == "string" and #source > 0 then return source end
    end
    return nil
end

local cachedLibrary = nil

local function loadLibrary()
    if cachedLibrary then return cachedLibrary end
    local source = fetchLibrarySource()
    if type(source) ~= "string" or #source == 0 then
        error("Failed to load src/dephubv2lib.lua: no copy available")
    end
    local chunk, compileError = loadstring(source)
    if not chunk then error("Failed to compile dephubv2lib.lua: " .. tostring(compileError)) end
    local okRun, export = pcall(chunk)
    if not okRun or type(export) ~= "table" or type(export.MakeWindow) ~= "function" then
        error("dephubv2lib.lua did not return a valid library: " .. tostring(export))
    end
    cachedLibrary = export
    return export
end

-- ===========================================================================
-- Section wrapper
--
-- RedzLib has no section *container*: `Tab:AddSection(title)` returns a header
-- object and every control added afterwards lands below it on the tab. DepHub's
-- backends expect a section handle they can add controls to, so the wrapper
-- simply forwards each builder to the tab. Visually the result is identical:
-- the header is drawn, then the controls the backend adds for that section.
-- ===========================================================================

local function makeSection(adapter, tabHandle, title)
    local section = { Adapter = adapter, Control = tabHandle, Title = title }

    function section:CreateToggle(label, initial, callback)
        return tabHandle:AddToggle({
            Name = tostring(label),
            Default = initial == true,
            Callback = callback
        })
    end

    function section:CreateSlider(label, minimum, maximum, initial, callback)
        local lo = tonumber(minimum) or 0
        local hi = tonumber(maximum) or 100
        local start = tonumber(initial)
        if start == nil then start = lo end
        -- RedzLib requires min < max and a positive increment; derive a sane
        -- step from the range so callers keep passing plain numbers.
        local range = hi - lo
        local step = 1
        if range > 0 and range <= 1 then step = 0.01
        elseif range > 1000 then step = math.max(1, math.floor(range / 1000)) end
        if hi <= lo then hi = lo + step end
        return tabHandle:AddSlider({
            Name = tostring(label),
            Min = lo,
            Max = hi,
            Increment = step,
            Default = start,
            Callback = callback
        })
    end

    function section:CreateDropdown(label, options, initial, callback)
        local list = {}
        for _, option in ipairs(type(options) == "table" and options or {}) do
            list[#list + 1] = tostring(option)
        end
        if #list == 0 then list = { "None" } end
        local default = tostring(initial or list[1])
        return tabHandle:AddDropdown({
            Name = tostring(label),
            Options = list,
            Default = default,
            Callback = function(value) if callback then callback(value) end end
        })
    end

    function section:CreateButton(label, callback)
        return tabHandle:AddButton({
            Name = tostring(label),
            Callback = callback
        })
    end

    -- DepHub's input handle is a small record: `.Value` holds the current text
    -- and `.Control` is the underlying object (diagnostics clears it with
    -- `.Control:Set("")`). RedzLib's textbox exposes `Set`/`SetText`, so the
    -- handle simply forwards.
    function section:CreateInput(label, placeholder, initial, callback)
        local handle = { Value = tostring(initial or "") }
        handle.Control = tabHandle:AddTextBox({
            Name = tostring(label),
            Placeholder = tostring(placeholder or ""),
            Default = tostring(initial or ""),
            Callback = function(value)
                handle.Value = tostring(value or "")
                if callback then callback(value) end
            end
        })
        return handle
    end

    function section:CreateParagraph(titleText, bodyText)
        return tabHandle:AddParagraph(tostring(titleText or ""), tostring(bodyText or ""))
    end

    -- RedzLib stacks every control vertically and has no side-by-side container,
    -- so a "row" is a pass-through handle onto the same tab. The controls still
    -- render (stacked) and every backend call site keeps working unchanged.
    function section:CreateRow()
        return section
    end

    function section:CreateStack()
        return section
    end

    return section
end

-- ===========================================================================
-- Dashboard builders
--
-- The loader builds a fixed Dashboard tab for every game and calls two library
-- methods for it. RedzLib has neither, so the adapter provides them on top of
-- RedzLib primitives: a greeting/identity banner and a live metrics block. Both
-- keep the same signature the loader already calls.
-- ===========================================================================

local function greetingText()
    local hour = tonumber(os.date("%H")) or 12
    if hour >= 5 and hour < 12 then return "Good Morning"
    elseif hour >= 12 and hour < 17 then return "Good Afternoon"
    elseif hour >= 17 and hour < 20 then return "Good Evening"
    else return "Good Night" end
end

-- RedzLib does not expose the services it resolved; the adapter re-reads the two
-- the dashboard needs. Kept lazy so a missing service never breaks loading.
local Services = setmetatable({}, {
    __index = function(self, name)
        local ok, service = pcall(function() return game:GetService(name) end)
        local value = ok and service or nil
        rawset(self, name, value)
        return value
    end
})

local function installDashboardBuilders(adapter, library)
    -- Real RedzLib has no dashboard builders, so the adapter supplies them. A
    -- test double (or a future library that grows its own) already providing them
    -- keeps its implementation.
    if type(library.CreateDashboardBanner) ~= "function" then
        function library:CreateDashboardBanner(tabName)
            local record = adapter._tabByName[tabName]
            if not record or not record.Control then return nil end
            local player = Services.Players and Services.Players.LocalPlayer
            local displayName = "Player"
            if player then displayName = tostring(player.DisplayName or player.Name or "Player") end
            record.Control:AddSection("Dashboard")
            local banner = record.Control:AddParagraph(
                greetingText() .. ", " .. displayName,
                "Signed in to DepHub. Everything below is built live from this game."
            )
            return banner
        end
    end

    if type(library.CreatePerformanceDashboard) ~= "function" then
        function library:CreatePerformanceDashboard(tabName, columnName)
            local record = adapter._tabByName[tabName]
            if not record or not record.Control then return nil end
            local metrics = record.Control:AddParagraph("Performance", "Session started")
            local startedAt = os.clock()
            local runService = Services.RunService
            if runService and type(runService.RenderStepped) == "table" and type(runService.RenderStepped.Connect) == "function" then
                local lastFrame = os.clock()
                local frames = 0
                local accum = 0
                adapter._metricsConnection = runService.RenderStepped:Connect(function(deltaTime)
                    local now = os.clock()
                    frames = frames + 1
                    accum = accum + (tonumber(deltaTime) or (now - lastFrame))
                    lastFrame = now
                    if accum >= 1 then
                        local fps = math.floor(frames / accum)
                        local elapsed = now - startedAt
                        pcall(function()
                            metrics:SetTitle(string.format("Performance  ·  %d FPS", fps))
                            metrics:SetDescription(string.format("Session %02d:%02d:%02d", math.floor(elapsed / 3600), math.floor((elapsed % 3600) / 60), math.floor(elapsed % 60)))
                        end)
                        frames = 0
                        accum = 0
                    end
                end)
            end
            return metrics
        end
    end
end

-- ===========================================================================
-- Shell construction
-- ===========================================================================

function DemonUI.new(options)
    options = options or {}
    local library = loadLibrary()

    local window = library:MakeWindow({
        Title = options.Name or WINDOW_OPTIONS.Title,
        SubTitle = options.Version and ("v" .. tostring(options.Version)) or WINDOW_OPTIONS.SubTitle
    })

    local self = setmetatable({
        Library = library,
        Window = window,
        Tabs = {},
        Categories = {},
        CurrentSea = "Sea1",
        SearchQuery = "",
        Destroyed = false,
        _tabByName = {}
    }, DemonUI)

    self:CreateCategory(DEFAULT_CATEGORY, "layers")

    -- Keep RedzLib's dashboard builders on the library object so the loader's
    -- `window.Library:CreateDashboardBanner(...)` calls resolve.
    installDashboardBuilders(self, library)

    -- Open/close the panel without the keyboard. Some executers deliver
    -- InputBegan with gameProcessed=true, so the shell ignores the toggle key on
    -- purpose; this global flips the window's visibility directly and doubles as
    -- a probe (if __DEPHUB_TOGGLE() works but the key does not, it is the
    -- executor). RedzLib has no Toggle() of its own, so the adapter provides it.
    function library:Toggle()
        if self.Destroyed then return false end
        window:Minimize()
        return true
    end

    local env = type(getgenv) == "function" and getgenv() or _G
    env.__DEPHUB_TOGGLE = function()
        if self.Destroyed or not self.Library then return false end
        pcall(function() self.Library:Toggle() end)
        return true
    end

    -- The global open/close key (N by default). RedzLib has no key binding, so
    -- the adapter owns it: a keyboard InputBegan that is not game-processed (so
    -- typing in chat never toggles) flips the window. The connection is kept so
    -- Destroy can drop it.
    self.ToggleKey = options.ToggleKey or WINDOW_OPTIONS.ToggleKey
    do
        local ok, input = pcall(function() return game:GetService("UserInputService") end)
        if ok and input and type(input.InputBegan) == "table" and type(input.InputBegan.Connect) == "function" then
            self._toggleKeyConnection = input.InputBegan:Connect(function(io, gameProcessed)
                if gameProcessed then return end
                if self.Destroyed then return end
                if io.UserInputType ~= Enum.UserInputType.Keyboard then return end
                if io.KeyCode == self.ToggleKey then
                    pcall(function() self.Library:Toggle() end)
                end
            end)
        end
    end

    return self
end

-- Backends call this to add a category of their own. RedzLib has no category
-- concept, so the adapter records the group here; tabs keep the category name so
-- any consumer that inspects `tab.Category` still sees it. Idempotent. When the
-- underlying library happens to model categories (a test double, or a future
-- library), the call is forwarded so its own bookkeeping stays in step.
function DemonUI:CreateCategory(name, icon)
    name = tostring(name or DEFAULT_CATEGORY)
    if self.Categories[name] then return true end
    self.Categories[name] = true
    if type(self.Library.CreateCategory) == "function" then
        pcall(function() self.Library:CreateCategory(name, icon) end)
    end
    return true
end

function DemonUI:CreateTab(name, category)
    if self.Destroyed then return nil end
    name = tostring(name)
    category = tostring(category or DEFAULT_CATEGORY)
    if not self.Categories[category] then self:CreateCategory(category) end

    local existing = self.Tabs[category .. "|" .. name]
    if existing then return existing end

    -- RedzLib keys tabs by title, so a name has to be unique across the window.
    -- Two categories wanting a tab called "Farm" get distinct titles.
    local title = name
    if self._tabByName[title] then title = name .. " · " .. category end

    local ok, tabHandle = pcall(function() return self.Window:MakeTab({ Title = title }) end)
    if not ok or type(tabHandle) ~= "table" then
        return nil, tostring(tabHandle)
    end

    local record = {
        Adapter = self,
        Name = title,
        DisplayName = name,
        Category = category,
        Key = category .. "|" .. name,
        Control = tabHandle,
        Sections = {},
        Visible = true,
        Sea = nil
    }

    function record:CreateSection(sectionTitle, column)
        sectionTitle = tostring(sectionTitle or self.DisplayName)
        if self.Sections[sectionTitle] then return self.Sections[sectionTitle] end
        local handled = pcall(function() self.Control:AddSection(sectionTitle) end)
        if not handled then return nil end
        local wrapper = makeSection(self.Adapter, self.Control, sectionTitle)
        self.Sections[sectionTitle] = wrapper
        return wrapper
    end

    function record:SetVisible(visible)
        self.Visible = visible == true
        pcall(function() self.Control:SetVisible(self.Visible) end)
    end

    self.Tabs[record.Key] = record
    self._tabByName[title] = record
    return record
end

-- Sea filtering is kept for API compatibility. DepHub's backends do not call it
-- today; when they do, a tab scoped to a sea is simply hidden while another sea
-- is active. RedzLib hides a tab with Tab:SetVisible, which covers both its
-- button and its content page in one call.
function DemonUI:_tabMatchesSea(tab, sea)
    local scope = tab.Sea
    if scope == nil or scope == "" or scope == "All" then return true end
    local lower = tostring(scope):lower()
    if lower:find("sea1") and sea == "Sea1" then return true end
    if lower:find("sea2") and sea == "Sea2" then return true end
    if lower:find("sea3") and sea == "Sea3" then return true end
    return lower == tostring(sea):lower()
end

function DemonUI:_refreshVisibility()
    if self.Destroyed then return end
    local sea = self.CurrentSea
    for _, tab in pairs(self.Tabs) do
        local matches = self:_tabMatchesSea(tab, sea)
        local label = tostring(tab.DisplayName or tab.Name or ""):lower()
        local matchesQuery = self.SearchQuery == "" or label:find(self.SearchQuery, 1, true) ~= nil
        local visible = matches and matchesQuery
        tab.Visible = visible
        pcall(function() tab.Control:SetVisible(visible) end)
    end
end

function DemonUI:SetCurrentSea(sea)
    self.CurrentSea = tostring(sea or "Sea1")
    self:_refreshVisibility()
end

-- Feature search: hides tabs whose name does not contain the query. Combines
-- with the sea filter; an empty query matches everything.
function DemonUI:Search(query)
    self.SearchQuery = tostring(query or ""):lower()
    self:_refreshVisibility()
end

function DemonUI:Notify(title, message, kind)
    if self.Destroyed then return end
    pcall(function()
        self.Window:Notify({
            Title = tostring(title or "DepHub"),
            Content = tostring(message or ""),
            Duration = 4
        })
    end)
end

function DemonUI:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    if self._toggleKeyConnection then
        pcall(function() self._toggleKeyConnection:Disconnect() end)
        self._toggleKeyConnection = nil
    end
    if self._metricsConnection then
        pcall(function() self._metricsConnection:Disconnect() end)
        self._metricsConnection = nil
    end
    pcall(function() self.Library:Destroy() end)
    table.clear(self.Tabs)
    table.clear(self.Categories)
    table.clear(self._tabByName)
end

return DemonUI

]],
    ["src/core/diagnostics.lua"] = [[
-- Shared DepHub live diagnostics console.
--
-- One Debug tab, identical in every game, that behaves like a real terminal:
-- it keeps itself current instead of showing a snapshot, and it listens to
-- both the hub and the game.
--
-- Listeners (read-only; they never modify the game's own scripts):
--   * global log hooks    -- warn/print routed through a capture buffer
--   * ScriptContext.Error -- engine/script errors from the running game
--   * live metrics        -- FPS, ping, memory, uptime, entity counts
--   * structure watch     -- titans/resources entering and leaving
--   * remote sniffer      -- every GET/POST the hub sends, with arguments
--
-- API used by the loader and backends:
--   Diag:SetEnvironment(t)         -- executor/place/version snapshot
--   Diag:Module(name, ok, detail)  -- module load outcome
--   Diag:RegisterModule(name)      -- declare a module before it reports
--   Diag:Probe(label, ok, detail)  -- game-structure probe result
--   Diag:Feature(name, reader)     -- live value, polled for the console
--   Diag:Watch(label, reader)      -- watched value; changes become log lines
--   Diag:Note(text)                -- free-form line
--   Diag:Log(kind, text)           -- capture a log line
--   Diag:Command(name, handler)    -- register a console command
--   Diag:Install(ui)               -- build the live Debug console
--   Diag:Report() / Diag:Copy()    -- whole snapshot as text
--
-- Every collector is pcall-guarded: a probe, feature or hook that throws is
-- shown as an error line instead of taking the hub (or the game) down.
local Diagnostics = {}
Diagnostics.__index = Diagnostics

local MAX_LOG = 400
local REFRESH = 0.5

local function envTable()
    return type(getgenv) == "function" and getgenv() or _G
end

local function safe(...)
    return select(2, pcall(...))
end

-- Capture the environment this chunk was loaded into while we are still at
-- top level. Luau's getfenv() answers for the *calling* function, so a call
-- made later from inside a method can resolve to a different table than the
-- one the chunk actually runs in. Reading it once, here, gives us the real
-- holder for warn/print in every environment (executor globals or a host
-- that ran the chunk under setfenv).
--
-- Note: the probe runs inside its own closure on purpose. Calling getfenv
-- itself as the pcall target would answer for pcall's C frame, not the chunk.
local LOAD_ENV
do
    local ok, captured = pcall(function() return getfenv() end)
    if ok and type(captured) == "table" then LOAD_ENV = captured end
end

local function now()
    return os.clock()
end

local function clockString(seconds)
    seconds = math.max(0, math.floor(seconds or 0))
    return string.format("%02d:%02d:%02d", math.floor(seconds / 3600), math.floor(seconds % 3600 / 60), seconds % 60)
end

function Diagnostics.new()
    local self = setmetatable({
        Environment = {},
        Modules = {}, ModuleOrder = {},
        Probes = {}, ProbeOrder = {},
        Features = {}, FeatureOrder = {},
        Watches = {}, WatchOrder = {}, WatchValues = {},
        Notes = {},
        Logs = {},
        LogPaused = false,
        SniffEnabled = true,
        RemoteLog = {},
        Hooks = {},
        Commands = {},
        StartedAt = now(),
        Metrics = {FPS = 0, Ping = 0, Memory = 0, Uptime = 0, Titans = 0},
        Installed = false,
        Tab = nil,
        RenderTask = nil,
        Destroyed = false
    }, Diagnostics)
    self:_registerBuiltins()
    return self
end

local function pushUnique(list, value)
    if not table.find(list, value) then list[#list + 1] = value end
end

-- ---------------------------------------------------------------------------
-- Data collection
-- ---------------------------------------------------------------------------

function Diagnostics:SetEnvironment(values)
    if type(values) ~= "table" then return end
    for key, value in pairs(values) do self.Environment[tostring(key)] = tostring(value) end
end

function Diagnostics:RegisterModule(name)
    name = tostring(name)
    pushUnique(self.ModuleOrder, name)
    if self.Modules[name] == nil then self.Modules[name] = {Ok = nil, Detail = "pending"} end
    return name
end

function Diagnostics:Module(name, ok, detail)
    name = tostring(name)
    pushUnique(self.ModuleOrder, name)
    self.Modules[name] = {Ok = ok == true, Detail = detail ~= nil and tostring(detail) or (ok and "ok" or "no detail")}
    self:_addLog("module", (ok and "[OK] " or "[FAIL] ") .. name .. ": " .. self.Modules[name].Detail)
end

function Diagnostics:Probe(label, ok, detail)
    label = tostring(label)
    pushUnique(self.ProbeOrder, label)
    self.Probes[label] = {Ok = ok == true, Detail = detail ~= nil and tostring(detail) or (ok and "ok" or "absent")}
end

function Diagnostics:Feature(name, reader)
    name = tostring(name)
    pushUnique(self.FeatureOrder, name)
    self.Features[name] = reader
end

-- A watch polls its reader on the console loop and writes a log line whenever
-- the value changes, so structure changes (a titan spawning, a remote leaving)
-- become timestamped events instead of a value you have to stare at.
function Diagnostics:Watch(label, reader)
    label = tostring(label)
    pushUnique(self.WatchOrder, label)
    self.Watches[label] = reader
end

function Diagnostics:Note(text)
    self.Notes[#self.Notes + 1] = tostring(text)
end

function Diagnostics:Command(name, handler)
    self.Commands[tostring(name)] = handler
end

-- ---------------------------------------------------------------------------
-- Log capture + hooks
-- ---------------------------------------------------------------------------

local function stamp()
    return string.format("%6.2f", now() % 100000)
end

function Diagnostics:_addLog(kind, text)
    if self.LogPaused and kind ~= "console" then return end
    self.Logs[#self.Logs + 1] = {Kind = tostring(kind or "log"), Text = tostring(text), T = stamp()}
    while #self.Logs > MAX_LOG do table.remove(self.Logs, 1) end
end

function Diagnostics:Log(kind, text)
    self:_addLog(kind, text)
end

-- Wrap the executor's warn/print so everything the hub *and the game* prints is
-- captured. The originals are always called, so nothing is swallowed.
function Diagnostics:_installLogHooks()
    if self.Hooks.warn or self.Hooks.print then return end
    -- Candidate holders, in priority order: the table the chunk was loaded
    -- into (always correct), the shared executor globals, and the raw _G.
    local holders = {}
    local seen = {}
    local function add(table_)
        if type(table_) == "table" and not seen[table_] then
            seen[table_] = true
            holders[#holders + 1] = table_
        end
    end
    add(LOAD_ENV)
    add(envTable())
    add(_G)
    for _, name in ipairs({"warn", "print"}) do
        -- Hook every holder that currently exposes the function, so a line
        -- emitted by the hub or by the game is captured no matter which table
        -- it resolves through. The first one found is the reference the
        -- wrapper forwards to.
        local original
        for _, holder in ipairs(holders) do
            if type(holder[name]) == "function" then
                original = original or holder[name]
                break
            end
        end
        if original then
            local wrapped = function(...)
                local parts = {}
                for i = 1, select("#", ...) do parts[i] = tostring(select(i, ...)) end
                self:_addLog(name, table.concat(parts, " "))
                return original(...)
            end
            local installed = {}
            for _, holder in ipairs(holders) do
                if type(holder[name]) == "function" then
                    pcall(function() holder[name] = wrapped end)
                    installed[#installed + 1] = holder
                end
            end
            self.Hooks[name] = {Original = original, Holders = installed, Wrapped = wrapped}
        end
    end
    -- ScriptContext.Error reports errors raised by scripts running in this
    -- client, including the game's own. We only listen.
    local ok, scriptContext = pcall(function() return game:GetService("ScriptContext") end)
    if ok and scriptContext and scriptContext.Error and not self.Hooks.ScriptContext then
        local connection = scriptContext.Error:Connect(function(message, stack)
            self:_addLog("error", tostring(message) .. (stack and ("\n" .. tostring(stack)) or ""))
        end)
        self.Hooks.ScriptContext = connection
    end
end

function Diagnostics:_removeLogHooks()
    local env = envTable()
    local restore = env.restorefunction or _G.restorefunction
    for name, hook in pairs(self.Hooks) do
        if name == "ScriptContext" then
            pcall(function() hook:Disconnect() end)
        elseif type(hook) == "table" and hook.Holders then
            for _, holder in ipairs(hook.Holders) do
                pcall(function() holder[name] = hook.Original end)
            end
        elseif type(hook) == "table" then
            -- Remote sniffer record: undo executor hooks and field patches.
            if hook.Restores and type(restore) == "function" then
                for _, handle in ipairs(hook.Restores) do pcall(restore, handle) end
            end
            for _, patch in ipairs(hook.Fields or {}) do
                pcall(function() rawset(patch.Remote, patch.Name, patch.Original) end)
            end
        end
    end
    self.Hooks = {}
end

-- Wrap a remote so every invocation the hub makes is logged with its arguments.
-- The wrapping is transparent: the original call is forwarded untouched.
--
-- Real Roblox Instances keep their methods on a shared metatable, so a plain
-- field assignment does not override InvokeServer/FireServer. The sniffer
-- therefore prefers an executor's hooking primitive (hookfunction /
-- replaceclosure) when one is present, and only falls back to a field patch
-- for plain-function doubles that accept one.
function Diagnostics:SniffRemote(remote, label)
    if not remote then return end
    label = tostring(label)
    local key = "remote:" .. label
    if self.Hooks[key] then return end

    local env = envTable()
    local hook = env.hookfunction or _G.hookfunction
    local restore = env.restorefunction or _G.restorefunction
    local record = {Restores = {}, Fields = {}}
    self.Hooks[key] = record

    -- Reading a method that does not exist on the Instance's type raises
    -- ("FireServer is not a valid member of RemoteFunction"), so every method
    -- read goes through pcall. A RemoteFunction exposes InvokeServer and a
    -- RemoteEvent exposes FireServer; whichever is absent simply yields nil.
    for _, name in ipairs({"InvokeServer", "FireServer"}) do
        local okRead, method = pcall(function() return remote[name] end)
        if okRead and type(method) == "function" then
            local verb = name == "InvokeServer" and "GET " or "POST "
            local wrapped = function(instance, ...)
                self:_addLog("remote", verb .. label .. "(" .. self:_fmtArgs(...) .. ")")
                return method(instance, ...)
            end
            if type(hook) == "function" then
                -- Executor hooking: swap the closure and keep the handle for
                -- restorefunction on teardown.
                local handle
                local ok = pcall(function() handle = hook(method, wrapped) end)
                if ok and handle ~= nil then
                    record.Restores[#record.Restores + 1] = handle
                else
                    self:_addLog("remote", "could not hook " .. name .. " of " .. label)
                end
            elseif rawget(remote, name) == method then
                -- Plain-function double: patch the own field only, and only
                -- when no metatable shadows it.
                record.Fields[#record.Fields + 1] = {Remote = remote, Name = name, Original = method}
                pcall(function() rawset(remote, name, wrapped) end)
            end
        end
    end
    if type(restore) ~= "function" then record.Restores = nil end
end

function Diagnostics:_fmtArgs(...)
    local parts = {}
    for i = 1, select("#", ...) do
        local value = select(i, ...)
        local kind = type(value)
        if kind == "string" or kind == "number" or kind == "boolean" then
            parts[i] = tostring(value)
        elseif typeof(value) == "Instance" then
            parts[i] = tostring(value.ClassName) .. ":" .. tostring(value.Name)
        elseif typeof(value) == "Vector3" then
            parts[i] = string.format("(%.1f,%.1f,%.1f)", value.X, value.Y, value.Z)
        else
            parts[i] = kind
        end
    end
    return table.concat(parts, ", ")
end

-- ---------------------------------------------------------------------------
-- Metrics
-- ---------------------------------------------------------------------------

-- Resolve a child by name without raising when the member is absent. A raw
-- index like stats.FrameStats throws on executors where the member is not
-- exposed, so every optional read goes through FindFirstChild.
local function child(object, name)
    if not object then return nil end
    local ok, found = pcall(function() return object:FindFirstChild(name) end)
    return ok and found or nil
end

function Diagnostics:_collectMetrics()
    local metrics = self.Metrics
    local okStats, stats = pcall(function() return game:GetService("Stats") end)

    -- FPS: executors expose FrameStats.FrameRate differently. It may be a value
    -- object read via GetValue() or .Value, and some runtimes keep it under
    -- RenderStats instead. Try each route, then fall back to the physics frame
    -- rate the engine reports, so the metric is never stuck at 0 -- and this
    -- runs even when Stats is unavailable.
    local fps
    if okStats and stats then
        local frame = child(stats, "FrameStats") or child(stats, "RenderStats")
        if frame then
            local rate = child(frame, "FrameRate")
            if rate then
                fps = safe(function() return rate:GetValue() end)
                if type(fps) ~= "number" then fps = safe(function() return rate.Value end) end
            end
        end
    end
    if type(fps) ~= "number" then
        fps = safe(function() return workspace:GetRealPhysicsFPS() end)
    end
    if type(fps) == "number" and fps > 0 then metrics.FPS = fps end

    if okStats and stats then
        local network = child(stats, "Network")
        local serverStats = network and child(network, "ServerStatsItem")
        local pingItem = serverStats and child(serverStats, "Data Ping")
        if pingItem then
            local ping = safe(function() return pingItem:GetValue() end)
            if type(ping) ~= "number" then ping = safe(function() return pingItem.Value end) end
            if type(ping) == "number" then metrics.Ping = ping end
        end
        local memory = safe(function() return stats:GetTotalMemoryUsageMb() end)
        if type(memory) == "number" then metrics.Memory = memory end
    end
    metrics.Uptime = now() - self.StartedAt

    -- Entity counts come from whatever the active backend opted to watch; a
    -- generic fallback keeps the console useful before a backend reports.
    local okWorkspace, ws = pcall(function() return game:GetService("Workspace") end)
    if okWorkspace and ws then
        local titans = child(ws, "Titans")
        local count = titans and safe(function() return #titans:GetChildren() end)
        if type(count) == "number" then metrics.Titans = count end
    end
    return metrics
end

function Diagnostics:_pollWatches()
    if self.Destroyed then return end
    for _, label in ipairs(self.WatchOrder) do
        local reader = self.Watches[label]
        if type(reader) == "function" then
            local ok, value = pcall(reader)
            local text = ok and tostring(value) or ("ERRO: " .. tostring(value))
            if self.WatchValues[label] ~= text then
                if self.WatchValues[label] ~= nil then self:_addLog("watch", label .. ": " .. self.WatchValues[label] .. " -> " .. text) end
                self.WatchValues[label] = text
            end
        end
    end
end

-- ---------------------------------------------------------------------------
-- Built-in console commands
-- ---------------------------------------------------------------------------

function Diagnostics:_registerBuiltins()
    self:Command("help", function() return "commands: " .. self:_commandList() end)
    self:Command("clear", function() self.Logs = {}; return "log cleared" end)
    self:Command("pause", function() self.LogPaused = true; return "log paused" end)
    self:Command("resume", function() self.LogPaused = false; return "log resumed" end)
    self:Command("report", function() return "full report: use the Copy report button" end)
    self:Command("modules", function()
        local parts = {}
        for _, name in ipairs(self.ModuleOrder) do
            local record = self.Modules[name]
            parts[#parts + 1] = (record and (record.Ok == true and "ok " or record.Ok == false and "FAIL " or "? ") or "? ") .. name
        end
        return table.concat(parts, " | ")
    end)
    self:Command("probes", function()
        local parts = {}
        for _, label in ipairs(self.ProbeOrder) do
            local record = self.Probes[label]
            if record then parts[#parts + 1] = label .. "=" .. tostring(record.Ok and "ok" or "absent") end
        end
        return table.concat(parts, " | ")
    end)
    self:Command("features", function()
        local parts = {}
        for _, name in ipairs(self.FeatureOrder) do
            local reader = self.Features[name]
            if type(reader) == "function" then
                local ok, value = pcall(reader)
                parts[#parts + 1] = name .. "=" .. (ok and tostring(value) or "ERROR")
            end
        end
        return table.concat(parts, " | ")
    end)
    self:Command("sniff", function(argument)
        if argument == "on" then self.SniffEnabled = true return "remote sniffing on"
        elseif argument == "off" then self.SniffEnabled = false return "remote sniffing off" end
        return "usage: sniff on|off (current: " .. tostring(self.SniffEnabled) .. ")"
    end)
    self:Command("env", function()
        local parts = {}
        for key, value in pairs(self.Environment) do parts[#parts + 1] = key .. "=" .. tostring(value) end
        table.sort(parts)
        return table.concat(parts, " | ")
    end)
    self:Command("metrics", function()
        local metrics = self:_collectMetrics()
        return string.format("fps=%.0f ping=%.0fms memory=%.1fMB uptime=%s titans=%d",
            metrics.FPS, metrics.Ping, metrics.Memory, clockString(metrics.Uptime), metrics.Titans)
    end)
end

function Diagnostics:_commandList()
    local names = {}
    for name in pairs(self.Commands) do names[#names + 1] = name end
    table.sort(names)
    return table.concat(names, ", ")
end

function Diagnostics:RunCommand(text)
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return "" end
    local name, argument = text:match("^(%S+)%s*(.*)$")
    self:_addLog("cmd", "> " .. text)
    local handler = self.Commands[name]
    if not handler then
        local message = "unknown command: " .. name .. " (" .. self:_commandList() .. ")"
        self:_addLog("console", message)
        return message
    end
    local ok, result = pcall(handler, argument ~= "" and argument or nil)
    local message = ok and tostring(result or "ok") or ("error: " .. tostring(result))
    self:_addLog("console", message)
    return message
end

-- ---------------------------------------------------------------------------
-- Rendering
-- ---------------------------------------------------------------------------

local function statusMark(ok)
    if ok == true then return "[OK]" end
    if ok == false then return "[FAIL]" end
    return "[?]"
end

function Diagnostics:MetricsLine()
    local metrics = self:_collectMetrics()
    return string.format("FPS %3.0f | ping %3.0fms | mem %.0fMB | uptime %s | titans %d",
        metrics.FPS, metrics.Ping, metrics.Memory, clockString(metrics.Uptime), metrics.Titans)
end

function Diagnostics:Report()
    if self.Destroyed then return "diagnostics stopped" end
    local ok, text = pcall(function() return self:_render() end)
    return ok and text or ("DepHub diagnostics: failed to build the report: " .. tostring(text))
end

function Diagnostics:_render()
    local lines = {}
    lines[#lines + 1] = "===== DepHub console ====="
    lines[#lines + 1] = "active module: " .. tostring((envTable().__DEPHUB or {}).Mode or "?")
    lines[#lines + 1] = self:MetricsLine()
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Environment --"
    local envKeys = {}
    for key in pairs(self.Environment) do envKeys[#envKeys + 1] = key end
    table.sort(envKeys)
    for _, key in ipairs(envKeys) do lines[#lines + 1] = key .. ": " .. self.Environment[key] end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Modules --"
    for _, name in ipairs(self.ModuleOrder) do
        local record = self.Modules[name]
        if record then lines[#lines + 1] = statusMark(record.Ok) .. " " .. name .. ": " .. tostring(record.Detail) end
    end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Game structure --"
    for _, label in ipairs(self.ProbeOrder) do
        local record = self.Probes[label]
        if record then lines[#lines + 1] = statusMark(record.Ok) .. " " .. label .. ": " .. tostring(record.Detail) end
    end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Feature state (live) --"
    for _, name in ipairs(self.FeatureOrder) do
        local reader = self.Features[name]
        if type(reader) == "function" then
            local ok, value = pcall(reader)
            lines[#lines + 1] = name .. ": " .. (ok and tostring(value) or ("READ ERROR: " .. tostring(value)))
        end
    end
    lines[#lines + 1] = ""

    if #self.WatchOrder > 0 then
        lines[#lines + 1] = "-- Watches --"
        for _, label in ipairs(self.WatchOrder) do lines[#lines + 1] = label .. ": " .. tostring(self.WatchValues[label] or "?") end
        lines[#lines + 1] = ""
    end

    if #self.Notes > 0 then
        lines[#lines + 1] = "-- Notes --"
        for _, note in ipairs(self.Notes) do lines[#lines + 1] = note end
        lines[#lines + 1] = ""
    end

    lines[#lines + 1] = "-- Log (" .. tostring(#self.Logs) .. " of " .. tostring(MAX_LOG) .. ") --"
    for _, entry in ipairs(self.Logs) do lines[#lines + 1] = "[" .. entry.T .. "][" .. entry.Kind .. "] " .. entry.Text end
    return table.concat(lines, "\n")
end

function Diagnostics:LogText()
    local lines = {}
    for _, entry in ipairs(self.Logs) do lines[#lines + 1] = "[" .. entry.T .. "][" .. entry.Kind .. "] " .. entry.Text end
    return table.concat(lines, "\n")
end

function Diagnostics:Summary()
    local okM, failM, pendM = 0, 0, 0
    for _, name in ipairs(self.ModuleOrder) do
        local record = self.Modules[name]
        if record then
            if record.Ok == true then okM = okM + 1
            elseif record.Ok == false then failM = failM + 1
            else pendM = pendM + 1 end
        end
    end
    local okP, failP = 0, 0
    for _, label in ipairs(self.ProbeOrder) do
        local record = self.Probes[label]
        if record then
            if record.Ok == true then okP = okP + 1 else failP = failP + 1 end
        end
    end
    return string.format("modules %d ok / %d fail / %d pending | structure %d ok / %d absent | features %d | log %d",
        okM, failM, pendM, okP, failP, #self.FeatureOrder, #self.Logs)
end

function Diagnostics:Copy()
    local text = self:Report()
    local env = envTable()
    local copied = false
    for _, name in ipairs({"setclipboard", "toclipboard", "Clipboard"}) do
        local fn = (env and env[name]) or _G[name]
        if type(fn) == "function" then
            local ok = pcall(fn, text)
            if ok then copied = true break end
        end
    end
    pcall(print, text)
    return copied, text
end

-- ---------------------------------------------------------------------------
-- Live console UI
-- ---------------------------------------------------------------------------

function Diagnostics:_refreshViews()
    if self.Destroyed then return end
    if self.MetricsParagraph then pcall(function() self.MetricsParagraph:Set(nil, self:MetricsLine()) end) end
    if self.ReportParagraph then pcall(function() self.ReportParagraph:Set(nil, self:Report()) end) end
    if self.LogParagraph then pcall(function() self.LogParagraph:Set(nil, self:LogText()) end) end
end

function Diagnostics:Install(ui)
    if self.Installed or type(ui) ~= "table" or type(ui.CreateTab) ~= "function" then return false end
    local tab = ui:CreateTab("Debug", "All")
    if not tab then return false end
    self.Tab = tab
    self.UI = ui

    local live = tab:CreateSection("Live", "Left")
    if live then
        self.MetricsParagraph = live:CreateParagraph("Metrics", self:MetricsLine())
        if type(self.MetricsParagraph.Set) ~= "function" then self.MetricsParagraph = nil end
        self.ReportParagraph = live:CreateParagraph("State", self:Report())
        if type(self.ReportParagraph.Set) ~= "function" then self.ReportParagraph = nil end
    end

    local controls = tab:CreateSection("Controls", "Left")
    if controls then
        self.LogParagraph = controls:CreateParagraph("Log", self:LogText())
        if type(self.LogParagraph.Set) ~= "function" then self.LogParagraph = nil end
        controls:CreateToggle("Remote sniff", self.SniffEnabled, function(value) self.SniffEnabled = value == true end)
        controls:CreateToggle("Pause log", false, function(value) self.LogPaused = value == true end)
        controls:CreateButton("Clear log", function() self.Logs = {}; self:_refreshViews() end)
        controls:CreateButton("Copy report (clipboard + console)", function()
            local copied = self:Copy()
            if type(ui.Notify) == "function" then
                ui:Notify("Debug", copied and "Report copied." or "Report sent to the console (clipboard unavailable).")
            end
            self:_refreshViews()
        end)
    end

    local terminal = tab:CreateSection("Terminal", "Right")
    if terminal then
        self.CommandInput = terminal:CreateInput("Command", "type and click Run (help)", "", function() end)
        terminal:CreateButton("Run", function()
            local value = self.CommandInput and self.CommandInput.Value or ""
            self:RunCommand(value)
            if self.CommandInput then pcall(function() self.CommandInput.Control:Set("") end) end
            self:_refreshViews()
        end)
        terminal:CreateParagraph("Commands", self:_commandList())
    end

    self.Installed = true
    self:_installLogHooks()
    -- A single refresh loop keeps every view current; it stops with Destroy.
    self.RenderTask = task.spawn(function()
        while not self.Destroyed do
            task.wait(REFRESH)
            if self.Destroyed then return end
            local ok, err = pcall(function()
                self:_pollWatches()
                self:_refreshViews()
            end)
            if not ok then self:_addLog("console", "loop: " .. tostring(err)) end
        end
    end)
    self:_addLog("console", "debug console started")
    return true
end

function Diagnostics:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self:Uninstall()
end

-- Detach the UI tab and the log hooks while keeping the collector alive, so the
-- data keeps accumulating and Install can bring the tab back later. Destroy
-- builds on this and additionally marks the collector as gone.
function Diagnostics:Uninstall()
    if self.RenderTask then pcall(task.cancel, self.RenderTask); self.RenderTask = nil end
    self:_removeLogHooks()
    self.Installed = false
    self.Tab = nil
    self.UI = nil
    self.MetricsParagraph = nil
    self.ReportParagraph = nil
    self.LogParagraph = nil
    self.CommandInput = nil
end

return Diagnostics

