    ["src/core/health-monitor.lua"] = [[
local task = task
local type = type
local tostring = tostring
local pcall = pcall
local os_clock = os.clock

local HealthMonitor = {}
HealthMonitor.__index = HealthMonitor

function HealthMonitor.new(options)
    options = options or {}

    local self = setmetatable({}, HealthMonitor)
    self.Destroyed = false
    self.Started = false
    self.Interval = math.max(tonumber(options.Interval) or 2, 0.25)
    self.MaxErrors = tonumber(options.MaxErrors) or 5
    self.Checks = {}
    self.Results = {}
    self.ErrorCount = 0
    self.LastError = nil
    self.Status = "Healthy"
    self.StartedAt = os_clock()
    self.OnChanged = options.OnChanged
    return self
end

function HealthMonitor:Register(name, callback)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return false
    end

    self.Checks[name] = {
        Callback = callback,
        Errors = 0,
        Failures = 0,
        LastRun = 0,
        LastSuccess = 0,
        LastError = nil,
        Healthy = true
    }

    return true
end

-- A check that returns false is a normal negative report; only a raised error is a
-- fault. Conflating the two made a legitimately-false check look permanently
-- Unhealthy once it crossed MaxErrors.
function HealthMonitor:RunCheck(name, check)
    local ok, result = pcall(check.Callback, check)
    check.LastRun = os_clock()

    if not ok then
        check.Errors = check.Errors + 1
        check.LastError = tostring(result)
        check.Healthy = false
        self.ErrorCount = self.ErrorCount + 1
        self.LastError = check.LastError
        self.Results[name] = false
        return false
    end

    check.Errors = 0
    check.LastError = nil
    if result == false then
        check.Failures = check.Failures + 1
        check.Healthy = false
    else
        check.Failures = 0
        check.Healthy = true
        check.LastSuccess = os_clock()
    end
    self.Results[name] = check.Healthy
    return check.Healthy
end

function HealthMonitor:Evaluate()
    if self.Destroyed then
        self.Status = "Destroyed"
        return self.Status
    end

    local unhealthy = 0
    local registered = 0

    for name, check in pairs(self.Checks) do
        registered = registered + 1
        if not self:RunCheck(name, check) then
            unhealthy = unhealthy + 1
        end
    end

    if registered == 0 then
        self.Status = "Healthy"
    elseif unhealthy == 0 then
        self.Status = "Healthy"
    elseif unhealthy < registered then
        self.Status = "Degraded"
    else
        self.Status = "Unhealthy"
    end

    if self.OnChanged then
        pcall(self.OnChanged, self.Status, self.Results)
    end

    return self.Status
end

function HealthMonitor:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true

    task.spawn(function()
        while not self.Destroyed do
            self:Evaluate()
            -- Jitter the evaluation cadence so the health loop is not perfectly periodic.
            task.wait(self.Interval * (1 + (math.random() * 2 - 1) * 0.15))
        end
    end)

    return true
end

function HealthMonitor:GetSnapshot()
    local checks = {}

    for name, check in pairs(self.Checks) do
        checks[name] = {
            Healthy = check.Healthy,
            Errors = check.Errors,
            Failures = check.Failures,
            LastError = check.LastError,
            LastRun = check.LastRun,
            LastSuccess = check.LastSuccess
        }
    end

    return {
        Status = self.Status,
        ErrorCount = self.ErrorCount,
        LastError = self.LastError,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        Checks = checks
    }
end

function HealthMonitor:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false
    self.Checks = {}
    self.Results = {}
    self.Status = "Destroyed"
end

return HealthMonitor

]],
    ["src/core/runtime.lua"] = [[
local type = type
local tostring = tostring
local pcall = pcall
local tonumber = tonumber
local pairs = pairs
local os_clock = os.clock

local Runtime = {}
Runtime.__index = Runtime

function Runtime.new(options)
    options = options or {}

    local Scheduler = options.Scheduler
    local HealthMonitor = options.HealthMonitor
    local Dashboard = options.Dashboard

    local self = setmetatable({}, Runtime)
    self.Destroyed = false
    self.Started = false
    self.StartedAt = os_clock()
    self.ErrorCount = 0
    self.LastError = nil
    self.Health = "Healthy"
    self.Events = {}
    local schedulerOptions = {}
    local providedSchedulerOptions = options.SchedulerOptions
    if type(providedSchedulerOptions) == "table" then
        for key, value in pairs(providedSchedulerOptions) do schedulerOptions[key] = value end
    end
    local previousOnError = schedulerOptions.OnError
    schedulerOptions.OnError = function(state, message)
        self.ErrorCount = self.ErrorCount + 1
        self.LastError = message
        self:Emit("TaskError", state, message)
        if type(previousOnError) == "function" then pcall(previousOnError, state, message) end
    end
    self.Scheduler = type(Scheduler) == "table" and Scheduler.new(schedulerOptions) or nil
    self.HealthMonitor = type(HealthMonitor) == "table" and HealthMonitor.new(options.HealthOptions or {}) or nil
    self.Dashboard = type(Dashboard) == "table" and Dashboard.new(options.DashboardOptions or {}) or nil
    return self
end

function Runtime:On(name, callback)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return function() end
    end

    local listeners = self.Events[name]
    if not listeners then
        listeners = {}
        self.Events[name] = listeners
    end

    local connection = {Connected = true, Callback = callback}
    listeners[connection] = true

    return function()
        if not connection.Connected then
            return
        end
        connection.Connected = false
        listeners[connection] = nil
    end
end

function Runtime:Emit(name, ...)
    if self.Destroyed then
        return
    end

    local listeners = self.Events[name]
    if not listeners then
        return
    end

    for connection in pairs(listeners) do
        if connection.Connected then
            pcall(connection.Callback, ...)
        end
    end
end

function Runtime:Register(name, callback, options)
    if self.Destroyed or not self.Scheduler then
        return nil
    end

    local state = self.Scheduler:Register(name, callback, options)
    if state then
        self:Emit("TaskRegistered", state)
    end
    return state
end

function Runtime:SetEnabled(name, enabled)
    if self.Destroyed or not self.Scheduler then
        return false
    end
    return self.Scheduler:SetEnabled(name, enabled)
end

function Runtime:IsEnabled(name)
    return self.Scheduler ~= nil and self.Scheduler:Get(name) ~= nil and self.Scheduler:Get(name).Enabled == true
end

function Runtime:GetTask(name)
    if not self.Scheduler then
        return nil
    end
    return self.Scheduler:Get(name)
end

function Runtime:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true
    self.StartedAt = os_clock()

    if self.Dashboard then
        self.Dashboard:Start()
    end

    if self.HealthMonitor then
        self.HealthMonitor:Start()
    end

    if self.Scheduler then
        self.Scheduler:Start()
    end

    self:Emit("Started")
    return true
end

function Runtime:GetSnapshot()
    local schedulerSnapshot = self.Scheduler and self.Scheduler:GetSnapshot() or {}
    local healthSnapshot = self.HealthMonitor and self.HealthMonitor:GetSnapshot() or {Status = "Unavailable"}
    local dashboardSnapshot = self.Dashboard and self.Dashboard:GetSnapshot() or {}

    self.Health = healthSnapshot.Status or "Unknown"

    return {
        Health = self.Health,
        Started = self.Started,
        StartedAt = self.StartedAt,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        ErrorCount = self.ErrorCount,
        LastError = self.LastError,
        Tasks = schedulerSnapshot,
        HealthMonitor = healthSnapshot,
        Dashboard = dashboardSnapshot
    }
end

function Runtime:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false

    if self.Scheduler then
        pcall(self.Scheduler.Destroy, self.Scheduler)
    end

    if self.HealthMonitor then
        pcall(self.HealthMonitor.Destroy, self.HealthMonitor)
    end

    if self.Dashboard then
        pcall(self.Dashboard.Destroy, self.Dashboard)
    end

    self.Scheduler = nil
    self.HealthMonitor = nil
    self.Dashboard = nil
    self.Events = {}
    self.Health = "Destroyed"
end

return Runtime

]],
    ["src/core/scheduler.lua"] = [[
local task = task
local type = type
local tostring = tostring
local pcall = pcall
local os_clock = os.clock

local Scheduler = {}
Scheduler.__index = Scheduler

function Scheduler.new(options)
    options = options or {}

    local self = setmetatable({}, Scheduler)
    self.Tasks = {}
    self.Order = {}
    self.Destroyed = false
    self.Started = false
    self.NextId = 0
    self.DefaultInterval = tonumber(options.DefaultInterval) or 0.1
    self.MaxErrors = tonumber(options.MaxErrors) or 5
    self.OnError = type(options.OnError) == "function" and options.OnError or nil
    return self
end

-- Re-registering an existing name must not silently keep the stale callback:
-- backends re-register tasks after respawns with fresh upvalues. Swap the body in
-- place, bump the version (which retires the current thread) and restart if live.
function Scheduler:Register(name, callback, options)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return nil
    end

    local existing = self.Tasks[name]
    if existing then
        existing.Callback = callback
        existing.Version = existing.Version + 1
        existing.Started = false
        if options then
            if options.Interval ~= nil then existing.Interval = math.max(tonumber(options.Interval) or existing.Interval, 0.01) end
            if options.Priority ~= nil then existing.Priority = tonumber(options.Priority) or existing.Priority end
            if options.Enabled ~= nil then existing.Enabled = options.Enabled ~= false end
        end
        if self.Started and existing.Enabled then
            self:StartTask(existing)
        end
        return existing
    end

    options = options or {}
    self.NextId = self.NextId + 1

    local state = {
        Id = self.NextId,
        Name = name,
        Callback = callback,
        Interval = math.max(tonumber(options.Interval) or self.DefaultInterval, 0.01),
        Priority = tonumber(options.Priority) or 0,
        Enabled = options.Enabled ~= false,
        Running = false,
        Errors = 0,
        LastError = nil,
        LastRun = 0,
        LastSuccess = 0,
        Started = false,
        RunningVersion = nil,
        Version = 0,
        Destroyed = false
    }

    self.Tasks[name] = state
    self.Order[#self.Order + 1] = state

    if self.Started and state.Enabled then
        self:StartTask(state)
    end

    return state
end

function Scheduler:SetEnabled(name, enabled)
    local state = self.Tasks[name]
    if not state or self.Destroyed then
        return false
    end

    state.Enabled = enabled == true
    state.Version = state.Version + 1
    state.RunningVersion = nil

    if state.Enabled and self.Started then
        self:StartTask(state)
    end

    return true
end

function Scheduler:Run(state)
    if self.Destroyed or state.Destroyed or not state.Enabled or state.Running then
        return false
    end

    state.Running = true
    state.LastRun = os_clock()

    local ok, err = pcall(state.Callback, state)
    state.Running = false

    if ok then
        state.Errors = 0
        state.LastError = nil
        state.LastSuccess = os_clock()
        return true
    end

    state.Errors = state.Errors + 1
    state.LastError = tostring(err)

    if state.Errors >= self.MaxErrors then
        state.Enabled = false
    end

    if self.OnError then
        pcall(self.OnError, state, state.LastError)
    end

    return false
end

-- A task can have at most one live thread per Version. The old guard
-- (`state.Started and state.Enabled`) skipped restarting when the previous thread
-- was still parked in task.wait, leaving an enabled task with no runner.
function Scheduler:StartTask(state)
    if self.Destroyed or state.Destroyed then
        return
    end

    if state.RunningVersion == state.Version and state.Started then
        return
    end

    state.Started = true
    local version = state.Version
    state.RunningVersion = version

    task.spawn(function()
        while not self.Destroyed and not state.Destroyed and state.Version == version do
            if state.Enabled then
                self:Run(state)
            end
            task.wait(state.Interval)
        end
        if state.RunningVersion == version then
            state.Started = false
            state.RunningVersion = nil
        end
    end)
end

function Scheduler:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true

    table.sort(self.Order, function(a, b)
        return a.Priority > b.Priority
    end)

    for _, state in ipairs(self.Order) do
        if state.Enabled then
            self:StartTask(state)
        end
    end

    return true
end

function Scheduler:Stop(name)
    local state = self.Tasks[name]
    if not state then
        return false
    end

    state.Enabled = false
    state.Version = state.Version + 1
    state.RunningVersion = nil
    return true
end

function Scheduler:Get(name)
    return self.Tasks[name]
end

function Scheduler:GetSnapshot()
    local result = {}

    for _, state in ipairs(self.Order) do
        result[#result + 1] = {
            Name = state.Name,
            Enabled = state.Enabled,
            Running = state.Running,
            Errors = state.Errors,
            LastError = state.LastError,
            LastRun = state.LastRun,
            LastSuccess = state.LastSuccess,
            Priority = state.Priority,
            Interval = state.Interval
        }
    end

    return result
end

function Scheduler:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true

    for _, state in ipairs(self.Order) do
        state.Destroyed = true
        state.Enabled = false
        state.Version = state.Version + 1
        state.RunningVersion = nil
    end

    self.Tasks = {}
    self.Order = {}
end

return Scheduler

]],
    ["src/core/tween-movement.lua"] = [[
local Players=game:GetService("Players")
local TweenService=game:GetService("TweenService")
local RunService=game:GetService("RunService")
local Workspace=game:GetService("Workspace")

local Movement={}
Movement.__index=Movement

function Movement.new(config)
    config=config or {}

    return setmetatable({
        Player=Players.LocalPlayer,
        Speed=tonumber(config.Speed) or 220,
        NearSpeed=tonumber(config.NearSpeed) or 440,
        NearDistance=math.max(tonumber(config.NearDistance) or 380,0),
        DirectDistance=math.max(tonumber(config.DirectDistance) or 12,0),
        ArrivalRadius=math.max(tonumber(config.ArrivalRadius) or 0.75,0.01),
        MinDuration=tonumber(config.MinDuration) or 0.03,
        MaxSegmentDuration=tonumber(config.MaxSegmentDuration) or 3,
        SegmentPause=tonumber(config.SegmentPause) or 0.5,
        Priorities=type(config.Priorities)=="table" and config.Priorities or {},
        UsePhysics=config.UsePhysics~=false,
        Tween=nil,
        SteppedConnection=nil,
        HeartbeatConnection=nil,
        ActiveHumanoid=nil,
        ActiveRoot=nil,
        CollisionState={},
        ControlState=nil,
        LastClearCFrame=nil,
        Moving=false,
        MoveToken=0,
        ActiveOwner=nil,
        ActivePriority=-math.huge,
        Destroyed=false
    },Movement)
end

function Movement:_character()
    local character=self.Player and self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")

    if not humanoid or humanoid.Health<=0 or not root then
        return nil
    end

    return humanoid,root
end

function Movement:_toCFrame(target)
    local kind=typeof(target)

    if kind=="CFrame" then
        return target
    elseif kind=="Vector3" then
        return CFrame.new(target)
    elseif kind=="Instance" and target:IsA("BasePart") then
        return target.CFrame
    end

    return nil
end

function Movement:_isRootClear(cframe,character)
    local params=OverlapParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances={character}

    local ok,parts=pcall(
        Workspace.GetPartBoundsInBox,
        Workspace,
        cframe,
        Vector3.new(1.8,2,1.8),
        params
    )

    if not ok then
        return true
    end

    for _,part in ipairs(parts) do
        if part:IsA("BasePart") and part.CanCollide then
            return false
        end
    end

    return true
end

function Movement:_noclip(character)
    for _,part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if self.CollisionState[part]==nil then
                self.CollisionState[part]=part.CanCollide
            end
            part.CanCollide=false
        end
    end
end

function Movement:_applyTravelState(humanoid,root)
    self.CollisionState={}
    self.ControlState={
        WalkSpeed=humanoid.WalkSpeed,
        JumpPower=humanoid.JumpPower,
        JumpHeight=humanoid.JumpHeight,
        AutoRotate=humanoid.AutoRotate
    }

    humanoid.WalkSpeed=0
    humanoid.JumpPower=0
    humanoid.JumpHeight=0
    humanoid.AutoRotate=false
    self:_noclip(root.Parent)
end

function Movement:_restoreTravelState(humanoid)
    for part,canCollide in pairs(self.CollisionState) do
        if part and part.Parent then
            part.CanCollide=canCollide
        end
    end
    table.clear(self.CollisionState)

    local state=self.ControlState
    self.ControlState=nil

    if humanoid and humanoid.Parent and state then
        humanoid.WalkSpeed=state.WalkSpeed
        humanoid.JumpPower=state.JumpPower
        humanoid.JumpHeight=state.JumpHeight
        humanoid.AutoRotate=state.AutoRotate
    end

    if humanoid and humanoid.Parent and humanoid.Health>0 and self.UsePhysics and humanoid:GetState()==Enum.HumanoidStateType.Physics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.GettingUp)
    end
end

function Movement:_resolveSpeed(remaining,requested)
    local explicit=tonumber(requested)

    if explicit and explicit>0 then
        return explicit
    end

    if self.NearSpeed and self.NearSpeed>0 and self.NearDistance>0 and remaining<=self.NearDistance then
        return self.NearSpeed
    end

    return self.Speed
end

function Movement:GetProfile()
    return {
        Speed=self.Speed,
        NearSpeed=self.NearSpeed,
        NearDistance=self.NearDistance,
        DirectDistance=self.DirectDistance,
        ArrivalRadius=self.ArrivalRadius,
        MinDuration=self.MinDuration,
        MaxSegmentDuration=self.MaxSegmentDuration,
        SegmentPause=self.SegmentPause
    }
end

function Movement:GetOwner()
    return self.ActiveOwner,self.ActivePriority
end

function Movement:IsOwnedBy(owner)
    return self.ActiveOwner~=nil and self.ActiveOwner==tostring(owner)
end

function Movement:Stop(preservePosition,owner)
    if owner~=nil and self.ActiveOwner~=nil and self.ActiveOwner~=tostring(owner) then
        return false,"owner mismatch"
    end

    self.MoveToken+=1

    local tween=self.Tween
    local stepped=self.SteppedConnection
    local heartbeat=self.HeartbeatConnection
    local humanoid=self.ActiveHumanoid
    local root=self.ActiveRoot
    local lastClear=self.LastClearCFrame

    self.Tween=nil
    self.SteppedConnection=nil
    self.HeartbeatConnection=nil
    self.ActiveHumanoid=nil
    self.ActiveRoot=nil
    self.LastClearCFrame=nil
    self.Moving=false
    self.ActiveOwner=nil
    self.ActivePriority=-math.huge

    if tween then pcall(tween.Cancel,tween) end
    if stepped then pcall(stepped.Disconnect,stepped) end
    if heartbeat then pcall(heartbeat.Disconnect,heartbeat) end

    if root and root.Parent then
        if not preservePosition and not self:_isRootClear(root.CFrame,root.Parent) and lastClear then
            root.CFrame=lastClear
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
    end

    self:_restoreTravelState(humanoid)
    return true
end

function Movement:CancelOwner(owner,preservePosition)
    if not self:IsOwnedBy(owner) then
        return false
    end

    return self:Stop(preservePosition~=false,owner)
end

function Movement:IsMoving()
    return self.Moving==true
end

function Movement:FlyTo(target,speed,owner,priority)
    if self.Destroyed then
        return false,"destroyed"
    end

    local goal=self:_toCFrame(target)
    if not goal then
        return false,"invalid target"
    end

    local humanoid,root=self:_character()
    if not humanoid or not root then
        return false,"character unavailable"
    end

    local requestedSpeed=tonumber(speed)
    if requestedSpeed and requestedSpeed<=0 then
        return false,"invalid speed"
    end

    if self.Speed<=0 then
        return false,"invalid speed"
    end

    local moveOwner=tostring(owner or "default")
    local configuredPriority=tonumber(self.Priorities[moveOwner]) or 0
    local movePriority=tonumber(priority) or configuredPriority

    if self.Moving and self.ActiveOwner and self.ActiveOwner~=moveOwner and movePriority<self.ActivePriority then
        return false,"busy",self.ActiveOwner
    end

    self:Stop(true)
    local token=self.MoveToken
    local distance=(root.Position-goal.Position).Magnitude

    if distance<=self.ArrivalRadius then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    if self.DirectDistance>0 and distance<=self.DirectDistance then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    self.Moving=true
    self.ActiveOwner=moveOwner
    self.ActivePriority=movePriority
    self.ActiveHumanoid=humanoid
    self.ActiveRoot=root
    self:_applyTravelState(humanoid,root)

    if self:_isRootClear(root.CFrame,root.Parent) then
        self.LastClearCFrame=root.CFrame
    end

    root.AssemblyLinearVelocity=Vector3.zero
    root.AssemblyAngularVelocity=Vector3.zero

    if self.UsePhysics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.Physics)
    end

    self.SteppedConnection=RunService.Stepped:Connect(function()
        if token~=self.MoveToken or not root.Parent then return end

        self:_noclip(root.Parent)
        humanoid.WalkSpeed=0
        humanoid.JumpPower=0
        humanoid.JumpHeight=0
        humanoid.AutoRotate=false
    end)

    local lastClearCheck=0

    self.HeartbeatConnection=RunService.Heartbeat:Connect(function()
        if token~=self.MoveToken then return end

        if not root.Parent or humanoid.Health<=0 then
            self:Stop(true,moveOwner)
            return
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        local now=os.clock()
        if now-lastClearCheck>=0.15 then
            lastClearCheck=now

            if self:_isRootClear(root.CFrame,root.Parent) then
                self.LastClearCFrame=root.CFrame
            end
        end
    end)

    local completed=true

    while token==self.MoveToken do
        local delta=goal.Position-root.Position
        local remaining=delta.Magnitude

        if remaining<=self.ArrivalRadius then
            root.CFrame=goal
            break
        end

        local moveSpeed=self:_resolveSpeed(remaining,requestedSpeed)
        local segmentDuration=math.min(remaining/moveSpeed,self.MaxSegmentDuration)
        local segmentDistance=math.min(remaining,moveSpeed*self.MaxSegmentDuration)
        local nextPosition=root.Position+delta.Unit*segmentDistance
        local segmentGoal=CFrame.new(nextPosition)*goal.Rotation

        local ok,tween=pcall(function()
            return TweenService:Create(
                root,
                TweenInfo.new(math.max(segmentDuration,self.MinDuration),Enum.EasingStyle.Linear),
                {CFrame=segmentGoal}
            )
        end)

        if not ok then
            self:Stop(true,moveOwner)
            return false,tostring(tween)
        end

        self.Tween=tween
        tween:Play()

        local playbackState=tween.Completed:Wait()

        if token~=self.MoveToken then
            return false,"cancelled"
        end

        if playbackState~=Enum.PlaybackState.Completed then
            completed=false
            break
        end

        self.Tween=nil
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        if remaining>segmentDistance+0.05 and self.SegmentPause>0 then
            local holdCFrame=root.CFrame
            local pauseUntil=os.clock()+self.SegmentPause

            while token==self.MoveToken and os.clock()<pauseUntil do
                if not root.Parent or humanoid.Health<=0 then
                    break
                end

                root.CFrame=holdCFrame
                root.AssemblyLinearVelocity=Vector3.zero
                root.AssemblyAngularVelocity=Vector3.zero
                RunService.Heartbeat:Wait()
            end
        end
    end

    if token~=self.MoveToken then
        return false,"cancelled"
    end

    self:Stop(true,moveOwner)
    return completed
end

function Movement:SetSpeed(value)
    value=tonumber(value)
    if not value or value<=0 then
        return false
    end

    self.Speed=value
    return true
end

function Movement:SetNearSpeed(value,distance)
    value=tonumber(value)
    distance=tonumber(distance)

    if not value or value<=0 or not distance or distance<=0 then
        return false
    end

    self.NearSpeed=value
    self.NearDistance=distance
    return true
end

function Movement:Destroy()
    if self.Destroyed then return end
    self:Stop()
    self.Destroyed=true
end

return Movement

