    ["src/core/ui-kit.lua"] = [[
-- DepHub UI kit
--
-- One small helper every backend uses to build its part of the shared shell in
-- the repository's standard shape:
--
--     Category (finalidade: Visual / Combat / Farm / Movement / Player /
--               World / Misc / Settings)
--       └─ Tab
--            └─ Section (Left or Right)
--                 └─ Toggle / Slider / Dropdown / Button / Input / Paragraph
--
-- Why this exists: exactly the same three-step dance (create the category, make
-- the tab inside it, then make a section with a valid column) was hand-written
-- in every backend, and the copy in some of them passed the column argument in
-- the wrong slot -- which makes Library:CreateSection error, the pcall swallow
-- it, and the whole tab render EMPTY. Centralizing it here means there is one
-- correct implementation instead of N chances to get it wrong.
--
-- The kit is purely a thin wrapper over env.__DEPHUB.UI. It never makes a GUI of
-- its own and never touches anything outside the API the shell exposes.

local env = type(getgenv) == "function" and getgenv() or _G

local Kit = {}

-- Icons for the standard categories, so every game's sidebar looks the same for
-- the same finalidade. Names are theme icon names (see the shell's GetIcon).
local CATEGORY_ICONS = {
    Visual = "eye",
    Combat = "crosshair",
    Farm = "wheat",
    Movement = "move-3d",
    Player = "user",
    World = "globe",
    Misc = "wrench",
    Settings = "settings",
}

-- Resolve the shared shell. Returns nil (never errors) when there is no UI, so
-- a backend can call the kit unconditionally and simply build nothing.
local function window()
    local ui = env.__DEPHUB and env.__DEPHUB.UI
    if type(ui) == "table" and type(ui.CreateTab) == "function" then return ui end
    return nil
end

-- Create a category once. Idempotent: a second call for the same name is a
-- no-op, so two features in the same finalidade never collide.
function Kit.Category(name, icon)
    local ui = window()
    if not ui then return false end
    if type(ui.CreateCategory) ~= "function" then return false end
    local ok = pcall(function() ui:CreateCategory(name, icon or CATEGORY_ICONS[name] or "layers") end)
    return ok
end

-- Create a tab inside a category. Category defaults to the tab's own name so a
-- single-tab game stays trivial, but the normal call passes the finalidade:
--     Kit.Tab("ESP", "Visual")
function Kit.Tab(name, category)
    local ui = window()
    if not ui then return nil end
    category = category or name
    Kit.Category(category)
    local ok, tab = pcall(function() return ui:CreateTab(name, category) end)
    if ok and tab then return tab end
    return nil
end

-- Create a section on a tab. The column MUST be "Left" or "Right" (anything else
-- makes the shell drop the section and leave the tab empty); we clamp it here so
-- a backend can never pass the wrong value.
function Kit.Section(tab, title, column)
    if not (tab and type(tab.CreateSection) == "function") then return nil end
    if column ~= "Left" and column ~= "Right" then column = "Left" end
    local ok, section = pcall(function() return tab:CreateSection(title, column) end)
    if ok then return section end
    return nil
end

-- One-call convenience: tab (in a category) + section, which is the shape almost
-- every feature uses. Returns the section (or nil).
function Kit.Panel(tabName, category, sectionTitle, column)
    local tab = Kit.Tab(tabName, category)
    if not tab then return nil end
    return Kit.Section(tab, sectionTitle or tabName, column)
end

-- The standard categories a backend may use, in the order they should appear.
-- Kept here so every game presents the same finalidades in the same order.
Kit.CATEGORIES = { "Visual", "Combat", "Farm", "Movement", "Player", "World", "Misc", "Settings" }

-- Group controls side by side on one line. Returns a row handle with the same
-- Create* builders a section has (CreateToggle / CreateSlider / ...). The row
-- shares its width across the controls added to it, so a toggle and the slider
-- that drives it sit on one line instead of two full-width rows.
function Kit.Row(section)
    if not (section and type(section.CreateRow) == "function") then return nil end
    local ok, row = pcall(function() return section:CreateRow() end)
    if ok and row then return row end
    return nil
end

-- Group controls as a named vertical stack (same stacked look, one box).
function Kit.Stack(section)
    if not (section and type(section.CreateStack) == "function") then return nil end
    local ok, stack = pcall(function() return section:CreateStack() end)
    if ok and stack then return stack end
    return nil
end

function Kit.categoryIcon(name)
    return CATEGORY_ICONS[name] or "layers"
end

return Kit

]],
    ["src/core/updater.lua"] = [[
local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local pcall = pcall
local math_random = math.random
local os_clock = os.clock

local GetService = game.GetService
local Players = GetService(game, "Players")
local HttpService = GetService(game, "HttpService")
local TeleportService = GetService(game, "TeleportService")

local LocalPlayer = Players.LocalPlayer

local sourceBase = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local MANIFEST_URL = sourceBase .. "src/update-manifest.json"
local SERVERS_URL = "https://games.roblox.com/v1/games/%s/servers/Public?sortOrder=Asc&limit=100"
local COMPARE_URL = "https://api.github.com/repos/glowpkj/DepHub/compare/%s...%s"

local Updater = {}
Updater.__index = Updater

local function silent()
end

local updateLog = silent
local updateWarn = silent

local function httpGet(url)
    local ok, result = pcall(function()
        return __dephubHttpGet(url)
    end)
    if ok and type(result) == "string" and #result > 0 then
        return true, result
    end
    return false, ok and "Resposta vazia" or tostring(result)
end

local function decode(source)
    local ok, result = pcall(function()
        return HttpService:JSONDecode(source)
    end)
    if ok and type(result) == "table" then
        return true, result
    end
    return false, ok and "JSON invalido" or tostring(result)
end

local function buildSet(list)
    local result = {}
    if type(list) ~= "table" then
        return result
    end
    for _, value in ipairs(list) do
        if type(value) == "string" then
            result[value] = true
        end
    end
    return result
end

function Updater.new(options)
    options = options or {}
    local self = setmetatable({}, Updater)
    self.PlaceId = tostring(options.PlaceId or game.PlaceId)
    self.GameId = tostring(options.GameId or game.GameId)
    self.ManifestId = tostring(options.ManifestId or self.GameId)
    self.CurrentVersion = options.CurrentVersion and tostring(options.CurrentVersion) or nil
    self.CurrentCommit = options.CurrentCommit and tostring(options.CurrentCommit) or nil
    self.PollInterval = tonumber(options.PollInterval) or 15
    self.Mode = options.Mode or "serverhop"
    self.StartupGrace = tonumber(options.StartupGrace) or 90
    self.StartedAt = os_clock()
    self.CancelledVersions = {}
    self.RejectedVersions = {}
    self.Destroyed = false
    self.Started = false
    self.PendingUpdate = nil
    self.ActionInProgress = false
    return self
end

function Updater:FetchVersion()
    local ok, source = httpGet(MANIFEST_URL .. "?dephubupdate=" .. tostring(math_random(1000000, 9999999)))
    if not ok then
        return false, source
    end

    if self.Destroyed then return false, "Updater destruido" end
    local decoded, manifest = decode(source)
    if not decoded then
        return false, manifest
    end

    local games = manifest.games
    local info = type(games) == "table" and (games[self.ManifestId] or games[self.PlaceId]) or nil
    if type(info) ~= "table" or not info.version then
        return false, "Jogo sem versao registrada"
    end

    local commit = tostring(info.commit or manifest.commit or "")
    local files = type(info.files) == "table" and info.files or {}

    return true, {
        Version = tostring(info.version),
        Name = tostring(info.name or "DepHub"),
        Commit = commit,
        Files = files
    }
end

function Updater:ValidateBackendChange(info)
    if not self.CurrentCommit or self.CurrentCommit == "" then
        return false
    end

    if not info.Commit or info.Commit == "" then
        return false
    end

    if self.CurrentCommit == info.Commit then
        return false
    end

    local url = string.format(COMPARE_URL, self.CurrentCommit, info.Commit)
    local ok, source = httpGet(url)
    if not ok then
        return false
    end

    local decoded, compareData = decode(source)
    if not decoded then
        return false
    end

    local trackedFiles = buildSet(info.Files)
    local changedTracked = {}

    if type(compareData.files) == "table" then
        for _, file in ipairs(compareData.files) do
            local filename = type(file) == "table" and file.filename or nil
            if filename and trackedFiles[filename] then
                changedTracked[#changedTracked + 1] = filename
            end
        end
    end

    return #changedTracked > 0
end

-- Without a frontend, detected updates wait for explicit action.
function Updater:Cancel()
    if self.ActionInProgress then return end
    if self.PendingUpdate then
        self.CancelledVersions[self.PendingUpdate.Version] = true
        self.PendingUpdate = nil
    end
end

function Updater:ApplyPending()
    if self.Destroyed or self.ActionInProgress or not self.PendingUpdate then return false end
    return self:Teleport()
end

function Updater:GetServer()
    local url = string.format(SERVERS_URL, self.PlaceId)
    local ok, source = httpGet(url)
    if not ok then
        return false, source
    end

    local decoded, data = decode(source)
    if not decoded then
        return false, data
    end

    local candidates = {}
    if type(data.data) == "table" then
        for _, server in data.data do
            if type(server) == "table" and server.id and tonumber(server.playing) and tonumber(server.maxPlayers) then
                if server.id ~= game.JobId and server.playing < server.maxPlayers then
                    candidates[#candidates + 1] = server.id
                end
            end
        end
    end

    if #candidates == 0 then
        return false, "No server available"
    end

    return true, candidates[math_random(1, #candidates)]
end

function Updater:Teleport()
    if self.Destroyed or self.ActionInProgress then
        return false
    end

    self.ActionInProgress = true
    self.PendingUpdate = nil

    if self.Mode == "rejoin" then
        local ok = pcall(function()
            TeleportService:Teleport(tonumber(self.PlaceId), LocalPlayer)
        end)
        if not ok then self.ActionInProgress = false end
        return ok
    end

    local ok, jobId = self:GetServer()
    if ok and jobId then
        local teleported = pcall(function()
            TeleportService:TeleportToPlaceInstance(tonumber(self.PlaceId), jobId, LocalPlayer)
        end)
        if teleported then
            return true
        end
    end

    local teleported = pcall(function()
        TeleportService:Teleport(tonumber(self.PlaceId), LocalPlayer)
    end)
    if not teleported then self.ActionInProgress = false end
    return teleported
end

function Updater:Check()
    if self.Destroyed or self.PendingUpdate or self.ActionInProgress then
        return
    end

    local ok, info = self:FetchVersion()
    if not ok or self.Destroyed then return end

    local startupAge = os_clock() - self.StartedAt

    if not self.CurrentVersion then
        self.CurrentVersion = info.Version
        self.CurrentCommit = info.Commit
        return
    end

    if info.Version == self.CurrentVersion then
        return
    end

    if startupAge < self.StartupGrace then
        self.CurrentVersion = info.Version
        self.CurrentCommit = info.Commit
        return
    end

    if self.CancelledVersions[info.Version] or self.RejectedVersions[info.Version] then
        return
    end

    if not self:ValidateBackendChange(info) then
        self.RejectedVersions[info.Version] = true
        return
    end

    if not self.Destroyed then self.PendingUpdate = info end
end

function Updater:Start()
    if self.Destroyed or self.Started then return false end
    self.Started = true

    task.spawn(function()
        task.wait(5)
        if self.Destroyed then
            return
        end

        self:Check()

        while not self.Destroyed do
            task.wait(self.PollInterval * (1 + (math.random() * 2 - 1) * 0.15))
            if not self.Destroyed then
                self:Check()
            end
        end
    end)
end

function Updater:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false
    self.PendingUpdate = nil
end

return Updater


]],
    ["src/dephubv2lib.lua"] = [[
-- DepHub UI library (RedzLib v2.0.1, vendored).
--
-- This is the single UI library every backend in DepHub renders through. It is
-- kept in-tree (not fetched at runtime) so editing this file edits the UI.
--
-- It was originally shipped minified, with single-letter top-level names and no
-- comments. The minified body is preserved exactly (it is load-bearing and has
-- been proven to render identically), but the file-wide top-level symbols have
-- been renamed to meaningful names and the file is split into labelled sections
-- so it can be read and maintained. Everything below the "SECTION" banners is
-- the original logic, untouched except for those renames.
--
-- Public API (the part DepHub consumes):
--   local lib = Library                     -- this module's export
--   local win = lib:MakeWindow({Title=, SubTitle=, ScriptFolder=})
--   local tab = win:MakeTab({Title=, Icon=})
--   tab:AddSection(title)                   -- visual header (string only)
--   tab:AddToggle/Slider/Button/TextBox/Dropdown/Paragraph/Keybind/...
--   win:Notify({Title=, Content=, Icon=, Duration=})
--   win:Dialog({Title=, Content=, Options={...}})
--   win:SelectTab(n|tab) / win:GetTabByTitle(t) / win:Minimize() / win:Dialog()
--   tab:Select() / tab:SetVisible(bool) / tab:Destroy()
--   lib:GetIconByName(name) / lib:SetTheme(name) / lib:SetUIScale(scale)
