    ["src/games/bloodstrike.lua"] = [[
local game, task, type, tostring, tonumber, pairs, ipairs, pcall, math = game, task, type, tostring, tonumber, pairs, ipairs, pcall, math
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local LocalPlayer = Players.LocalPlayer
local env = type(getgenv) == "function" and getgenv() or _G
local STATE_KEY = "__DEPHUB_BLOODSTRIKE"

local previous = env[STATE_KEY]
if type(previous) == "table" and type(previous.Destroy) == "function" then
    pcall(previous.Destroy, previous)
end

if not LocalPlayer then
    return false
end

-- Blood Strike backend.
--
-- The game keeps every fighter (players and bots) as a Model under
-- workspace.Characters, named after the owner, instead of relying on the usual
-- Players.Character mirror. So the ESP resolves a character by matching the
-- Model name against the player list, then falls back to the standard
-- LocalPlayer/Players surface when that container is missing (menu, loading, a
-- private server variant) so the panel still works instead of going blank.

local State = {
    Version = "0.1.0",
    Destroyed = false,
    Started = false,
    Root = nil,
    Connections = {},
    Toggles = {
        ESP = false,
        TeamCheck = true,
        ESPNames = true,
        ESPDistance = true,
        ESPHealth = false,
        Chams = true,
    },
    ToggleLabels = {
        ESP = "ESP enabled",
        TeamCheck = "Ignore teammates",
        ESPNames = "Show name",
        ESPDistance = "Show distance",
        ESPHealth = "Show health",
        Chams = "Chams (outline)",
    },
    Values = {
        Range = 1000,
        ESPColor = Color3.fromRGB(255, 70, 70),
        EnemyColor = Color3.fromRGB(255, 70, 70),
        AllyColor = Color3.fromRGB(80, 200, 255),
        TextSize = 13,
    },
    ESPObjects = {},
}

env[STATE_KEY] = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.BloodStrike = State

local function characterParts(player)
    local character = player.Character
    if not character then return nil, nil, nil end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
    return character, humanoid, root
end

-- A character Model in workspace.Characters is named after its owner. Resolve it
-- back to the Player so team checks and the player list stay authoritative.
local function playerForModel(model)
    if not model then return nil end
    local player = Players:GetPlayerFromCharacter(model)
    if player then return player end
    local name = model.Name
    for _, candidate in ipairs(Players:GetPlayers()) do
        if candidate.Name == name or candidate.DisplayName == name then return candidate end
    end
    return nil
end

-- The ESP is driven off workspace.Characters when it exists; otherwise it falls
-- back to the players whose Character lives under the standard container. Both
-- paths yield {model, player} pairs the rest of the module treats identically.
local function eachFighter()
    local list = {}
    local container = Workspace:FindFirstChild("Characters")
    if container then
        for _, model in ipairs(container:GetChildren()) do
            if model:IsA("Model") then
                list[#list + 1] = {model = model, player = playerForModel(model)}
            end
        end
    end
    if #list == 0 then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                list[#list + 1] = {model = player.Character, player = player}
            end
        end
    end
    return list
end

local function isAlly(player)
    if not player or not LocalPlayer then return false end
    if player == LocalPlayer then return true end
    if LocalPlayer.Team ~= nil and player.Team ~= nil then return player.Team == LocalPlayer.Team end
    if LocalPlayer.TeamColor ~= nil and player.TeamColor ~= nil then return player.TeamColor == LocalPlayer.TeamColor end
    return false
end

local function colorFor(player)
    if State.Toggles.TeamCheck and isAlly(player) then return State.Values.AllyColor end
    return State.Values.EnemyColor
end

function State:RemoveESP(model)
    local record = self.ESPObjects[model]
    if not record then return end
    self.ESPObjects[model] = nil
    for _, object in pairs(record) do
        if typeof(object) == "Instance" then pcall(object.Destroy, object) end
    end
end

function State:ClearESP()
    for model in pairs(self.ESPObjects) do
        self:RemoveESP(model)
    end
end

function State:CreateESP(model, player)
    self:RemoveESP(model)
    if self.Destroyed or not self.Toggles.ESP or not model then return end
    if self.Toggles.TeamCheck and isAlly(player) then return end
    local head = model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart")
    if not head then return end

    local color = colorFor(player)
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "DepHubESP"
    billboard.AlwaysOnTop = true
    billboard.Size = UDim2.fromOffset(220, 46)
    billboard.StudsOffset = Vector3.new(0, 2.8, 0)
    billboard.Adornee = head
    billboard.Parent = head

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextStrokeTransparency = 0.35
    label.TextColor3 = color
    label.TextSize = self.Values.TextSize
    label.Parent = billboard

    local highlight
    if self.Toggles.Chams then
        highlight = Instance.new("Highlight")
        highlight.Name = "DepHubChams"
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillColor = color
        highlight.FillTransparency = 0.55
        highlight.OutlineColor = Color3.new(1, 1, 1)
        highlight.Adornee = model
        highlight.Parent = model
    end

    self.ESPObjects[model] = {Billboard = billboard, Label = label, Highlight = highlight}
end

function State:SetESP(enabled)
    self.Toggles.ESP = enabled == true
    if not self.Toggles.ESP then
        self:ClearESP()
        return true
    end
    self:Refresh()
    return true
end

-- Reconcile every frame: create records for fighters in range, drop stale ones,
-- and repaint the survivors. Team check and range are re-evaluated live so a
-- toggle or slider change is visible without a relock.
function State:Refresh()
    if self.Destroyed or not self.Toggles.ESP then return end
    local _, _, localRoot = characterParts(LocalPlayer)
    local seen = {}
    for _, entry in ipairs(eachFighter()) do
        local model, player = entry.model, entry.player
        if model ~= (LocalPlayer.Character) then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head")
            local distance = 0
            if localRoot and root and localRoot.Position and root.Position then
                local delta = root.Position - localRoot.Position
                distance = math.floor(delta.Magnitude or 0)
            end
            local ally = self.Toggles.TeamCheck and isAlly(player)
            local visible = not ally and distance <= self.Values.Range
            if visible then
                seen[model] = true
                local record = self.ESPObjects[model]
                if not record then
                    self:CreateESP(model, player)
                    record = self.ESPObjects[model]
                end
                if record then
                    local color = colorFor(player)
                    record.Label.TextColor3 = color
                    if record.Highlight then record.Highlight.FillColor = color end
                    local text = {}
                    if self.Toggles.ESPNames then
                        text[#text + 1] = player and (player.DisplayName or player.Name) or model.Name
                    end
                    if self.Toggles.ESPHealth and humanoid and humanoid.Health then text[#text + 1] = math.floor(humanoid.Health) .. " HP" end
                    if self.Toggles.ESPDistance then text[#text + 1] = distance .. "m" end
                    record.Label.Text = table.concat(text, " | ")
                    record.Label.TextSize = self.Values.TextSize
                    record.Billboard.Enabled = true
                    if record.Highlight then record.Highlight.Enabled = true end
                end
            end
        end
    end
    for model in pairs(self.ESPObjects) do
        if not seen[model] then self:RemoveESP(model) end
    end
end

function State:SetToggle(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    if self.Toggles[name] == nil then return false end
    self.Toggles[name] = enabled == true
    if name == "ESP" then
        return self:SetESP(enabled)
    elseif name == "TeamCheck" or name == "Chams" then
        -- A team/chams change alters which records exist, so rebuild.
        if self.Toggles.ESP then self:ClearESP(); self:Refresh() end
    end
    return true
end

function State:GetToggle(name)
    if self.Destroyed or type(name) ~= "string" then return false end
    return self.Toggles[name] == true
end

function State:SetRange(value)
    value = tonumber(value)
    if not value or value ~= value or value < 1 then return false end
    self.Values.Range = math.clamp(math.floor(value), 1, 100000)
    return true
end

function State:SetTextSize(value)
    value = tonumber(value)
    if not value or value ~= value then return false end
    self.Values.TextSize = math.clamp(math.floor(value), 6, 40)
    return true
end

function State:Start()
    if self.Started or self.Destroyed then return false end
    self.Started = true
    local connection = RunService.RenderStepped:Connect(function()
        if not self.Destroyed and self.Toggles.ESP then self:Refresh() end
    end)
    self.Connections[#self.Connections + 1] = connection
    return true
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self:ClearESP()
    for _, connection in ipairs(self.Connections) do
        if typeof(connection) == "Instance" or type(connection) == "table" then
            pcall(function() connection:Disconnect() end)
        end
    end
    self.Connections = {}
    if env[STATE_KEY] == self then env[STATE_KEY] = nil end
    if env.__DEPHUB and env.__DEPHUB.BloodStrike == self then env.__DEPHUB.BloodStrike = nil end
end

-- ---------------------------------------------------------------------------
-- Presentation: the shared shell. Tabs and sections are the backend's job.
-- ---------------------------------------------------------------------------
-- Presentation: grouped by CATEGORY (finalidade), never a per-game tab. This
-- backend is purely visual, so everything lives in the Visual category.
-- ---------------------------------------------------------------------------
do
    local Kit = env.__DEPHUB and env.__DEPHUB.UIKit
    if Kit then
        local visual = Kit.Section(Kit.Tab("ESP", "Visual"), "Players", "Left")
        if visual then
            -- Six ESP element switches, all the same decision; two lines of three,
            -- then the two value sliders.
            local espRow1 = Kit.Row(visual)
            if espRow1 then
                espRow1:CreateToggle(State.ToggleLabels.ESP, State.Toggles.ESP, function(v) State:SetToggle("ESP", v) end)
                espRow1:CreateToggle(State.ToggleLabels.TeamCheck, State.Toggles.TeamCheck, function(v) State:SetToggle("TeamCheck", v) end)
            else
                visual:CreateToggle(State.ToggleLabels.ESP, State.Toggles.ESP, function(v) State:SetToggle("ESP", v) end)
                visual:CreateToggle(State.ToggleLabels.TeamCheck, State.Toggles.TeamCheck, function(v) State:SetToggle("TeamCheck", v) end)
            end
            local espRow1b = Kit.Row(visual)
            if espRow1b then
                espRow1b:CreateToggle(State.ToggleLabels.Chams, State.Toggles.Chams, function(v) State:SetToggle("Chams", v) end)
                espRow1b:CreateToggle(State.ToggleLabels.ESPNames, State.Toggles.ESPNames, function(v) State.Toggles.ESPNames = v == true end)
            else
                visual:CreateToggle(State.ToggleLabels.Chams, State.Toggles.Chams, function(v) State:SetToggle("Chams", v) end)
                visual:CreateToggle(State.ToggleLabels.ESPNames, State.Toggles.ESPNames, function(v) State.Toggles.ESPNames = v == true end)
            end
            local espRow2 = Kit.Row(visual)
            if espRow2 then
                espRow2:CreateToggle(State.ToggleLabels.ESPDistance, State.Toggles.ESPDistance, function(v) State.Toggles.ESPDistance = v == true end)
                espRow2:CreateToggle(State.ToggleLabels.ESPHealth, State.Toggles.ESPHealth, function(v) State.Toggles.ESPHealth = v == true end)
            else
                visual:CreateToggle(State.ToggleLabels.ESPDistance, State.Toggles.ESPDistance, function(v) State.Toggles.ESPDistance = v == true end)
                visual:CreateToggle(State.ToggleLabels.ESPHealth, State.Toggles.ESPHealth, function(v) State.Toggles.ESPHealth = v == true end)
            end
            local espSliderRow = Kit.Row(visual)
            if espSliderRow then
                espSliderRow:CreateSlider("Max distance", 50, 5000, State.Values.Range, function(v) State:SetRange(v) end)
                espSliderRow:CreateSlider("Text size", 8, 30, State.Values.TextSize, function(v) State:SetTextSize(v) end)
            else
                visual:CreateSlider("Max distance", 50, 5000, State.Values.Range, function(v) State:SetRange(v) end)
                visual:CreateSlider("Text size", 8, 30, State.Values.TextSize, function(v) State:SetTextSize(v) end)
            end
        end
    end
end

State:Start()

do
    local Diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.RegisterModule) == "function" then
        Diag:RegisterModule("src/games/bloodstrike.lua")
        Diag:Feature("BloodStrike.ESP", function() return State.Toggles.ESP and "ON" or "off" end)
        Diag:Feature("BloodStrike.TeamCheck", function() return State.Toggles.TeamCheck and "ON" or "off" end)
        Diag:Watch("BloodStrike alvos", function() return tostring((function()
            local n = 0
            for _ in pairs(State.ESPObjects) do n = n + 1 end
            return n
        end)()) end)
        Diag:Command("bs", function()
            local container = Workspace:FindFirstChild("Characters")
            return "esp=" .. tostring(State.Toggles.ESP) ..
                " team=" .. tostring(State.Toggles.TeamCheck) ..
                " characters=" .. tostring(container and #container:GetChildren() or 0)
        end)
    end
end

env.BS = State

return State

]],
    ["src/games/bloxfruits.lua"] = [[
local game = game
local type = type
local tostring = tostring

local env = type(getgenv) == "function" and getgenv() or _G
local report = (env.__DEPHUB and type(env.__DEPHUB.Log) == "function") and env.__DEPHUB.Log or function() end

-- Backend for o script de Blox Fruits do usuario.
--
-- As features ficam em src/games/features/bloxfruits/<nome>.lua, uma por
-- arquivo, cada uma independente (sem DepHub, sem adapter OSS): elas fazem os
-- proprios game:GetService e se publicam como um modulo com new()/Enable()/
-- Disable(). Este backend so faz tres coisas -- baixa a arvore, monta o painel
-- e liga/desliga cada feature pelo toggle.
--
-- As features que ainda nao foram portadas ficam guardadas em
-- src/games/features/bloxfruits/parked/ (nada foi apagado): elas saem da pasta
-- ativa, nao carregam e nao entram no manifest, mas seguem no disco prontas
-- para serem trazidas pro molde proprio uma a uma. Por isso o backend so varre
-- FEATURE_MODULES -- nao existe flag global que ligue/desligue tudo.

local FEATURE_PATH = "src/games/features/bloxfruits/"
local VERSION = "1.0.0"

-- As features deste backend, na ordem em que carregam. Cada entrada: o arquivo,
-- a aba/secao em que aparece e o rotulo do toggle. O resto (range, intervalo…)
-- sai do proprio modulo, para o backend nao virar uma lista de knobs paralela.
--
-- Só a blade hit tem UI. O teleporte e INFRAESTRUTURA: um motor que outras
-- features usam (pegar fruta, farm), nao um toggle -- por isso entra em
-- INFRA_MODULES e nao aparece no painel.
local FEATURE_MODULES = {
    {name = "bladhits", page = "Combat", section = "BLADE HITS", toggle = "Blade hits"},
    {name = "fruit", page = "Farm", section = "FRUIT", toggle = "Grab fruit"},
    {name = "islands", page = "Travel", section = "ISLAND TELEPORT", toggle = "Island teleport"},
}
local INFRA_MODULES = {
    {name = "teleport"},
}

local previous = type(env.__DEPHUB_BLOXFRUITS) == "table" and env.__DEPHUB_BLOXFRUITS or nil
if previous and type(previous.Destroy) == "function" then pcall(previous.Destroy, previous) end

local sourceBase = (env.__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"

-- Prefer the bundle's resolver published on the shared environment. It is only
-- present in a bundled build; a source checkout resolves through the loader's
-- own fetch path, so fall back to the executor primitives in that order.
local function fetch(path)
    local cb = tostring((env.__DEPHUB or {}).SourceCacheBust or "")
    local url = sourceBase .. path .. (cb ~= "" and ("?cb=" .. cb) or "")
    local resolver = (type(env.__dephubHttpGet) == "function" and env.__dephubHttpGet)
        or (type(env.__DEPHUB_HTTP_GET) == "function" and env.__DEPHUB_HTTP_GET)
        or (type(_G.__dephubHttpGet) == "function" and _G.__dephubHttpGet)
        or (type(_G.__DEPHUB_HTTP_GET) == "function" and _G.__DEPHUB_HTTP_GET)
    if resolver then
        local ok, source = pcall(resolver, url)
        if ok and type(source) == "string" and #source > 0 then return true, source end
    end
    local ok, source = pcall(function() return __dephubHttpGet(url) end)
    if ok and type(source) == "string" and #source > 0 then return true, source end
    return false, tostring(source)
end

local function loadFactory(path)
    local okFetch, source = fetch(path)
    if not okFetch then return false, "fetch: " .. tostring(source) end
    local chunk, chunkError = loadstring(source)
    if not chunk then return false, "compile: " .. tostring(chunkError) end
    local okRun, factory = pcall(chunk)
    if not okRun or type(factory) ~= "table" then return false, "run: " .. tostring(factory) end
    return true, factory
end

local LocalPlayer = game:GetService("Players").LocalPlayer
if not LocalPlayer then
    report("BloxFruits: LocalPlayer ausente")
    return false
end

local State = {
    Destroyed = false,
    Version = VERSION,
    Features = {},
    Instances = {},
    Infra = {},
    Errors = {},
    Toggles = {},
    ToggleLabels = {},
    LastError = nil,
}

-- Carrega cada feature e guarda a fabrica. Nenhum init ainda: o modulo so
-- instancia quando o toggle liga, para o painel abrir sem ligar nada sozinho.
for _, entry in ipairs(FEATURE_MODULES) do
    local ok, factory = loadFactory(FEATURE_PATH .. entry.name .. ".lua")
    if ok then
        State.Features[entry.name] = factory
    else
        State.Errors[#State.Errors + 1] = entry.name .. ": " .. tostring(factory)
        report("BloxFruits: feature " .. entry.name .. " falhou: " .. tostring(factory))
    end
end

-- Infraestrutura: carrega e INSTANCIA sempre, porque nao ha toggle pra ligar.
-- O motor de teleporte fica disponivel em State.Infra para qualquer feature
-- (ou para o console) chamar. Sem character ou sem remotes ele nao explode --
-- so nao faz nada -- entao instanciar no load e seguro.
for _, entry in ipairs(INFRA_MODULES) do
    local ok, factory = loadFactory(FEATURE_PATH .. entry.name .. ".lua")
    if ok and type(factory) == "table" and type(factory.new) == "function" then
        local created, instance = pcall(factory.new, {})
        if created and type(instance) == "table" then
            if type(instance.Enable) == "function" then pcall(instance.Enable, instance) end
            State.Infra[entry.name] = instance
            State.Features[entry.name] = factory
        else
            State.Errors[#State.Errors + 1] = entry.name .. ": " .. tostring(instance)
        end
    else
        State.Errors[#State.Errors + 1] = entry.name .. ": " .. tostring(factory)
        report("BloxFruits: infra " .. entry.name .. " falhou: " .. tostring(factory))
    end
end

-- O motor de teleporte publico: as features chamam State:Teleport() para se
-- mover. Ele e o mesmo objeto para todo mundo -- um teleporte so, testado.
function State:Teleport()
    return self.Infra.teleport
end

-- A antiga lista de elementos de raid (State.RaidElements) saiu junto com a raid
-- parkeada -- so ela usava. Quando a raid voltar, a lista volta com ela.

function State:GetFeature(name)
    return self.Instances[name]
end

function State:SetFeature(name, enabled)
    if self.Destroyed then return false end
    local entry
    for _, candidate in ipairs(FEATURE_MODULES) do
        if candidate.name == name then entry = candidate break end
    end
    local factory = self.Features[name]
    if not entry or type(factory) ~= "table" then return false end
    if enabled then
        local instance = self.Instances[name]
        if not instance then
            -- Toda feature recebe um contexto com as pecas que podem ser
            -- COMPARTILHADAS -- e a feature decide se usa cada uma. Hoje:
            --   * teleport: o motor de voo (infra). A fruta usa no grab.
            --   * combat: a blade hit, quando ja instanciada. Reservado pra uma
            --     feature que ataque em vez de ter um ataque proprio (um motor
            --     de ataque no script, nao dois). Ninguem consome hoje -- a raid,
            --     que era a consumidora, esta parkeada.
            local context = {
                teleport = self.Infra.teleport,
                combat = self.Instances.bladhits,
                state = self,
            }
            local ok, created = pcall(factory.new, context)
            if not ok or type(created) ~= "table" then
                self.LastError = "new " .. name .. ": " .. tostring(created)
                report("BloxFruits: " .. self.LastError)
                return false
            end
            instance = created
            self.Instances[name] = instance
        end
        local ok = pcall(instance.Enable, instance)
        if not ok then self.LastError = "enable " .. name; return false end
        self.Toggles[name] = instance:IsEnabled() == true
        return self.Toggles[name]
    end
    local instance = self.Instances[name]
    if instance then pcall(instance.Disable, instance) end
    self.Toggles[name] = false
    return true
end

function State:SetToggle(key, enabled)
    return self:SetFeature(key, enabled == true)
end

function State:GetToggle(key)
    local instance = self.Instances[key]
    if instance then return instance:IsEnabled() == true end
    return self.Toggles[key] == true
end

-- A feature expoe os proprios knobs (range, intervalo…) por metodos, nao por
-- um config paralelo aqui. O backend so encaminha.
function State:SetFeatureRange(key, value)
    local instance = self.Instances[key]
    if not instance then return false end
    if type(instance.SetRange) ~= "function" then return false end
    return pcall(instance.SetRange, instance, value)
end

function State:SetFeatureInterval(key, value)
    local instance = self.Instances[key]
    if not instance then return false end
    if type(instance.SetInterval) ~= "function" then return false end
    return pcall(instance.SetInterval, instance, value)
end

function State:GetStatus()
    local on = 0
    for _, value in pairs(self.Toggles) do if value then on = on + 1 end end
    return {
        Version = self.Version,
        Features = self.Instances,
        Infra = self.Infra,
        Loaded = self.Features,
        TogglesOn = on,
        Errors = self.Errors,
    }
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    for name, instance in pairs(self.Instances) do
        if type(instance.Destroy) == "function" then pcall(instance.Destroy, instance) end
        self.Instances[name] = nil
    end
    for name, instance in pairs(self.Infra) do
        if type(instance.Destroy) == "function" then pcall(instance.Destroy, instance) end
        self.Infra[name] = nil
    end
    if env.__DEPHUB_BLOXFRUITS == self then env.__DEPHUB_BLOXFRUITS = nil end
    if env.__DEPHUB and env.__DEPHUB.BloxFruits == self then env.__DEPHUB.BloxFruits = nil end
    if env.__DEPHUB and env.__DEPHUB.BloxFruitsOwn == self then env.__DEPHUB.BloxFruitsOwn = nil end
end

env.__DEPHUB_BLOXFRUITS = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.BloxFruits = State
env.__DEPHUB.BloxFruitsOwn = State

-- Painel: a UI e construida pelo proprio backend, com a shell compartilhada,
-- para o script nao depender do adapter nem de um frontend externo.
--
-- Cada feature traz o proprio bloco de UI. O backend so posiciona (categoria,
-- aba, secao) e cria os controles que a feature declarou -- sem o backend
-- conhecer knob por knob. A categoria e sempre finalidade (Combat, Fruit), nao
-- nome de jogo, como manda a convencao.
local PANELS = {
    bladhits = {
        page = "Combat",
        section = "BLADE HITS",
        category = "Combat",
        icon = "swords",
        build = function(section, instance)
            section:CreateToggle("Blade hits", false, function(value)
                if value and not instance.Backend:SetFeature("bladhits", true) then
                    instance.Notify("Blade hits", "Remotes nao encontrados (Modules.Net).")
                end
                if not value then instance.Backend:SetFeature("bladhits", false) end
            end)
            section:CreateParagraph("Blade hits", "Auto-swing at every enemy in range using the game's attack remotes.")
        end,
    },
    fruit = {
        page = "Farm",
        section = "FRUIT",
        category = "Farm",
        icon = "cherry",
        build = function(section, instance)
            section:CreateToggle("Fruit ESP", false, function(value)
                while State.Instances.fruit == nil do task.wait() end
                State.Instances.fruit:SetEsp(value)
            end)
            section:CreateSlider("ESP max distance", 0, 2000, 0, function(value)
                if State.Instances.fruit then State.Instances.fruit:SetEspRange(value) end
            end)
            section:CreateToggle("Grab fruit", false, function(value)
                if value and not State:SetFeature("fruit", true) then
                    instance.Notify("Grab fruit", "Teleport motor ausente.")
                    return
                end
                if not value then State:SetFeature("fruit", false) end
                if State.Instances.fruit then State.Instances.fruit:SetGrab(value) end
            end)
            section:CreateSlider("Grab max distance", 0, 2000, 0, function(value)
                if State.Instances.fruit then State.Instances.fruit:SetRange(value) end
            end)
            section:CreateToggle("Auto store fruit", false, function(value)
                if State.Instances.fruit then State.Instances.fruit:SetStore(value) end
            end)
            section:CreateInput("Skip list", "Dragon, Rocket", "", function(text)
                if State.Instances.fruit then State.Instances.fruit:SetSkip(text) end
            end)
            section:CreateInput("Store keep list", "never store these", "", function(text)
                if State.Instances.fruit then State.Instances.fruit:SetKeep(text) end
            end)
        end,
    },
    islands = {
        page = "Travel",
        section = "ISLAND TELEPORT",
        category = "Travel",
        icon = "map",
        build = function(section, instance)
            -- O dropdown lista as ilhas do Sea 2 (confirmadas pelo usuario). A
            -- selecao NAO teleporta sozinha: e gate do toggle. Trocar a ilha com
            -- o toggle ligado voa de novo.
            local islands = {}
            local factory = State.Features.islands
            if factory and type(factory.islands) == "table" then
                islands = factory.islands
            end
            local selected = islands[1] or "Snow Mountain"
            -- O handle do toggle: a chegada precisa desligar ESTE controle
            -- (programaticamente), nao so a flag interna. SetValue dispara o
            -- callback, que por sua vez chama SetEnabled(false) -- um unico
            -- caminho de desligamento.
            local islandToggle = nil
            -- Ao CHEGAR na ilha, o toggle se desliga sozinho. So este toggle e
            -- mexido (a feature tem um so); nada mais e tocado. O hook e
            -- (re)ligado toda vez que o toggle e armado, porque a instancia da
            -- feature so nasce no primeiro SetFeature(..., true).
            local function wireArrivalHook()
                local feature = State.Instances.islands
                if not feature then return end
                feature.OnArrive = function(_, arrived)
                    if islandToggle and type(islandToggle.SetValue) == "function" then
                        islandToggle:SetValue(false)
                    elseif islandToggle and islandToggle.Value ~= nil then
                        islandToggle.Value = false
                    end
                    if arrived then
                        instance.Notify("Island teleport", ("Arrived at %s."):format(tostring(arrived)))
                    end
                end
            end
            islandToggle = section:CreateToggle("Island teleport", false, function(value)
                if value then
                    if not State:SetFeature("islands", true) then
                        instance.Notify("Island teleport", "Teleport motor ausente.")
                        return
                    end
                    wireArrivalHook()
                    if State.Instances.islands then
                        if not State.Instances.islands:SetEnabled(true) then
                            instance.Notify("Island teleport", State.Instances.islands.LastStatus or "falhou.")
                        end
                    end
                    return
                end
                if State.Instances.islands then State.Instances.islands:SetEnabled(false) end
                State:SetFeature("islands", false)
            end)
            -- A instancia pode ja existir (toggle reaberto nesta sessao): liga o
            -- hook de imediato tambem.
            wireArrivalHook()
            section:CreateDropdown("Island", islands, selected, function(choice)
                selected = choice
                if State.Instances.islands then
                    local ok = State.Instances.islands:Select(choice)
                    if State.Instances.islands.ToggleOn and not ok then
                        instance.Notify("Island teleport", State.Instances.islands.LastStatus or "ilha fora do mapa.")
                    end
                end
            end)
            section:CreateParagraph("Island teleport", "Pick an island and fly there. Only travels while the toggle is on.")
        end,
    },
    -- RAID: parked. O Auto raid e o Auto complete nao estavam do jeito que o
    -- usuario quer, entao a feature inteira saiu da lista ativa e foi para
    -- features/bloxfruits/parked/raid.lua -- nada foi apagado. Para trazer de
    -- volta, e so re-adicionar {name = "raid", page = "Farm", section = "RAID",
    -- toggle = "Auto raid"} em FEATURE_MODULES e recriar o raid no PANELS.
}

local visual = env.__DEPHUB and env.__DEPHUB.UI or nil
if type(visual) == "table" and type(visual.CreateTab) == "function" then
    local tabs = {}
    local categories = {}
    local helper = {
        Backend = State,
        Notify = function(title, body) visual:Notify(title, body) end,
    }
    for _, entry in ipairs(FEATURE_MODULES) do
        local panel = PANELS[entry.name]
        if panel and State.Features[entry.name] then
            if not categories[panel.category] then
                categories[panel.category] = true
                visual:CreateCategory(panel.category, panel.icon)
            end
            local tab = tabs[panel.page]
            if tab == nil then
                tab = visual:CreateTab(panel.page, panel.category, nil) or false
                tabs[panel.page] = tab
            end
            if tab then
                local section = tab:CreateSection(panel.section)
                if section then panel.build(section, helper) end
            end
        end
    end
    State.UIFrontend = visual
end

do
    local Diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.RegisterModule) == "function" then
        local function register(entry)
            local path = "features/bloxfruits/" .. entry.name .. ".lua"
            Diag:RegisterModule(path)
            local loaded = type(State.Features[entry.name]) == "table"
            local detail = loaded and "loaded" or "absent"
            if not loaded and type(State.Errors) == "table" then
                for _, err in ipairs(State.Errors) do
                    if tostring(err):find(entry.name, 1, true) then detail = tostring(err) break end
                end
            end
            Diag:Module(path, loaded, detail)
        end
        for _, entry in ipairs(FEATURE_MODULES) do register(entry) end
        for _, entry in ipairs(INFRA_MODULES) do register(entry) end
        Diag:Feature("BloxFruits.Toggles on", function() return tostring(State:GetStatus().TogglesOn) end)
        Diag:Feature("BloxFruits.Teleport", function() return State.Infra.teleport and "ready" or "absent" end)
        Diag:Feature("BloxFruits.LastError", function() return tostring(State.LastError or "none") end)
    end
end

return State

]],
    ["src/games/features/aotr/assistance.lua"] = [[
-- Optional helpers adapted from aotr_corrigido_v3. Paths remain runtime assumptions.
local Feature = {}
function Feature.new(context)
    local self = {Jobs = {}, States = {}, Injuries = {}, Destroyed = false}
    local player = context.Player
    local function path(root, ...)
        for _, name in ipairs({...}) do root = root and root:FindFirstChild(name) end
        return root
    end
    local function report(name, message)
        self.States[name] = tostring(message)
        context.Warn(name .. ": " .. tostring(message))
    end
    local function stop(name)
        local job = self.Jobs[name]
        self.Jobs[name] = nil
        if job then
            job.Active = false
            if job.Connection then job.Connection:Disconnect() end
            if job.Thread then pcall(task.cancel, job.Thread) end
        end
    end
    local function restoreInjuries()
        for injury, entry in pairs(self.Injuries) do
            -- Do not put injuries from a previous character into the new character.
            if entry.Character == player.Character and entry.Parent.Parent then
                local ok, err = pcall(function() injury.Parent = entry.Parent end)
                if not ok then report("AntiInjury", err) end
            else pcall(function() injury:Destroy() end) end
        end
        self.Injuries = {}
    end
    local function invoke(...)
        local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "GET")
        if not remote or not remote:IsA("RemoteFunction") then error("Assets.Remotes.GET unavailable") end
        return remote:InvokeServer(...)
    end
    local function top()
        return path(player, "PlayerGui", "Interface", "HUD", "Main", "Top")
    end
    local function visible(gui)
        if not gui or not gui:IsA("GuiObject") then return false end
        local item = gui
        while item and item ~= player do
            if item:IsA("GuiObject") and not item.Visible then return false end
            if item:IsA("ScreenGui") and not item.Enabled then return false end
            item = item.Parent
        end
        return true
    end
    local ticks = {}
    function ticks.AutoBladeRefill(job)
        local character = player.Character
        local blade = path(character, "Rig_" .. player.Name, "LeftHand", "Blade_1")
        if not blade or not blade:IsA("BasePart") then return "waiting: Rig/LeftHand/Blade_1" end
        if blade.Transparency ~= 1 then job.Reloading = nil; return "blade equipped" end
        if character:GetAttribute("IFrames") ~= nil then return "waiting: IFrames" end
        local hud = top()
        local sets = path(hud and hud:FindFirstChild("Blade", true), "Sets")
        if not sets or not (sets:IsA("TextLabel") or sets:IsA("TextButton")) then return "waiting: Blade.Sets" end
        local available = tonumber(sets.Text:match("(%d+)%s*/"))
        if not available or available <= 0 then return "no blade sets / unreadable HUD" end
        if job.Character ~= character then job.Character = character; job.Reloading = nil end
        job.Reloading = job.Reloading or os.clock()
        if os.clock() - job.Reloading >= 30 then return "reload timeout; toggle off/on to retry" end
        invoke("Blades", "Reload")
        return "reload requested (unverified)"
    end
    function ticks.AntiInjury()
        local folder = path(player.Character, "Injuries")
        if not folder then return "waiting: Character.Injuries" end
        for _, injury in ipairs(folder:GetChildren()) do
            self.Injuries[injury] = {Parent = folder, Character = player.Character}
            injury.Parent = nil -- retained for restoration; never destroy current injuries
        end
        for injury, entry in pairs(self.Injuries) do
            if entry.Character ~= player.Character then
                pcall(function() injury:Destroy() end)
                self.Injuries[injury] = nil
            end
        end
        return "client injuries detached; server effect unverified"
    end
    function ticks.AutoGrabEscape(job)
        local buttons = path(player, "PlayerGui", "Interface", "Buttons")
        if not buttons then return "waiting: Interface.Buttons" end
        if job.Folder ~= buttons then
            if job.Connection then job.Connection:Disconnect() end
            job.Folder = buttons
            job.Connection = buttons.ChildAdded:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "POST")
                    if not remote or not remote:IsA("RemoteEvent") then error("Assets.Remotes.POST unavailable") end
                    remote:FireServer("Attacks", "Slash_Escape")
                end)
                if not ok then report("AutoGrabEscape", err) end
            end)
        end
        return "listening: Buttons.ChildAdded (legacy trigger)"
    end
    function ticks.AutoRetry(job)
        local title = path(player, "PlayerGui", "Interface", "Rewards", "Main", "Info", "Main", "Buttons", "Retry", "Title")
        if not visible(title) or not (title:IsA("TextLabel") or title:IsA("TextButton")) then job.Requested = nil; return "waiting: visible Retry.Title" end
        if title.Text:find("STARTING", 1, true) or title.Text:find("(0/0)", 1, true) then job.Requested=nil; return "waiting: retry state" end
        if job.Requested == title then return "retry requested; waiting for next rewards screen" end
        invoke("Functions", "Retry", "Add")
        job.Requested = title
        return "retry requested (unverified)"
    end
    function self:SetToggle(name, enabled)
        if self.Destroyed then return false end
        if not ticks[name] and name ~= "AntiAFK" then return false end
        stop(name)
        if name == "AntiInjury" and not enabled then restoreInjuries() end
        self.States[name] = enabled and "starting" or "off"
        if not enabled then return true end
        local job = {Active = true}
        self.Jobs[name] = job
        if name == "AntiAFK" then
            job.Connection = player.Idled:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local virtualUser = game:GetService("VirtualUser")
                    virtualUser:CaptureController()
                    virtualUser:ClickButton2(Vector2.new())
                end)
                if not ok then report(name, err) end
            end)
            self.States[name] = "listening: Idled"
        else
            job.Thread = task.spawn(function()
                while job.Active and not self.Destroyed do
                    local ok, status = pcall(ticks[name], job)
                    if not job.Active or self.Destroyed then return end
                    if ok then self.States[name] = status else report(name, status) end
                    task.wait(name == "AutoBladeRefill" and 1 or 0.5)
                end
            end)
        end
        return true
    end
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed = true
        for name in pairs(self.Jobs) do stop(name) end
        restoreInjuries()
    end
    return self
end
return Feature

