    ["src/games/features/aotr/combat.lua"] = [[
-- Legacy remote contracts are unverified. States describe local work, never kills.
--
-- The three combat features drive the game's own remotes (Blades / Hitboxes /
-- S_Skills / Attacks / Functions). Every state string says "server unconfirmed"
-- on purpose: the client can only observe that a request was sent, so no state
-- here claims a kill or a reload actually happened server-side.
local Module={}
function Module.new(ctx)
    local path=ctx.Targets.Path
    local self={Jobs={},States={},Enabled={},Destroyed=false,CheckBusy=false,CheckResult="Disabled: not requested"}
    local effects,tracks={},{}
    local priorCharacterEffects={}
    local mover=ctx.Movement.new(ctx)
    self.Movement=mover
    function self:SetMovementSpeed(value) return mover:SetSpeed(value) end
    function self:SetNoclip(value) return mover:SetNoclip(value) end
    function self:PauseMovement() mover:Stop() end
    local ripperCharacter=nil
    local function state(name,value) self.States[name]=value end
    local function invoke(...)
        local remote=path(ctx.ReplicatedStorage,"Assets","Remotes","GET")
        if not remote or not remote:IsA("RemoteFunction") then error("Assets.Remotes.GET unavailable") end
        return remote:InvokeServer(...)
    end
    local function post(...)
        local remote=path(ctx.ReplicatedStorage,"Assets","Remotes","POST")
        if not remote or not remote:IsA("RemoteEvent") then error("Assets.Remotes.POST unavailable") end
        remote:FireServer(...)
    end
    local function restoreTracks()
        for track,speed in pairs(tracks) do pcall(function() track:AdjustSpeed(speed) end) end
        tracks={}
    end
    local function clearRipper()
        ctx.Properties:Clear("Ripper");restoreTracks();effects={}
    end
    local function stop(name)
        local job=self.Jobs[name];self.Jobs[name]=nil
        if job then job.Active=false;if job.Thread then pcall(task.cancel,job.Thread) end end
        if name=="Ripper" then clearRipper() end
        if name=="ClassicAutofarm" then mover:Stop() end
    end
    local function worker(name,tick,interval)
        if self.Jobs[name] then return end
        local job={Active=true,Character=ctx.Player.Character}
        self.Jobs[name]=job
        job.Thread=task.spawn(function()
            while job.Active and not self.Destroyed do
                local ok,result=pcall(tick,job)
                if not job.Active or self.Destroyed then return end
                if ok then state(name,result or "Running")
                else
                    state(name,"Error: "..tostring(result));ctx.Warn(name..": "..tostring(result))
                    if name=="Ripper" then clearRipper() end
                    if name=="ClassicAutofarm" then mover:Stop() end
                end
                task.wait(interval)
            end
        end)
    end
    local function ripperTick()
        local character=ctx.Player.Character
        if character~=ripperCharacter then clearRipper();ripperCharacter=character end
        if not ctx.Targets.Alive(character) then clearRipper();return "Waiting: alive character" end
        local now=ctx.Now()
        local selected=nil
        for _,part in ipairs(ctx.Workspace:GetChildren()) do
            if not priorCharacterEffects[part] and part:IsA("BasePart") and (part.Name==ctx.Player.Name.."_Steel" or part.Name==ctx.Player.Name.."_Thrust" or part.Name==ctx.Player.Name.."_RIP") then
                if not effects[part] then effects[part]=now+2 end
                if effects[part]>now and not selected then selected=part end
            end
        end
        for part in pairs(effects) do if not part.Parent then effects[part]=nil end end
        for part in pairs(priorCharacterEffects) do if not part.Parent then priorCharacterEffects[part]=nil end end
        if not selected then ctx.Properties:Clear("Ripper");restoreTracks();return "Waiting: own Steel / Thrust / RIP effect" end
        local desired={[selected]={Size=Vector3.new(125,125,125)}}
        local restorers={}
        local folder=path(ctx.Workspace,"Titans")
        local count=0
        for _,model in ipairs(folder and folder:GetChildren() or {}) do
            if model:IsA("Model") and model.Name~="Attack_Titan" then
                local nape=path(model,"Hitboxes","Hit","Nape")
                local head=path(model,"Fake","Head")
                if nape and nape:IsA("BasePart") and head and head:IsA("BasePart") then
                    -- Capture a head-relative transform once, not a guessed world position.
                    local original=ctx.Properties:Original(nape,"CFrame")
                    local offset=head.CFrame:ToObjectSpace(original)
                    restorers[nape]={CFrame=function() if head.Parent then return head.CFrame*offset end end}
                    desired[nape]={CFrame=selected.CFrame,Size=Vector3.new(150,150,150),Transparency=1}
                    count=count+1
                end
            end
        end
        ctx.Properties:Set("Ripper",desired,30,restorers)
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            for _,track in ipairs(animator:GetPlayingAnimationTracks()) do
                if tracks[track]==nil then tracks[track]=track.Speed end
                track:AdjustSpeed(0)
            end
        end
        return "Running: local effect, "..count.." napes (server unconfirmed)"
    end
    local function updateRipper()
        if self.Enabled.TitanRipper or self.Enabled.SkillAutofarm then worker("Ripper",ripperTick,0.1)
        else stop("Ripper");state("Ripper","Disabled") end
    end
    -- Names, icon IDs and delays originate in the supplied script; unknown slots are skipped.
    -- Icon-to-ID associations follow the three legacy skill names/sequence;
    -- unlike explicit SkillId attributes, these associations still need live validation.
    local sequence={{"108","15216496277",0.1},{"14","15215073606",2.5},{"23","15215081865",0.1},{"14","15215073606",0.5}}
    local function hotbar()
        return path(ctx.Player,"PlayerGui","Interface","HUD","Main","Top","7","Hotbar")
    end
    local function equipped(id,icon)
        local bar=hotbar()
        for _,slot in ipairs(bar and bar:GetChildren() or {}) do
            if slot.Name:find("Skill",1,true) then
                local image=path(slot,"Inner","Icon")
                local matches=slot:GetAttribute("SkillId")==id or tostring(slot:GetAttribute("SkillId") or "")==id
                if icon and image and (image:IsA("ImageLabel") or image:IsA("ImageButton")) then matches=matches or image.Image:match("(%d+)$")==icon end
                if matches then
                    local cooldown=path(slot,"Cooldown")
                    if not cooldown or not cooldown:IsA("GuiObject") then return false,"missing Cooldown" end
                    return not cooldown.Visible,cooldown.Visible and "cooldown" or "ready"
                end
            end
        end
        return false,"equipment not identified"
    end
    local function skillTick(job)
        if job.Character~=ctx.Player.Character then job.Character=ctx.Player.Character;job.Step=1;job.NextAt=0 end
        local root=ctx.Targets.Alive(job.Character)
        if not root then return "Waiting: alive character" end
        if root.Anchored or job.Character:GetAttribute("IFrames")==true then return "Waiting: character unavailable / IFrames" end
        if not ctx.Targets.Select(ctx.Workspace,root) then return "Waiting: live target" end
        if ctx.Now()<(job.NextAt or 0) then return "Waiting: sequence delay" end
        local index=job.Step or 1
        local step=sequence[index]
        local ready,reason=equipped(step[1],step[2])
        job.Step=index%#sequence+1
        job.NextAt=ctx.Now()+step[3]
        if not ready then return "Waiting: skill "..step[1].." / "..reason end
        state("SkillAutofarm","Running: requesting skill "..step[1].." (server unconfirmed)")
        invoke("S_Skills","Usage",step[1])
        return "Running: skill "..step[1].." requested (server unconfirmed)"
    end
    local function classicTick(job)
        if job.Character~=ctx.Player.Character then mover:Stop();job.Character=ctx.Player.Character;job.NextAttack=0;job.Target=nil end
        local root=ctx.Targets.Alive(job.Character)
        if not root then mover:Stop();return "Waiting: alive character" end
        if root.Anchored or job.Character:GetAttribute("IFrames")==true then mover:Stop();return "Waiting: character unavailable / IFrames" end
        if ctx.IsTeleporting() then mover:Stop();return "Waiting: refill teleport" end
        local blade=path(job.Character,"Rig_"..ctx.Player.Name,"LeftHand","Blade_1")
        if not blade or not blade:IsA("BasePart") then mover:Stop();return "Waiting: blade reference" end
        if blade.Transparency==1 then
            local top=path(ctx.Player,"PlayerGui","Interface","HUD","Main","Top")
            local sets=path(top and top:FindFirstChild("Blade",true),"Sets")
            local available=sets and (sets:IsA("TextLabel") or sets:IsA("TextButton")) and tonumber(sets.Text:match("(%d+)%s*/"))
            if available~=0 then mover:Stop();return "Waiting: blade reload / enable Blade Refill" end
            local refill=ctx.FindRefill()
            if not refill then mover:Stop();return "Waiting: GasTanks.Refill" end
            mover:Move(root,refill,3)
            if (root.Position-refill.Position).Magnitude>20 then return "Running: approaching refill" end
            if ctx.Now()<(job.NextRefill or 0) then return "Waiting: refill response / HUD confirmation" end
            job.NextRefill=ctx.Now()+5
            state("ClassicAutofarm","Running: requesting full reload (server unconfirmed)")
            invoke("Blades","Full_Reload","Left",refill)
            if not job.Active or self.Destroyed or job.Character~=ctx.Player.Character then return "Waiting: character changed" end
            invoke("Blades","Full_Reload","Right",refill)
            return "Waiting: full reload requested / HUD confirmation"
        end
        local target=job.Target
        local folder=path(ctx.Workspace,"Titans")
        local humanoid=target and target.Model:FindFirstChildOfClass("Humanoid")
        if target and (not target.Part.Parent or target.Model.Parent~=folder or not humanoid or humanoid.Health<=0
            or (target.Boss and ctx.Targets.Marker(target.Model)~=target.Part)) then target=nil end
        local distance
        if not target then target,distance=ctx.Targets.Select(ctx.Workspace,root) end
        job.Target=target
        if not target then mover:Stop();return distance end
        mover:Move(root,target.Part,target.Boss and 195 or 75,target.Model)
        -- Recheck the live target/root immediately before sending an attack.
        if not target.Part.Parent or not target.Model.Parent then mover:Stop();return "Waiting: target removed" end
        distance=(root.Position-target.Part.Position).Magnitude
        if ctx.Now()<(job.NextAttack or 0) then return "Running: moving toward "..target.Model.Name end
        if distance>(target.Boss and 250 or 175) then return "Running: approaching target" end
        job.NextAttack=ctx.Now()+1
        post("Attacks","Slash",true)
        if not job.Active or self.Destroyed or job.Character~=ctx.Player.Character then return "Waiting: character changed" end
        state("ClassicAutofarm","Running: registering local target (server unconfirmed)")
        -- Preserve the reference contract without inventing random hit speed/damage.
        invoke("Hitboxes","Register",target.Part,root.AssemblyLinearVelocity.Magnitude,0)
        return "Running: attack requested (server unconfirmed)"
    end
    function self:SetToggle(name,enabled)
        if self.Destroyed or (name~="TitanRipper" and name~="SkillAutofarm" and name~="ClassicAutofarm") then return false end
        enabled=enabled==true
        if self.Enabled[name]==enabled then return true end
        self.Enabled[name]=enabled
        state(name,enabled and "Waiting: starting" or "Disabled")
        if name=="SkillAutofarm" then
            if enabled then worker(name,skillTick,0.2) else stop(name) end
        elseif name=="ClassicAutofarm" then
            if enabled then ctx.CancelTeleport();worker(name,classicTick,0.15) else stop(name) end
        end
        updateRipper()
        return true
    end
    function self:CheckShadowBan()
        if self.Destroyed or self.CheckBusy then return false end
        if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog);self.CheckWatchdog=nil end
        self.CheckToken=(self.CheckToken or 0)+1
        local token=self.CheckToken
        self.CheckBusy=true;self.CheckResult="Running: requesting account diagnostic"
        self.CheckThread=task.spawn(function()
            local ok,data=pcall(invoke,"Data","Get")
            if self.Destroyed or token~=self.CheckToken then return end
            self.CheckBusy=false;self.CheckThread=nil
            if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog);self.CheckWatchdog=nil end
            -- No reliable schema was supplied. Inspect types, never infer a ban verdict.
            if not ok then self.CheckResult="Error: "..tostring(data);ctx.Warn(self.CheckResult)
            elseif type(data)~="table" then self.CheckResult="Waiting: inconclusive / response is "..type(data)
            else
                local count=0
                for key in pairs(data) do if type(key)=="string" and key:lower():find("blacklist",1,true) then count=count+1 end end
                self.CheckResult="Waiting: inconclusive / "..count.." blacklist-like fields; schema unverified"
            end
        end)
        if self.CheckBusy then self.CheckWatchdog=task.spawn(function()
            task.wait(15)
            if self.Destroyed or token~=self.CheckToken or not self.CheckBusy then return end
            self.CheckToken=self.CheckToken+1
            if self.CheckThread then pcall(task.cancel,self.CheckThread);self.CheckThread=nil end
            self.CheckBusy=false
            self.CheckResult="Error: diagnostic timeout; result inconclusive"
            ctx.Warn(self.CheckResult)
        end) end
        return true
    end
    self.Respawn=ctx.Player.CharacterRemoving:Connect(function()
        for part in pairs(effects) do priorCharacterEffects[part]=true end
        mover:Stop();clearRipper()
        -- Cancel in-flight workers on character removal, without changing user's toggles.
        for _,name in ipairs({"Ripper","SkillAutofarm","ClassicAutofarm"}) do stop(name) end
        for name,enabled in pairs(self.Enabled) do if enabled then state(name,"Waiting: respawn") end end
    end)
    self.CharacterAdded=ctx.Player.CharacterAdded:Connect(function()
        if self.Destroyed then return end
        if self.Enabled.SkillAutofarm then worker("SkillAutofarm",skillTick,0.2) end
        if self.Enabled.ClassicAutofarm then worker("ClassicAutofarm",classicTick,0.15) end
        updateRipper()
    end)
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed=true
        self.Respawn:Disconnect();self.CharacterAdded:Disconnect()
        for _,name in ipairs({"Ripper","SkillAutofarm","ClassicAutofarm"}) do stop(name) end
        if self.CheckThread then pcall(task.cancel,self.CheckThread) end
        if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog) end
        self.CheckBusy=false;mover:Destroy()
    end
    return self
end
return Module

]],
    ["src/games/features/aotr/movement.lua"] = [[
-- Owned tween/hold and character-only noclip. No map edits or game mover writes.
--
-- The farm needs to fly to a nape and the player wants to pass through geometry
-- while doing it, but every change here is character-local (CanCollide on the
-- character's own parts) and is restored on Stop, so leaving the game clean is
-- never dependent on a feature turning itself off first.
local Module={}
function Module.new(context)
    context=context or {}
    local self={Root=nil,Character=nil,Speed=1000,Noclip=true,Collisions={},Destroyed=false}
    local function cancelTween()
        if self.Completed then self.Completed:Disconnect();self.Completed=nil end
        local tween=self.Tween;self.Tween=nil
        if tween then tween:Cancel() end
        self.Arrived=false
    end
    local function restoreCollisions()
        for part,value in pairs(self.Collisions) do
            if part.Parent then pcall(function() part.CanCollide=value end) end
        end
        self.Collisions={}
    end
    local function noclip()
        if not self.Noclip or not self.Character then return end
        for part,value in pairs(self.Collisions) do
            if not part:IsDescendantOf(self.Character) then
                if part.Parent then pcall(function() part.CanCollide=value end) end
                self.Collisions[part]=nil
            end
        end
        for _,part in ipairs(self.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                if self.Collisions[part]==nil then self.Collisions[part]=part.CanCollide end
                part.CanCollide=false
            end
        end
    end
    function self:Stop()
        cancelTween()
        if self.Step then self.Step:Disconnect();self.Step=nil end
        if self.Hold then self.Hold:Destroy();self.Hold=nil end
        restoreCollisions()
        if self.Root and self.Root.Parent then
            if self.Rotation then pcall(function() self.Root.CFrame=CFrame.new(self.Root.Position)*self.Rotation end) end
            pcall(function() self.Root.AssemblyLinearVelocity=self.Velocity end)
            pcall(function() self.Root.AssemblyAngularVelocity=self.AngularVelocity end)
        end
        if self.Humanoid and self.Humanoid.Parent then pcall(function() self.Humanoid.AutoRotate=self.AutoRotate end) end
        self.Humanoid=nil;self.Rotation=nil
        self.Root=nil;self.Character=nil;self.Target=nil;self.TargetModel=nil;self.Goal=nil
    end
    function self:SetSpeed(value)
        value=tonumber(value)
        if self.Destroyed or not value or value~=value or value<50 or value>2000 then return false end
        if self.Speed~=value then self.Speed=value;cancelTween();self.Goal=nil end
        return true
    end
    function self:SetNoclip(value)
        if self.Destroyed then return false end
        self.Noclip=value==true
        if self.Noclip then noclip() else restoreCollisions() end
        return true
    end
    function self:Move(root,target,height,targetModel)
        if self.Destroyed then return false end
        if not root.Parent or not target.Parent then self:Stop();return false end
        if self.Root~=root then
            self:Stop();self.Root=root;self.Character=root.Parent
            self.Velocity=root.AssemblyLinearVelocity;self.AngularVelocity=root.AssemblyAngularVelocity
            self.Rotation=root.CFrame.Rotation
            self.Humanoid=self.Character:FindFirstChildOfClass("Humanoid")
            if self.Humanoid then self.AutoRotate=self.Humanoid.AutoRotate;self.Humanoid.AutoRotate=false end
            self.Hold=Instance.new("BodyVelocity")
            self.Hold.Name="DepHub_AOTR_FarmHold"
            self.Hold.MaxForce=Vector3.new(1000000,1000000,1000000)
            self.Hold.Velocity=Vector3.new(0,0,0);self.Hold.Parent=root
            noclip()
            local run=context.RunService or game:GetService("RunService")
            self.Step=run.Stepped:Connect(function()
                local ok,err=pcall(function()
                    local humanoid=self.Character and self.Character:FindFirstChildOfClass("Humanoid")
                    local targetHumanoid=self.TargetModel and self.TargetModel:FindFirstChildOfClass("Humanoid")
                    if not self.Root or not self.Root.Parent or self.Root.Anchored or not humanoid or humanoid.Health<=0
                        or (self.Target and not self.Target.Parent)
                        or (self.TargetModel and (not self.TargetModel.Parent or not targetHumanoid or targetHumanoid.Health<=0))
                        or (context.Player and context.Player.Character~=self.Character) then self:Stop();return end
                    noclip()
                    self.Root.AssemblyAngularVelocity=Vector3.new(0,0,0)
                end)
                if not ok then self:Stop();if context.Warn then context.Warn("movement: "..tostring(err)) end end
            end)
        end
        noclip()
        self.TargetModel=targetModel
        local goal=target.Position+Vector3.new(0,height,0)
        local distance=(goal-root.Position).Magnitude
        if distance~=distance or distance>10000000 then self:Stop();error("Invalid movement distance") end
        if self.Target==target and self.Goal and (goal-self.Goal.Position).Magnitude<8 then
            if self.Tween or (self.Arrived and distance<4) then return true end
        end
        cancelTween();self.Target=target
        -- The target is directly below the hover point; use a nonparallel up axis.
        self.Goal=CFrame.lookAt(goal,target.Position,Vector3.new(0,0,1))
        if distance<0.5 then root.CFrame=self.Goal;self.Arrived=true;return true end
        local service=context.TweenService or game:GetService("TweenService")
        local tween=service:Create(root,TweenInfo.new(math.max(0.03,distance/self.Speed),Enum.EasingStyle.Linear),{CFrame=self.Goal})
        self.Tween=tween
        self.Completed=tween.Completed:Connect(function(state)
            if self.Tween~=tween then return end
            self.Tween=nil;self.Arrived=state==Enum.PlaybackState.Completed
            if self.Completed then self.Completed:Disconnect();self.Completed=nil end
        end)
        tween:Play()
        return true
    end
    function self:Destroy() if not self.Destroyed then self:Stop();self.Destroyed=true end end
    return self
end
return Module

]],
    ["src/games/features/aotr/properties.lua"] = [[
-- Property layers prevent one feature from restoring over another feature.
--
-- Several AOT:R features write the same property on the same object (the nape's
-- CFrame is touched by both the nape visual and the ripper). Recording the
-- original value once and letting the highest-priority layer win means turning
-- one feature off never clobbers another that is still on.
local Module = {}
function Module.new(warnError)
    local self = {Records={}, Layers={}}
    local function write(object, key, value)
        local ok, err = pcall(function() object[key]=value end)
        if not ok and warnError then warnError("restore "..key..": "..tostring(err)) end
    end
    function self:Original(object, key)
        local record=self.Records[object]
        return record and record[key] and record[key].Value or object[key]
    end
    function self:Refresh()
        for object, record in pairs(self.Records) do
            for key, saved in pairs(record) do
                local value, priority, claimed=nil,-math.huge,false
                for _, layer in pairs(self.Layers) do
                    local values=layer.Values[object]
                    if values and values[key]~=nil and layer.Priority>priority then
                        value,priority,claimed=values[key],layer.Priority,true
                    end
                end
                if claimed then write(object,key,value)
                else
                    local restored=saved.Value
                    if saved.Restore then
                        local ok, result=pcall(saved.Restore)
                        if ok and result~=nil then restored=result end
                    end
                    write(object,key,restored)
                    record[key]=nil
                end
            end
            if next(record)==nil then self.Records[object]=nil end
        end
    end
    function self:Set(owner, values, priority, restorers)
        for object, properties in pairs(values) do
            local record=self.Records[object] or {};self.Records[object]=record
            for key in pairs(properties) do
                if not record[key] then
                    record[key]={Value=object[key],Restore=restorers and restorers[object] and restorers[object][key]}
                end
            end
        end
        self.Layers[owner]={Values=values,Priority=priority or 0}
        self:Refresh()
    end
    function self:Clear(owner) self.Layers[owner]=nil;self:Refresh() end
    function self:Destroy() self.Layers={};self:Refresh() end
    return self
end
return Module

]],
    ["src/games/features/aotr/targets.lua"] = [[
-- Target selection for AOT:R: which titan (and which weakpoint) is live.
--
-- The nape is the kill part; a boss (Attack_Titan) exposes whatever its Marker
-- currently decorates. Returning nil instead of guessing keeps the farm from
-- attacking a part that no longer exists.
local Module={}
local function path(root,...)
    for _,name in ipairs({...}) do root=root and root:FindFirstChild(name) end
    return root
end
Module.Path=path
function Module.Alive(character)
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=path(character,"HumanoidRootPart")
    if not humanoid or humanoid.Health<=0 or not root or not root:IsA("BasePart") then return nil end
    return root,humanoid
end
function Module.Marker(model)
    local marker=path(model,"Marker")
    local hit=path(model,"Hitboxes","Hit")
    if not marker or not hit then return nil end
    local ok,part=pcall(function() return marker.Adornee end)
    if ok and part and part:IsA("BasePart") and part:IsDescendantOf(hit) then return part end
    return nil
end
function Module.Select(workspace,root)
    local folder=path(workspace,"Titans")
    if not folder or not root then return nil,"Waiting: Titans / character" end
    local best,distance=nil,math.huge
    for _,model in ipairs(folder:GetChildren()) do
        local humanoid=model:IsA("Model") and model:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health>0 then
            -- A boss with no active marker must not fall back to an arbitrary weakpoint.
            local part=model.Name=="Attack_Titan" and Module.Marker(model) or nil
            if model.Name~="Attack_Titan" then part=path(model,"Hitboxes","Hit","Nape") end
            if part and part:IsA("BasePart") then
                local d=(root.Position-part.Position).Magnitude
                if d<distance then best,distance={Model=model,Part=part,Boss=model.Name=="Attack_Titan"},d end
            end
        end
    end
    return best,best and distance or "Waiting: live target / boss marker"
end
return Module

]],
    ["src/games/features/bloxfruits/bladhits.lua"] = [[
local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring
local workspace = game:GetService("Workspace")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

-- Blade Hits -- o auto-hit do Blox Fruits.
--
-- Ele nao usa tool:Activate() nem input: dispara os remotes do proprio jogo
-- (RE/RegisterAttack + RE/RegisterHit) direto, que e o que faz um loop de
-- farm/mastery funcionar de verdade -- o golpe chega no inimigo mesmo quando a
-- animacao do swing nao alcancaria.
--
-- Self-contained de proposito: nada do DepHub, nada do adapter OSS. Faz o
-- proprio game:GetService e publica um modulo com new()/Enable()/Disable().
-- Assim ele pode ser colado em qualquer lugar, ou carregado por um backend
-- (o src/games/bloxfruits.lua faz isso), sem arrastar dependencia junto.

local Feature = {}
Feature.__index = Feature

-- Timing humanizado: varia cada espera pra o loop nao ser perfeitamente
-- periodico. Foi por isso que o original nao usava um wait(0.1) cravado.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local function alive(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health > 0
end

function Feature.new(options)
    options = options or {}
    local self = setmetatable({}, Feature)
    self.Enabled = false
    self.Thread = nil
    self.hits = 0
    -- Sem UI de range/intervalo: os valores sao fixos no melhor que funciona.
    -- Range 300 cobre o pack inteiro de mobs do BF (as pastas Enemies/Characters
    -- ficam densas), e 0.05s e o piso que ainda deixa o servidor aceitar os hits
    -- sem derrubar por spam -- o jitter de 25% em cima disso tira a cadencia
    -- perfeitamente periodica que o anti-cheat procura.
    self.MinInterval = options.interval or 0.05
    self.AttackRange = options.range or 300
    self.PlayerRange = options.playerRange or 60
    self.Players = options.players or false
    self.EnemiesFolder = options.enemiesFolder ~= false
    self.CharactersFolder = options.charactersFolder ~= false
    self.LastHitId = options.hitId or nil
    self.RegisterAttack = nil
    self.RegisterHit = nil
    return self
end

-- Resolve os remotes. Tenta Modules.Net (caminho atual do jogo) e cai pro Net
-- solto em ReplicatedStorage, que e o caminho de builds mais antigas.
function Feature:ResolveRemotes()
    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local net = (modules and modules:FindFirstChild("Net")) or ReplicatedStorage:FindFirstChild("Net")
    if not net then return false end
    local attack = net:FindFirstChild("RE/RegisterAttack")
    local hit = net:FindFirstChild("RE/RegisterHit")
    if not attack or not hit then return false end
    self.RegisterAttack = attack
    self.RegisterHit = hit
    return true
end

function Feature:_root()
    local character = LocalPlayer and LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

-- Junta todo alvo vivo no alcance. Varre as pastas que o jogo usa pra mobs e
-- pra outros personagens; players sao opcionais e tem alcance proprio.
function Feature:CollectEnemies(range)
    range = range or self.AttackRange
    local root = self:_root()
    if not root then return {} end
    local list = {}
    local function scan(folder)
        if not folder then return end
        for _, enemy in ipairs(folder:GetChildren()) do
            if enemy ~= LocalPlayer.Character then
                local humanoid = enemy:FindFirstChildOfClass("Humanoid")
                local part = enemy:FindFirstChild("Head") or enemy:FindFirstChild("HumanoidRootPart")
                if humanoid and humanoid.Health > 0 and part then
                    local distance = (part.Position - root.Position).Magnitude
                    if distance <= range then
                        list[#list + 1] = {model = enemy, part = part, distance = distance}
                    end
                end
            end
        end
    end
    if self.EnemiesFolder then scan(workspace:FindFirstChild("Enemies")) end
    if self.CharactersFolder then scan(workspace:FindFirstChild("Characters")) end
    if self.Players then
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player ~= LocalPlayer and player.Character
            local part = character and character:FindFirstChild("HumanoidRootPart")
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if part and humanoid and humanoid.Health > 0 then
                local distance = (part.Position - root.Position).Magnitude
                if distance <= self.PlayerRange then
                    list[#list + 1] = {model = character, part = part, distance = distance}
                end
            end
        end
    end
    table.sort(list, function(a, b) return a.distance < b.distance end)
    return list
end

-- Dispara os remotes em todos os alvos no alcance. O combo cicla 1..4 pra as
-- chaves de animacao alternarem do jeito que o jogo espera. O 4. argumento do
-- RegisterHit e o hitId validado no servidor: sem ele um hit forjado e ignorado
-- em conta nova, por isso ele vem de LastHitId (ver SetHitId).
function Feature:AttackNearest(range)
    if not (self.RegisterAttack and self.RegisterHit) then return false end
    local targets = self:CollectEnemies(range)
    if #targets == 0 then return false end
    self._combo = ((self._combo or 0) % 4) + 1
    pcall(function() self.RegisterAttack:FireServer(0.4, self._combo) end)
    for _, target in ipairs(targets) do
        pcall(function() self.RegisterHit:FireServer(target.part, {}, nil, self.LastHitId) end)
    end
    self.hits = self.hits + 1
    return true
end

function Feature:SetHitId(value)
    if value ~= nil then self.LastHitId = value end
end

function Feature:Enable()
    if self.Enabled then return true end
    if not self:ResolveRemotes() then return false end
    self.Enabled = true
    self.Thread = task.spawn(function()
        while self.Enabled do
            if alive(LocalPlayer.Character) then pcall(function() self:AttackNearest() end) end
            jitter(self.MinInterval, 0.25)
        end
        self.Thread = nil
    end)
    return true
end

function Feature:Disable()
    self.Enabled = false
    if self.Thread then pcall(task.cancel, self.Thread); self.Thread = nil end
    return true
end

function Feature:SetRange(value)
    value = tonumber(value)
    if not value or value <= 0 then return false end
    self.AttackRange = value
    return true
end

function Feature:SetInterval(value)
    value = tonumber(value)
    if not value or value <= 0 then return false end
    self.MinInterval = value
    return true
end

function Feature:IsEnabled() return self.Enabled end

function Feature:Destroy()
    self:Disable()
    self.RegisterAttack = nil
    self.RegisterHit = nil
end

return Feature

]],
    ["src/games/features/bloxfruits/fruit.lua"] = [[
local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring
local tonumber = tonumber
local math = math

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local workspace = game:GetService("Workspace")
local LocalPlayer = Players.LocalPlayer

-- Fruits -- pegar fruta do chao, no molde proprio.
--
-- Portado do script antigo (parked/fruits.lua), mas so a parte de FRUTA:
-- ESP, grab e store. O que estava misturado la (gacha, dealer, awakening,
-- baús) fica de fora -- se for trazido, e noutra feature.
--
-- A parte que importa: isto NAO tem teleporte proprio. Ele pega o motor geral
-- (features/bloxfruits/teleport.lua) por injeção e usa tp:GoToInstance(part).
-- Era assim no script antigo tambem -- fruits chamava o modulo de teleporte.
-- A blade hit e a fruta agora compartilham UM teleporte, testado.
--
-- Self-contained: faz os proprios game:GetService e nao depende do DepHub. So
-- pede o motor de teleporte, e mesmo assim de forma opcional (sem ele o ESP e
-- o store ainda funcionam; so o grab nao voa).

local Feature = {}
Feature.__index = Feature

-- --- Deteccao de fruta no chao ---------------------------------------------
-- Uma fruta no chao aparece de DUAS formas no Blox Fruits, e a versao antiga so
-- via a segunda -- por isso a fruta SPAWNADA pelo jogo nunca ganhava ESP nem
-- grab:
--   1. Spawnada pelo jogo: um Model chamado "Fruit"/"fruit" em Workspace, SEM
--      Handle (o Handle/ProximityPrompt so nasce quando o jogador encosta). Este
--      e o caso que estava sendo jogado fora pelo filtro antigo (so aceitava
--      Tool).
--   2. Dropada por jogador / ja virada item: um Tool com OriginalName
--      ("Dragon-Dragon Fruit") e Handle.
-- A deteccao aceita as duas. Para o Tool o nome bom e o OriginalName; para o
-- Model e o proprio .Name.

-- O nome e "Fruit"-like? (spawn do jogo). Compara sem diferenciar maiuscula e
-- aceita "fruit" e "fruits" -- substring nao pega "Fruit" maiusculo se eu so
-- testar igualdade, entao testo prefixo no minusculo.
local function looksLikeFruitModel(instance)
    local name = tostring(instance.Name):lower()
    return name == "fruit" or name == "fruits" or name:sub(1, 5) == "fruit"
end

-- A parte fisica pra adorno/teleporte. Tool -> Handle ou a primeira BasePart;
-- Model/Part -> a primeira BasePart descendente (a fruta spawnada e um Model sem
-- Handle, entao a parte esta la dentro).
local function fruitPart(fruit)
    if fruit:IsA("BasePart") then return fruit end
    return fruit:FindFirstChild("Handle") or fruit:FindFirstChildWhichIsA("BasePart")
end

-- Uma fruta no chao e um Tool (com OriginalName/Handle) OU um Model "Fruit" que
-- o jogo spawnou. Um Model qualquer do mapa -- com outra geometria -- nao passa:
-- so o que tem nome Fruit-like, pra nao poluir o ESP com o mapa inteiro.
local function isGroundFruit(instance)
    if instance:IsA("Tool") then
        local named = instance:GetAttribute("OriginalName") or tostring(instance.Name):find("-")
        return named ~= nil and fruitPart(instance) ~= nil
    end
    if instance:IsA("Model") or instance:IsA("BasePart") then
        return looksLikeFruitModel(instance) and fruitPart(instance) ~= nil
    end
    return false
end

-- As chaves de nome usadas pro skip/keep. Tool -> OriginalName + Name; Model
-- spawnado -> o proprio Name (que pode ser so "Fruit"; o nome real da fruta
-- aparece quando ela vira Tool). Por isso o skip/keep casa melhor em Tool --
-- mas o ESP/grab nunca dependem disso.
local function fruitNameKeys(fruit)
    local keys = {}
    local original = fruit:GetAttribute("OriginalName")
    if original then keys[#keys + 1] = tostring(original):lower() end
    if fruit.Name then keys[#keys + 1] = tostring(fruit.Name):lower() end
    return keys
end

local function nameInSet(set, fruit)
    if not set or not next(set) then return false end
    for _, key in ipairs(fruitNameKeys(fruit)) do
        for name in pairs(set) do
            if key:find(name, 1, true) == 1 then return true end
        end
    end
    return false
end

function Feature.new(options)
    options = options or {}
    local self = setmetatable({}, Feature)
    self.Enabled = false
    self.GrabEnabled = false
    self.EspEnabled = false
    self.StoreEnabled = false
    self.Threads = {}
    self.EspMap = {}
    -- O motor de teleporte geral. Sem ele o ESP e o store ainda rodam; so o
    -- grab recusa (nao tem como voar ate a fruta).
    self.Teleport = options.teleport or nil
    self.Range = options.range or 0            -- 0 = pega de qualquer distancia
    self.EspRange = options.espRange or 0      -- 0 = mostra toda fruta
    self.Skip = options.skip or {}             -- frutas nunca pegas (prefixo)
    self.Keep = options.keep or {}             -- frutas nunca guardadas
    self.StoreInterval = options.storeInterval or 2
    self.LastError = nil
    return self
end

function Feature:SetTeleport(motor)
    self.Teleport = motor
    return self.Teleport ~= nil
end

function Feature:_hrp()
    local character = LocalPlayer and LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

function Feature:_commF()
    local remotes = ReplicatedStorage:FindFirstChild("Remotes")
    return remotes and remotes:FindFirstChild("CommF_")
end

-- Todas as frutas no chao -- spawnada pelo jogo (Model "Fruit") e dropada
-- (Tool com OriginalName/Handle). A deteccao e isGroundFruit; ver o cabecalho
-- acima pro porque dos dois casos.
function Feature:GroundFruits()
    local list = {}
    for _, child in ipairs(workspace:GetChildren()) do
        if isGroundFruit(child) then list[#list + 1] = child end
    end
    return list
end

function Feature:NearestGroundFruit(skip)
    local root = self:_hrp()
    local best, bestPart, bestDistance
    local maxRange = tonumber(self.Range) or 0
    for _, fruit in ipairs(self:GroundFruits()) do
        local part = fruitPart(fruit)
        if part and not (skip and skip[fruit]) and not nameInSet(self.Skip, fruit) then
            local distance = root and (part.Position - root.Position).Magnitude or 0
            if (maxRange <= 0 or distance <= maxRange) and (not bestDistance or distance < bestDistance) then
                best, bestPart, bestDistance = fruit, part, distance
            end
        end
    end
    return best, bestPart
end

-- --- ESP ------------------------------------------------------------------
-- Destaca as frutas no chao com Highlight + BillboardGui mostrando nome e
-- distancia. O mapa de adornos e mantido entre frames e limpo no disable.

function Feature:_spawn(name, body)
    self.Threads[name] = task.spawn(body)
end

function Feature:_cancel(name)
    local thread = self.Threads[name]
    if thread then pcall(task.cancel, thread); self.Threads[name] = nil end
end

function Feature:SetEsp(on)
    self.EspEnabled = on == true
    if not self.EspEnabled then
        for _, entry in pairs(self.EspMap) do
            pcall(function() entry.highlight:Destroy(); entry.billboard:Destroy() end)
        end
        self.EspMap = {}
        self:_cancel("esp")
        return true
    end
    self:_spawn("esp", function()
        while self.EspEnabled do
            local live = {}
            local root = self:_hrp()
            for _, fruit in ipairs(self:GroundFruits()) do
                local part = fruitPart(fruit)
                if part then
                    live[fruit] = true
                    local entry = self.EspMap[fruit]
                    -- A parte da fruta pode MUDAR: a spawnada e um Model e a
                    -- parte viva pode ser re-parented enquanto existe. Se o
                    -- adorno aponta pra uma parte que nao e mais a atual, ele
                    -- fica orfao (o "tabugado" que o usuario viu): entao
                    -- re-aponta em vez de fingir que esta tudo bem.
                    if entry and entry.part ~= part then
                        pcall(function() entry.highlight:Destroy(); entry.billboard:Destroy() end)
                        self.EspMap[fruit] = nil
                        entry = nil
                    end
                    if not entry then
                        local highlight = Instance.new("Highlight")
                        highlight.FillColor = Color3.fromRGB(120, 220, 255)
                        highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
                        highlight.Adornee = part
                        highlight.Parent = part
                        local billboard = Instance.new("BillboardGui")
                        billboard.Size = UDim2.fromOffset(150, 20)
                        billboard.StudsOffset = Vector3.new(0, 2.5, 0)
                        billboard.AlwaysOnTop = true
                        billboard.Adornee = part
                        billboard.Parent = part
                        local label = Instance.new("TextLabel")
                        label.BackgroundTransparency = 1
                        label.Size = UDim2.fromScale(1, 1)
                        label.Font = Enum.Font.GothamBold
                        label.TextSize = 13
                        label.TextColor3 = Color3.fromRGB(120, 220, 255)
                        label.TextStrokeTransparency = 0.4
                        label.Parent = billboard
                        entry = {highlight = highlight, billboard = billboard, label = label, part = part}
                        self.EspMap[fruit] = entry
                    end
                    local distance = root and math.floor((part.Position - root.Position).Magnitude) or 0
                    local maxRange = tonumber(self.EspRange) or 0
                    local shown = (maxRange <= 0) or (distance <= maxRange)
                    entry.highlight.Enabled = shown
                    entry.billboard.Enabled = shown
                    -- Fruta spawnada chama-se so "Fruit"; mostra o nome real se
                    -- houver OriginalName, senao o proprio Name.
                    local label = fruit:GetAttribute("OriginalName") or fruit.Name
                    entry.label.Text = ("%s  %dm"):format(label, distance)
                end
            end
            for fruit, entry in pairs(self.EspMap) do
                if not live[fruit] then
                    pcall(function() entry.highlight:Destroy(); entry.billboard:Destroy() end)
                    self.EspMap[fruit] = nil
                end
            end
            task.wait(0.5)
        end
    end)
    return true
end

-- --- Grab -----------------------------------------------------------------
-- Acha a fruta mais perto, voa ate ela com o motor de teleporte, e dispara o
-- ProximityPrompt da fruta (fireproximityprompt) quando ele existe. Um passo por
-- vez, com o loop indo pra proxima -- igual ao collectNearestOnce do original.
--
-- ARMADILHA (a fruta spawnada): o Model "Fruit" do jogo NAO tem Handle nem
-- ProximityPrompt enquanto ninguem encostou -- o prompt so nasce no toque. Entao
-- fireproximityprompt nao acha nada pra disparar. Nesse caso o grab E o proprio
-- TOQUE: o motor voa ATE a fruta, e encostar nela faz o jogo virar o Model em
-- Tool (ai sim coletavel). Por isso o CollectNearestOnce dispara o prompt quando
-- houver (fruta dropada: caminho mais rapido) e sempre garante o voo ate a
-- fruta -- o encosto faz o resto.

function Feature:_fireFruitPrompt(fruit)
    local prompt = fruit:FindFirstChildWhichIsA("ProximityPrompt")
    if not prompt then
        for _, descendant in ipairs(fruit:GetDescendants()) do
            if descendant:IsA("ProximityPrompt") then prompt = descendant break end
        end
    end
    if not prompt then return false end
    local fire = fireproximityprompt
    if type(fire) ~= "function" then return false end
    local ok = pcall(fire, prompt)
    return ok
end

function Feature:CollectNearestOnce()
    local fruit, part = self:NearestGroundFruit()
    if not (fruit and part) then return false end
    local motor = self.Teleport
    if not motor then
        self.LastError = "teleport motor ausente"
        return false
    end
    -- Voa ate a fruta. GoToInstance chega em cima dela; encostar e o que faz o
    -- jogo virar o Model spawnado em Tool coletavel.
    pcall(function() motor:GoToInstance(part) end)
    -- Fruta dropada ja tem prompt: dispara (caminho mais rapido). Fruta
    -- spawnada nao tem -- e o encosto do voo que resolve.
    self:_fireFruitPrompt(fruit)
    return true
end

function Feature:SetGrab(on)
    self.GrabEnabled = on == true
    if not self.GrabEnabled then self:_cancel("grab"); return true end
    self:_spawn("grab", function()
        while self.GrabEnabled do
            local done = pcall(function() return self:CollectNearestOnce() end)
            if not done then self.LastError = "grab step falhou" end
            task.wait(0.5)
        end
    end)
    return true
end

-- --- Store ----------------------------------------------------------------
-- Guarda as frutas que voce ja tem (Tools carregados ou na mochila) via o
-- remote StoreFruit, respeitando a lista de "nunca guardar".

function Feature:StoreHeld()
    local comm = self:_commF()
    if not comm then return false end
    local pools = {}
    if LocalPlayer.Character then pools[#pools + 1] = LocalPlayer.Character end
    local backpack = LocalPlayer:FindFirstChild("Backpack")
    if backpack then pools[#pools + 1] = backpack end
    for _, pool in ipairs(pools) do
        for _, tool in ipairs(pool:GetChildren()) do
            if tool:IsA("Tool") then
                local original = tool:GetAttribute("OriginalName")
                -- Fruta tem "-" no OriginalName ("Dragon-Dragon Fruit"); nao
                -- confundir com espada nem com item qualquer.
                if original and tostring(original):find("-") and not nameInSet(self.Keep, tool) then
                    pcall(function() comm:InvokeServer("StoreFruit", original, tool) end)
                end
            end
        end
    end
    return true
end

function Feature:SetStore(on)
    self.StoreEnabled = on == true
    if not self.StoreEnabled then self:_cancel("store"); return true end
    self:_spawn("store", function()
        while self.StoreEnabled do
            pcall(function() self:StoreHeld() end)
            task.wait(self.StoreInterval)
        end
    end)
    return true
end

-- --- Knobs ----------------------------------------------------------------
function Feature:SetRange(value)
    value = tonumber(value)
    if not value or value < 0 then return false end
    self.Range = value
    return true
end

function Feature:SetEspRange(value)
    value = tonumber(value)
    if not value or value < 0 then return false end
    self.EspRange = value
    return true
end

-- "dragon rocket" -> {dragon=true, rocket=true}
function Feature:ParseList(text)
    local set = {}
    for token in tostring(text or ""):gmatch("[^,%s]+") do
        local name = token:lower()
        if name ~= "" then set[name] = true end
    end
    return set
end

function Feature:SetSkip(text)
    if type(text) == "string" then self.Skip = self:ParseList(text) else self.Skip = text or {} end
    return true
end

function Feature:SetKeep(text)
    if type(text) == "string" then self.Keep = self:ParseList(text) else self.Keep = text or {} end
    return true
end

-- --- Ciclo de vida --------------------------------------------------------
-- A feature so faz alguma coisa com pelo menos um dos tres ligado. Enable()
-- fica ligada enquanto qualquer um estiver; Disable() derruba todos.

function Feature:Enable()
    if self.Enabled then return true end
    self.Enabled = true
    return true
end

function Feature:Disable()
    self.Enabled = false
    self.GrabEnabled = false
    self.StoreEnabled = false
    self:SetEsp(false)
    self:_cancel("grab")
    self:_cancel("store")
    return true
end

function Feature:IsEnabled()
    return self.Enabled == true
end

function Feature:Destroy()
    self:Disable()
    self.Teleport = nil
    self.EspMap = {}
end

return Feature

]],
    ["src/games/features/bloxfruits/islands.lua"] = [[
local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring

local Players = game:GetService("Players")
local workspace = game:GetService("Workspace")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer

-- Island Teleport -- pular direto pra uma ilha pelo nome.
--
-- O usuario liga o toggle, escolhe a ilha no dropdown, e o personagem voa ate
-- ela. Teleporte "de botao": nao tem alvo movel nem loop de farm -- e so um voo
-- pontual por escolha.
--
-- NAO tem motor proprio: usa o teleporte geral (options.teleport, a infra) por
-- injecao, igual a fruta faz. Um motor de voo no script, nao dois.
--
-- O destino e a INSTANCIA real no mapa (workspace.Map.<Nome>), nao uma
-- coordenada chumbada: isso nao quebra quando o mapa muda e usa exatamente os
-- nomes que o usuario confirmou. Se a instancia nao existir (mar errado, ilha
-- fora do mapa), ele AVISA em vez de voar pro vazio.
--
-- Gate de verdade: selecionar no dropdown NAO teleporta. So vai se o toggle
-- estiver ligado. Trocar a ilha com o toggle ligado voa de novo; com ele
-- desligado, so memoriza a escolha.
--
-- Ao CHEGAR, o toggle se desliga sozinho -- foi o pedido do usuario: o voo e
-- pontual, nao faz sentido deixar armado depois que chegou. So a ilha daquele
-- voo desliga (a feature tem um unico toggle; nao ha "outras" para mexer). O
-- desligamento so dispara com o personagem perto do DESTINO daquele voo, entao
-- nao dispara cedo nem re-dispara com um passinho depois de chegar (a vigia
-- para no primeiro "chegou").
--
-- Self-contained: faz os proprios game:GetService e nao depende do DepHub. So
-- pede o motor de teleporte, e mesmo assim de forma opcional (sem ele, o toggle
-- recusa em vez de fingir que voa).

local Feature = {}
Feature.__index = Feature

-- A pasta das ilhas: workspace.Map. De la saem as instancias por nome.
local MAP_CONTAINER = "Map"

-- A que distancia do destino o voo conta como CHEGOU. O teleporte chega a 5
-- studs acima do alvo (ArrivalOffset), entao o limite tem que ser maior que
-- isso, mas pequeno o bastante para nao disparar no meio do caminho. 25 studs e
-- "do lado da ilha" sem confundir com passar por cima dela.
local ARRIVAL_DISTANCE = 25

-- As ilhas do Sea 2 (o usuario confirmou: todas as ilhas dele sao do Sea 2).
-- A chave e o rotulo que aparece no dropdown; o valor e o NOME DA INSTANCIA em
-- workspace.Map. Alguns rotulos bonitos nao batem com o nome do mapa (ex.:
-- Ghost Ship -> GhostShip), por isso a tabela explicita em vez de deduzir.
local SEA2_ISLANDS = {
    { label = "Snow Mountain",       instance = "SnowMountain" },
    { label = "Indra Island",        instance = "IndraIsland" },
    { label = "Ice Castle",          instance = "IceCastle" },
    { label = "Green Bit",           instance = "GreenBit" },
    { label = "Grave Island",        instance = "GraveIsland" },
    { label = "Ghost Ship Interior", instance = "GhostShipInterior" },
    { label = "Ghost Ship",          instance = "GhostShip" },
    { label = "Forgotten Island",    instance = "ForgottenIsland" },
    { label = "Fishmen",             instance = "Fishmen" },
    { label = "Dressrosa",           instance = "Dressrosa" },
    { label = "Darkbeard Arena",     instance = "DarkbeardArena" },
    { label = "Dapper Jack Arena",   instance = "DapperJackArena" },
}

-- A lista publica de rotulos, na ordem. O backend monta o dropdown daqui.
Feature.islands = {}
for _, entry in ipairs(SEA2_ISLANDS) do
    Feature.islands[#Feature.islands + 1] = entry.label
end

-- Acha a instancia da ilha em workspace.Map.<instancia>. Devolve a instancia ou
-- nil (se a pasta nao existir ou a ilha nao estiver no mapa).
function Feature:IslandInstance(instanceName)
    local map = workspace:FindFirstChild(MAP_CONTAINER)
    if not map then return nil end
    return map:FindFirstChild(instanceName)
end

-- A posicao do HumanoidRootPart agora, ou nil se nao ha character.
function Feature:RootPosition()
    local character = LocalPlayer and LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    return root and root.Position or nil
end

-- A posicao-mundo da instancia (Part -> Position; Model -> GetPivot). Espelha o
-- que o motor de teleporte usa como destino, para a vigia de chegada medir a
-- MESMA coisa que o voo persegue.
function Feature:InstancePosition(instance)
    if not instance then return nil end
    if instance:IsA("BasePart") then return instance.Position end
    if instance:IsA("Model") then
        local pivot = instance:GetPivot()
        return pivot and pivot.Position or nil
    end
    return nil
end

-- Vigia o voo ate o personagem ficar a <= ARRIVAL_DISTANCE do destino. No
-- primeiro frame que "chegou", para a vigia e chama o hook de chegada com o
-- rotulo da ilha. Nao dispara cedo (so e armada depois do Go), nem re-dispara
-- (a conexao e desligada assim que chegou).
function Feature:_WatchArrival(label, targetPosition)
    self:_StopWatching()
    if not targetPosition then return end
    if not (RunService and type(RunService.Heartbeat) == "table"
        and type(RunService.Heartbeat.Connect) == "function") then
        return
    end
    self._arrivalLabel = label
    self._arrivalTarget = targetPosition
    self._arrivalConnection = RunService.Heartbeat:Connect(function()
        local position = self:RootPosition()
        if not position then return end
        local distance = (position - self._arrivalTarget).Magnitude
        if distance <= ARRIVAL_DISTANCE then
            local arrived = self._arrivalLabel
            self:_StopWatching()
            self.LastStatus = ("arrived at %s"):format(tostring(arrived))
            -- A feature tem UM toggle (o da aba Travel). "Desligar so a ilha
            -- deste voo" = desligar esse toggle -- nao ha outro para tocar.
            if type(self.OnArrive) == "function" then
                pcall(self.OnArrive, self, arrived)
            end
        end
    end)
end

function Feature:_StopWatching()
    if self._arrivalConnection then
        pcall(function() self._arrivalConnection:Disconnect() end)
        self._arrivalConnection = nil
    end
    self._arrivalLabel = nil
    self._arrivalTarget = nil
end

function Feature.new(options)
    options = options or {}
    local self = setmetatable({}, Feature)
    self.Enabled = false
    -- A ilha escolhida no dropdown, pelo rotulo ("Snow Mountain"). Comeca na
    -- primeira da lista para o dropdown ter um valor inicial valido.
    self.Selected = options.selected or SEA2_ISLANDS[1].label
    -- So teleporta com o toggle ligado. Trocar a ilha com o toggle ligado voa de
    -- novo; desligado, so guarda.
    self.ToggleOn = false
    -- O motor de teleporte geral (infra). Sem ele o toggle recusa.
    self.Teleport = options.teleport or nil
    self.LastStatus = "idle"
    self.LastError = nil
    -- Hook de chegada: o backend liga isto ao toggle para que o toggle se
    -- desligue sozinho quando o personagem chega na ilha.
    self.OnArrive = options.onArrive or nil
    -- Estado da vigia de chegada (conexao Heartbeat + alvo do voo corrente).
    self._arrivalConnection = nil
    self._arrivalLabel = nil
    self._arrivalTarget = nil
    return self
end

function Feature:SetTeleport(motor)
    self.Teleport = motor
    return self.Teleport ~= nil
end

-- O rotulo -> o nome da instancia. Devolve nil se o rotulo nao for de ilha
-- conhecida.
function Feature:InstanceNameFor(label)
    local wanted = tostring(label or ""):lower()
    for _, entry in ipairs(SEA2_ISLANDS) do
        if entry.label:lower() == wanted then return entry.instance end
    end
    return nil
end

-- O voo de verdade. So acontece com o toggle ligado; e chamado pelo go() e
-- toda vez que a selecao muda com o toggle ja ligado.
function Feature:Go()
    local motor = self.Teleport
    if not motor then
        self.LastStatus = "no teleport motor"
        self.LastError = "sem motor de teleporte"
        return false
    end
    local instanceName = self:InstanceNameFor(self.Selected)
    if not instanceName then
        self.LastStatus = ("unknown island: %s"):format(tostring(self.Selected))
        return false
    end
    local island = self:IslandInstance(instanceName)
    if not island then
        -- A ilha nao esta no mapa agora (mar errado, ilha removida). Avisa em
        -- vez de voar pro vazio -- o objetivo e o jogador entender o porque.
        self.LastStatus = ("not in map: workspace.Map.%s"):format(instanceName)
        return false
    end
    local ok = pcall(function() motor:GoToInstance(island) end)
    if not ok then
        self.LastStatus = "teleport failed"
        self.LastError = "falha no voo"
        return false
    end
    self.LastStatus = ("flying to %s"):format(self.Selected)
    -- So agora (depois do Go deu certo) a vigia de chegada e armada: assim ela
    -- nunca dispara antes do voo comecar. O alvo e a posicao da MESMA instancia
    -- que o motor vai perseguir.
    self:_WatchArrival(self.Selected, self:InstancePosition(island))
    return true
end

-- O usuario escolheu uma ilha. So teleporta se o toggle estiver ligado (o gate
-- que o usuario pediu); se estiver desligado, so memoriza a escolha.
function Feature:Select(label)
    local instanceName = self:InstanceNameFor(label)
    if not instanceName then return false end
    self.Selected = label
    if self.ToggleOn then return self:Go() end
    return true
end

-- O toggle. Ligar voa pra ilha ja selecionada; desligar so para de agir (nao
-- cancela um voo em andamento -- o voo e pontual e termina sozinho; cancelar no
-- meio deixaria o personagem no ar no caminho).
--
-- Devolve true se ARMOU (tem motor). Se a ilha escolhida nao estiver no mapa
-- agora, continua armado e reporta em LastStatus -- assim o usuario pode so
-- trocar a ilha no dropdown sem religar o toggle.
function Feature:SetEnabled(on)
    self.ToggleOn = on == true
    if not self.ToggleOn then
        self.LastStatus = "idle"
        -- Desligar na mao cancela a vigia: sem voo rastreado, nao ha chegada
        -- para detectar.
        self:_StopWatching()
        return true
    end
    if not self.Teleport then
        self.LastError = "sem motor de teleporte"
        self.ToggleOn = false
        return false
    end
    self:Go()
    return true
end

-- --- Ciclo de vida --------------------------------------------------------

function Feature:Enable()
    if self.Enabled then return true end
    self.Enabled = true
    return true
end

function Feature:Disable()
    self.Enabled = false
    self.ToggleOn = false
    self.LastStatus = "idle"
    self:_StopWatching()
    return true
end

function Feature:IsEnabled()
    return self.Enabled == true
end

function Feature:Destroy()
    self:Disable()
    self.Teleport = nil
    self.OnArrive = nil
end

return Feature

]],
    ["src/games/features/bloxfruits/teleport.lua"] = [[
local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring
local tonumber = tonumber
local math = math

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local LocalPlayer = Players.LocalPlayer

-- Teleport -- o MOTOR de teleporte do Blox Fruits, sem UI.
--
-- Este modulo e infraestrutura, nao uma feature de painel: ele nao tem toggle
-- proprio. Ele expoe o teleporte perfeito (o fly por CFrame do script antigo)
-- para QUE QUALQUER feature chame -- a de pegar fruta, a de farm, a de boss.
-- A ideia e: um so teleporte, testado, que todo mundo usa.
--
-- O coracao e Go(pos): um TweenService no HumanoidRootPart com a velocidade
-- calculada pela distancia (mapa do Sea 3 e enorme, entao a velocidade tem que
-- escalar). Durante o voo:
--   * a velocidade linear e zerada todo Heartbeat (senao o character "escorrega"
--     e o tween briga com a fisica), e
--   * o character fica noclip (CanCollide = false em toda BasePart).
--   * NUNCA se usa Anchor: o BF rejeita todo hit num character ancorado.
--
-- Self-contained de proposito, igual a blade hit: faz os proprios
-- game:GetService e nao depende do DepHub nem do adapter. Publica
-- new()/Enable()/Disable() + os metodos de teleporte.

local Teleport = {}
Teleport.__index = Teleport

-- Converte o getter de posicao em Vector3. Os dados de ilha/boss usam
-- Vector3.new; os de fruta podem vir como {X=,Y=,Z=} (o .Position de uma Part),
-- entao os dois entram.
local function toVector3(value)
    if typeof(value) == "Vector3" then return value end
    if type(value) == "table" then
        return Vector3.new(tonumber(value.X) or 0, tonumber(value.Y) or 0, tonumber(value.Z) or 0)
    end
    return nil
end

function Teleport.new(options)
    options = options or {}
    local self = setmetatable({}, Teleport)
    self.Enabled = false
    self.Thread = nil
    -- Velocidade em studs/s. 200 aguenta o mapa gigante do Sea 3; mais baixo se
    -- o anti-cheat der loopback/kick. E o unico knob que importa de verdade.
    self.Speed = options.speed or 200
    -- Altura somada ao destino: cair de 5 studs acima evita spawnar dentro do
    -- chao e ficar preso.
    self.ArrivalOffset = options.arrivalOffset or Vector3.new(0, 5, 0)
    self.Tween = nil
    self._heartbeat = nil
    return self
end

function Teleport:HumanoidRootPart()
    local character = LocalPlayer and LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

function Teleport:IsFlying()
    return self.Tween ~= nil
end

-- Cancela o voo corrente, se houver. Chamado antes de todo Go novo (um so
-- tween por vez) e no Disable/Destroy.
function Teleport:Cancel()
    if self.Tween then
        pcall(function() self.Tween:Cancel() end)
        self.Tween = nil
    end
    return true
end

-- O motor. Leva o character ate `position` por CFrame, ancorando o voo no
-- Heartbeat (velocidade zero + noclip). Devolve o tween, ou nil se nao ha
-- character.
function Teleport:Go(position, offset)
    local target = toVector3(position)
    if not target then return nil end
    if offset then
        local off = toVector3(offset)
        if off then target = target + off end
    end

    local root = self:HumanoidRootPart()
    if not root then return nil end

    local distance = (root.Position - target).Magnitude
    -- Escala o tempo pela distancia, com piso de 0.05 (teleporte no lugar) e
    -- teto de 90s (um mapa cross-sea nao trava pra sempre).
    local duration = math.clamp(distance / math.max(self.Speed, 1), 0.05, 90)

    self:Cancel()
    local tween = TweenService:Create(
        root,
        TweenInfo.new(duration, Enum.EasingStyle.Linear),
        { CFrame = CFrame.new(target) }
    )
    self.Tween = tween
    tween.Completed:Connect(function()
        if self.Tween == tween then self.Tween = nil end
    end)
    tween:Play()
    return tween
end

-- Atalho: vai ate o offset padrao (5 studs acima). O Go puro deixa passar o
-- offset, mas quase todo call site quer so "chega la em cima".
function Teleport:GoTo(position)
    return self:Go(position, self.ArrivalOffset)
end

function Teleport:SetSpeed(value)
    value = tonumber(value)
    if not value or value <= 0 then return false end
    self.Speed = value
    return true
end

-- --- Teleporte por nome (ilhas/bosses) -------------------------------
-- As tabelas de posicao ficam no modulo porque varias features precisam delas
-- (pegar fruta procura nas ilhas, farm vai aos bosses). Quem so quer um destino
-- especifico pode passar a posicao direto pro Go.

Teleport.islands = {
