    ["src/games/features/mm2/roletracker.lua"] = [[
local game=game
local task=task
local type=type
local pairs=pairs
local ipairs=ipairs

local Factory={}

local function disconnectAll(list)
    if not list then return end
    for i=#list,1,-1 do
        local c=list[i]
        list[i]=nil
        if c then pcall(c.Disconnect,c) end
    end
end

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local RunService=context.RunService or game:GetService("RunService")
    local Workspace=context.Workspace or game:GetService("Workspace")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer

    local self={
        Enabled=false,
        Destroyed=false,
        Connections={},
        PlayerConnections={},
        Listeners={},
        Murder=nil,
        Sheriff=nil,
        LastSheriff=nil,
        GunDrop=nil,
        Accumulator=0,
        Debug=context.Debug==true,
        DebugInfo={Murder="none",Sheriff="none",LastSheriff="none",GunDrop="missing",Scans=0,LastChange="none"}
    }

    function self:_emit(role,newPlayer,oldPlayer)
        self.DebugInfo.LastChange=role..":"..(newPlayer and newPlayer.Name or "none")
        for callback in pairs(self.Listeners) do
            task.spawn(function()
                pcall(callback,role,newPlayer,oldPlayer)
            end)
        end
    end

    function self:OnChanged(callback)
        if type(callback)~="function" then return nil end
        self.Listeners[callback]=true
        local connection={Connected=true}
        function connection:Disconnect()
            if not self.Connected then return end
            self.Connected=false
            self._owner.Listeners[self._callback]=nil
        end
        connection._owner=self
        connection._callback=callback
        return connection
    end

    function self:_hasTool(player,name)
        if not player then return false end
        local character=player.Character
        local backpack=player:FindFirstChildOfClass("Backpack")
        if character and character:FindFirstChild(name,true) then return true end
        if backpack and backpack:FindFirstChild(name,true) then return true end
        return false
    end

    function self:_findGunDrop()
        if self.GunDrop and self.GunDrop.Parent then
            self.DebugInfo.GunDrop=self.GunDrop:GetFullName()
            return self.GunDrop
        end
        self.GunDrop=nil
        for _,object in ipairs(Workspace:GetDescendants()) do
            if object.Name=="GunDrop" then
                self.GunDrop=object
                break
            end
        end
        self.DebugInfo.GunDrop=self.GunDrop and self.GunDrop:GetFullName() or "missing"
        return self.GunDrop
    end

    function self:_setMurder(player)
        if self.Murder==player then return end
        local old=self.Murder
        self.Murder=player
        self.DebugInfo.Murder=player and player.Name or "none"
        self:_emit("Murder",player,old)
    end

    function self:_setSheriff(player)
        if self.Sheriff==player then return end
        local old=self.Sheriff
        if player then
            self.LastSheriff=self.Sheriff or self.LastSheriff
            self.Sheriff=player
        else
            self.LastSheriff=self.Sheriff or self.LastSheriff
            self.Sheriff=nil
        end
        self.DebugInfo.Sheriff=self.Sheriff and self.Sheriff.Name or "none"
        self.DebugInfo.LastSheriff=self.LastSheriff and self.LastSheriff.Name or "none"
        self:_emit("Sheriff",self.Sheriff,old)
    end

    function self:Scan()
        if self.Destroyed then return end
        self.DebugInfo.Scans=self.DebugInfo.Scans+1
        local murder=nil
        local sheriff=nil

        for _,player in ipairs(Players:GetPlayers()) do
            if self:_hasTool(player,"Knife") then murder=player end
            if self:_hasTool(player,"Gun") then sheriff=player end
        end

        if murder then
            self:_setMurder(murder)
        elseif self.Murder and (not self.Murder.Parent or not self.Murder.Character) then
            self:_setMurder(nil)
        end

        if sheriff then
            if sheriff~=self.Sheriff then self:_setSheriff(sheriff) end
        elseif self.Sheriff and not self.Sheriff.Parent then
            self:_setSheriff(nil)
        end

        self:_findGunDrop()
    end

    function self:GetRole(player)
        if not player then return "Unknown" end
        if player==self.Murder then return "Murder" end
        if player==self.Sheriff then return "Sheriff" end
        return "Innocent"
    end

    function self:GetMurder() return self.Murder end
    function self:GetSheriff() return self.Sheriff end
    function self:GetLastSheriff() return self.LastSheriff end
    function self:GetGunDrop() return self:_findGunDrop() end
    function self:HasTool(player,name) return self:_hasTool(player,name) end

    function self:ResetRound()
        self.GunDrop=nil
        self:_setMurder(nil)
        self:_setSheriff(nil)
        self.LastSheriff=nil
        self.DebugInfo.LastSheriff="none"
        self.DebugInfo.GunDrop="missing"
    end

    function self:_watchPlayer(player)
        if self.PlayerConnections[player] then return end
        local binding={Connections={},CharacterConnections={},BackpackConnections={}}
        self.PlayerConnections[player]=binding
        local pending=false
        local function rescan()
            if pending then return end
            pending=true
            task.defer(function()
                pending=false
                if self.Enabled and not self.Destroyed and self.PlayerConnections[player]==binding then self:Scan() end
            end)
        end
        local function bindCharacter(character)
            disconnectAll(binding.CharacterConnections)
            if character then
                local list=binding.CharacterConnections
                list[#list+1]=character.ChildAdded:Connect(rescan)
                list[#list+1]=character.ChildRemoved:Connect(rescan)
            end
            rescan()
        end
        local function bindBackpack(backpack)
            disconnectAll(binding.BackpackConnections)
            binding.Backpack=backpack
            if backpack then
                local list=binding.BackpackConnections
                list[#list+1]=backpack.ChildAdded:Connect(rescan)
                list[#list+1]=backpack.ChildRemoved:Connect(rescan)
            end
            rescan()
        end
        local list=binding.Connections
        list[#list+1]=player.CharacterAdded:Connect(bindCharacter)
        list[#list+1]=player.CharacterRemoving:Connect(function() bindCharacter(nil) end)
        list[#list+1]=player.ChildAdded:Connect(function(child) if child:IsA("Backpack") then bindBackpack(child) end end)
        list[#list+1]=player.ChildRemoved:Connect(function(child) if child==binding.Backpack then bindBackpack(nil) end end)
        bindCharacter(player.Character)
        bindBackpack(player:FindFirstChildOfClass("Backpack"))
    end

    function self:_unwatchPlayer(player)
        local binding=self.PlayerConnections[player]
        self.PlayerConnections[player]=nil
        if binding then
            disconnectAll(binding.Connections)
            disconnectAll(binding.CharacterConnections)
            disconnectAll(binding.BackpackConnections)
        end
        if self.Murder==player then self:_setMurder(nil) end
        if self.Sheriff==player then self:_setSheriff(nil) end
        if self.LastSheriff==player then
            self.LastSheriff=nil
            self.DebugInfo.LastSheriff="none"
        end
    end

    function self:Enable()
        if self.Destroyed then return false end
        if self.Enabled then return true end
        self.Enabled=true
        for _,player in ipairs(Players:GetPlayers()) do self:_watchPlayer(player) end
        self.Connections[#self.Connections+1]=Players.PlayerAdded:Connect(function(player)
            self:_watchPlayer(player)
            self:Scan()
        end)
        self.Connections[#self.Connections+1]=Players.PlayerRemoving:Connect(function(player)
            self:_unwatchPlayer(player)
        end)
        self.Connections[#self.Connections+1]=Workspace.DescendantAdded:Connect(function(object)
            if object.Name=="GunDrop" then
                self.GunDrop=object
                self.DebugInfo.GunDrop=object:GetFullName()
            end
        end)
        self.Connections[#self.Connections+1]=Workspace.DescendantRemoving:Connect(function(object)
            if object==self.GunDrop then
                self.GunDrop=nil
                self.DebugInfo.GunDrop="missing"
            end
        end)
        self.Connections[#self.Connections+1]=RunService.Heartbeat:Connect(function(dt)
            self.Accumulator=self.Accumulator+dt
            if self.Accumulator>=0.45 then
                self.Accumulator=0
                self:Scan()
            end
        end)
        self:Scan()
        return true
    end

    function self:GetDebugInfo()
        local out={}
        for k,v in pairs(self.DebugInfo) do out[k]=v end
        return out
    end

    function self:Disable()
        if not self.Enabled then return true end
        self.Enabled=false
        disconnectAll(self.Connections)
        for player in pairs(self.PlayerConnections) do self:_unwatchPlayer(player) end
        return true
    end

    function self:Destroy()
        if self.Destroyed then return end
        self:Disable()
        self.Destroyed=true
        self.Listeners={}
    end

    return self
end

return Factory


]],
    ["src/games/features/mm2/roundtracker.lua"] = [[
local game=game
local type=type
local pairs=pairs
local ipairs=ipairs

local Factory={}

local function disconnectAll(list)
    for i=#list,1,-1 do
        local c=list[i]
        list[i]=nil
        if c then pcall(c.Disconnect,c) end
    end
end

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local RunService=context.RunService or game:GetService("RunService")
    local Workspace=context.Workspace or game:GetService("Workspace")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer

    local self={
        Enabled=false,
        Destroyed=false,
        Connections={},
        Listeners={},
        RoundActive=false,
        Accumulator=0,
        LobbyStable=0,
        OutsideStable=0,
        CachedLobby=nil,
        CachedCFrame=nil,
        CachedSize=nil,
        DebugInfo={Lobby="missing",PlayersChecked=0,PlayersInLobby=0,AliveRoundPlayers=0,RoundActive=false,LastChange="none"}
    }

    function self:OnChanged(callback)
        if type(callback)~="function" then return nil end
        self.Listeners[callback]=true
        local connection={Connected=true,_owner=self,_callback=callback}
        function connection:Disconnect()
            if not self.Connected then return end
            self.Connected=false
            self._owner.Listeners[self._callback]=nil
        end
        return connection
    end

    function self:_emit(active)
        for callback in pairs(self.Listeners) do
            task.spawn(function() pcall(callback,active) end)
        end
    end

    function self:_setRoundActive(active,reason)
        active=active==true
        if self.RoundActive==active then return end
        self.RoundActive=active
        self.DebugInfo.RoundActive=active
        self.DebugInfo.LastChange=reason or (active and "started" or "ended")
        self:_emit(active)
    end

    function self:_computeLobbyBounds()
        local lobby=Workspace:FindFirstChild("RegularLobby")
        if not lobby then
            self.CachedLobby=nil
            self.CachedCFrame=nil
            self.CachedSize=nil
            self.DebugInfo.Lobby="missing"
            return nil,nil
        end

        self.DebugInfo.Lobby=lobby:GetFullName()
        local cf,size
        if lobby:IsA("BasePart") then
            cf,size=lobby.CFrame,lobby.Size
        elseif lobby:IsA("Model") then
            local ok,a,b=pcall(lobby.GetBoundingBox,lobby)
            if ok then cf,size=a,b end
        end

        if not cf then
            local parts={}
            for _,object in ipairs(lobby:GetDescendants()) do
                if object:IsA("BasePart") then parts[#parts+1]=object end
            end
            if #parts==0 then return nil,nil end
            local minX,minY,minZ=math.huge,math.huge,math.huge
            local maxX,maxY,maxZ=-math.huge,-math.huge,-math.huge
            for _,part in ipairs(parts) do
                local p=part.Position
                local s=part.Size*0.5
                minX=math.min(minX,p.X-s.X); minY=math.min(minY,p.Y-s.Y); minZ=math.min(minZ,p.Z-s.Z)
                maxX=math.max(maxX,p.X+s.X); maxY=math.max(maxY,p.Y+s.Y); maxZ=math.max(maxZ,p.Z+s.Z)
            end
            cf=CFrame.new((minX+maxX)/2,(minY+maxY)/2,(minZ+maxZ)/2)
            size=Vector3.new(maxX-minX,maxY-minY,maxZ-minZ)
        end

        self.CachedLobby=lobby
        self.CachedCFrame=cf
        self.CachedSize=size
        return cf,size
    end

    function self:_getLobbyBounds()
        if self.CachedLobby and self.CachedLobby.Parent and self.CachedCFrame and self.CachedSize then
            return self.CachedCFrame,self.CachedSize
        end
        return self:_computeLobbyBounds()
    end

    function self:_inside(cf,size,position)
        local localPos=cf:PointToObjectSpace(position)
        local half=size*0.5
        return math.abs(localPos.X)<=half.X+8
            and math.abs(localPos.Y)<=half.Y+12
            and math.abs(localPos.Z)<=half.Z+8
    end

    function self:IsPlayerInLobby(player)
        if not player then return false end
        local character=player.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not root then return false end
        local cf,size=self:_getLobbyBounds()
        if not cf then return false end
        return self:_inside(cf,size,root.Position)
    end

    function self:IsPlayerAliveInRound(player)
        if not player or player==LocalPlayer then return false end
        local character=player.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health<=0 or not root then return false end
        return not self:IsPlayerInLobby(player)
    end

    function self:GetAliveRoundPlayers()
        local result={}
        for _,player in ipairs(Players:GetPlayers()) do
            if self:IsPlayerAliveInRound(player) then result[#result+1]=player end
        end
        table.sort(result,function(a,b) return string.lower(a.Name)<string.lower(b.Name) end)
        self.DebugInfo.AliveRoundPlayers=#result
        return result
    end

    function self:_sample(dt)
        local cf,size=self:_computeLobbyBounds()
        if not cf then return end

        local checked=0
        local inside=0
        local aliveRound=0
        for _,player in ipairs(Players:GetPlayers()) do
            local character=player.Character
            local root=character and character:FindFirstChild("HumanoidRootPart")
            local humanoid=character and character:FindFirstChildOfClass("Humanoid")
            if root and humanoid and humanoid.Health>0 then
                checked=checked+1
                if self:_inside(cf,size,root.Position) then
                    inside=inside+1
                elseif player~=LocalPlayer then
                    aliveRound=aliveRound+1
                end
            end
        end

        self.DebugInfo.PlayersChecked=checked
        self.DebugInfo.PlayersInLobby=inside
        self.DebugInfo.AliveRoundPlayers=aliveRound
        local allInLobby=checked>0 and inside==checked

        if allInLobby then
            self.LobbyStable=self.LobbyStable+dt
            self.OutsideStable=0
            if self.LobbyStable>=1.15 then self:_setRoundActive(false,"all players in lobby") end
        else
            self.OutsideStable=self.OutsideStable+dt
            self.LobbyStable=0
            if checked>0 and self.OutsideStable>=0.65 then self:_setRoundActive(true,"players left lobby") end
        end
    end

    function self:IsRoundActive() return self.RoundActive end

    function self:GetDebugInfo()
        local out={}
        for k,v in pairs(self.DebugInfo) do out[k]=v end
        return out
    end

    function self:Enable()
        if self.Destroyed then return false end
        if self.Enabled then return true end
        self.Enabled=true
        self.Connections[#self.Connections+1]=Workspace.ChildAdded:Connect(function(child)
            if child.Name=="RegularLobby" then self.CachedLobby=nil end
        end)
        self.Connections[#self.Connections+1]=Workspace.ChildRemoved:Connect(function(child)
            if child==self.CachedLobby then self.CachedLobby=nil self.CachedCFrame=nil self.CachedSize=nil end
        end)
        self.Connections[#self.Connections+1]=RunService.Heartbeat:Connect(function(dt)
            self.Accumulator=self.Accumulator+dt
            if self.Accumulator>=0.2 then
                local elapsed=self.Accumulator
                self.Accumulator=0
                self:_sample(elapsed)
            end
        end)
        return true
    end

    function self:Disable()
        if not self.Enabled then return true end
        self.Enabled=false
        disconnectAll(self.Connections)
        self.LobbyStable=0
        self.OutsideStable=0
        return true
    end

    function self:Destroy()
        if self.Destroyed then return end
        self:Disable()
        self.Destroyed=true
        self.Listeners={}
        self.CachedLobby=nil
    end

    return self
end

return Factory

]],
    ["src/games/features/noobpiece/autoattack.lua"] = [[
local Players=game:GetService("Players")
local ReplicatedStorage=game:GetService("ReplicatedStorage")

local AutoAttack={}
AutoAttack.__index=AutoAttack

function AutoAttack.new()
    local events=ReplicatedStorage:FindFirstChild("Events") or ReplicatedStorage:WaitForChild("Events",8)
    local remote=events and (events:FindFirstChild("PlayerAttack") or events:WaitForChild("PlayerAttack",8))
    assert(remote and remote:IsA("RemoteEvent"),"Noob Piece: Events/PlayerAttack unavailable")
    return setmetatable({
        Player=Players.LocalPlayer,
        Remote=remote,
        Enabled=false,
        FarmEnabled=false,
        FarmReady=false,
        Interval=0.05,
        ActivateInterval=0.1,
        Token=0
    },AutoAttack)
end

function AutoAttack:_character()
    local character=self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")

    if not character or not humanoid or humanoid.Health<=0 then
        return nil
    end

    return character
end

function AutoAttack:_argument(tool)
    if tool and tool:GetAttribute("StatCategory")=="Fists" then
        return "0"
    end
    return ""
end

function AutoAttack:_run(token)
    local lastActivate=0

    while (self.Enabled or self.FarmEnabled) and token==self.Token do
        if self.Enabled or self.FarmReady then
            local character=self:_character()
            local tool=character and character:FindFirstChildOfClass("Tool")

            if tool then
                local now=os.clock()

                if now-lastActivate>=self.ActivateInterval then
                    lastActivate=now
                    pcall(tool.Activate,tool)
                end

                pcall(self.Remote.FireServer,self.Remote,self:_argument(tool))
            end
        end

        task.wait(self.Interval)
    end
end

function AutoAttack:_refresh()
    self.Token+=1

    if self.Enabled or self.FarmEnabled then
        local token=self.Token
        task.spawn(function()
            self:_run(token)
        end)
    end
end

function AutoAttack:SetEnabled(enabled)
    enabled=enabled==true
    if self.Enabled==enabled then return end

    self.Enabled=enabled
    self:_refresh()
end

function AutoAttack:SetFarmEnabled(enabled)
    enabled=enabled==true
    if self.FarmEnabled==enabled then return end

    self.FarmEnabled=enabled

    if not enabled then
        self.FarmReady=false
    end

    self:_refresh()
end

function AutoAttack:SetFarmReady(ready)
    self.FarmReady=self.FarmEnabled and ready==true
end

function AutoAttack:Destroy()
    self.Enabled=false
    self.FarmEnabled=false
    self.FarmReady=false
    self:_refresh()
end

return AutoAttack


]],
    ["src/games/features/noobpiece/autochest.lua"] = [[
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")

-- Humanised timing: vary each periodic wait to avoid a perfectly periodic loop.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local AutoChest={}
AutoChest.__index=AutoChest

local MOVEMENT_OWNER="AutoChest"

function AutoChest.new(movement)
    return setmetatable({
        Player=Players.LocalPlayer,
        Movement=movement,
        Enabled=false,
        Token=0,
        Delay=0.35,
        Height=2.5,
        LastTarget=nil
    },AutoChest)
end

function AutoChest:_character()
    local character=self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")
    if not character or not humanoid or humanoid.Health<=0 or not root then return nil end
    return character,root
end

function AutoChest:_parts(model)
    return model:FindFirstChild("Part1",true),model:FindFirstChild("Part2",true)
end

function AutoChest:_targetPart(model)
    local part1,part2=self:_parts(model)
    if part1 and part1:IsA("BasePart") and part1.Transparency<0.99 then return part1 end
    if part2 and part2:IsA("BasePart") and part2.Transparency<0.99 then return part2 end
    return nil
end

function AutoChest:_spawned(model)
    return self:_targetPart(model)~=nil
end

function AutoChest:_nearest(root)
    local folder=Workspace:FindFirstChild("Bau")
    if not folder then return nil,nil end

    local bestModel,bestPart,bestDistance

    for _,model in ipairs(folder:GetChildren()) do
        if model:IsA("Model") and model.Name=="Bau" then
            local part=self:_targetPart(model)

            if part then
                local distance=(root.Position-part.Position).Magnitude

                if not bestDistance or distance<bestDistance then
                    bestModel,bestPart,bestDistance=model,part,distance
                end
            end
        end
    end

    return bestModel,bestPart
end

function AutoChest:_targetCFrame(part)
    local position=part.Position+Vector3.new(0,self.Height,0)
    local look=part.CFrame.LookVector
    local flatLook=Vector3.new(look.X,0,look.Z)

    if flatLook.Magnitude<0.01 then
        flatLook=Vector3.new(0,0,-1)
    end

    return CFrame.lookAt(position,position+flatLook.Unit)
end

function AutoChest:_move(part)
    if not self.Movement then
        return false
    end

    return self.Movement:FlyTo(self:_targetCFrame(part),nil,MOVEMENT_OWNER)
end

function AutoChest:_touch(root,part)
    if type(firetouchinterest)~="function" then return end

    pcall(firetouchinterest,root,part,0)
    task.wait(0.04)
    pcall(firetouchinterest,root,part,1)
end

function AutoChest:_run(token)
    while self.Enabled and token==self.Token do
        local _,root=self:_character()

        if not root then
            jitter(0.4)
            continue
        end

        local model,part=self:_nearest(root)

        if not model or not part then
            self.LastTarget=nil
            jitter(0.25)
            continue
        end

        self.LastTarget=model

        local moved=self:_move(part)
        if not self.Enabled or token~=self.Token then
            break
        end

        if moved then
            local _,newRoot=self:_character()

            if newRoot and part.Parent and self:_spawned(model) then
                self:_touch(newRoot,part)
            end
        end

        local started=os.clock()

        while self.Enabled and token==self.Token and model.Parent and self:_spawned(model) and os.clock()-started<1.25 do
            jitter(0.08)
        end

        jitter(self.Delay)
    end
end

function AutoChest:SetDelay(value)
    self.Delay=math.clamp(tonumber(value) or 0.35,0.1,2)
end

function AutoChest:SetEnabled(enabled)
    enabled=enabled==true
    if self.Enabled==enabled then return end

    self.Enabled=enabled
    self.Token+=1

    if enabled then
        local token=self.Token
        task.spawn(function()
            self:_run(token)
        end)
    else
        self.LastTarget=nil

        if self.Movement then
            self.Movement:CancelOwner(MOVEMENT_OWNER,true)
        end
    end
end

function AutoChest:Destroy()
    self:SetEnabled(false)
end

return AutoChest

]],
    ["src/games/features/noobpiece/autofarm.lua"] = [[
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")

-- Humanised timing: a perfectly periodic loop is a bot fingerprint. jitter keeps
-- the same average cadence while varying each wait by +/-15%.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local AutoFarm={}
AutoFarm.__index=AutoFarm

local MOVEMENT_OWNER="AutoFarm"

function AutoFarm.new(movement,autoAttack,islandData)
    return setmetatable({
        Player=Players.LocalPlayer,
        Movement=movement,
        AutoAttack=autoAttack,
        IslandData=islandData,
        Enabled=false,
        Paused=false,
        Token=0,
        Target=nil,
        RangeMargin=1,
        Tolerance=0.75,
        FallbackRange=8,
        WeaponCategory="Fists",
        SelectedEnemy="Noob",
        SelectedIsland="HomeIsland",
        EnemyCatalog={},
        OptionLookup={}
    },AutoFarm)
end

function AutoFarm:_character()
    local character=self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")

    if not character or not humanoid or humanoid.Health<=0 or not root then
        return nil
    end

    return root
end

function AutoFarm:_weapon()
    local character=self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")

    if not character or not humanoid then
        return nil
    end

    local equipped=character:FindFirstChildOfClass("Tool")

    if equipped and equipped:GetAttribute("StatCategory")==self.WeaponCategory then
        return equipped
    end

    local backpack=self.Player:FindFirstChildOfClass("Backpack")

    if not backpack then
        return nil
    end

    for _,tool in ipairs(backpack:GetChildren()) do
        if tool:IsA("Tool") and tool:GetAttribute("StatCategory")==self.WeaponCategory then
            pcall(humanoid.EquipTool,humanoid,tool)
            return tool
        end
    end

    return nil
end

function AutoFarm:_range()
    local tool=self:_weapon()
    local range=tool and tool:GetAttribute("Range")

    if typeof(range)=="number" and range>0 then
        return range
    end

    return self.FallbackRange
end

function AutoFarm:SetWeaponCategory(category)
    if category~="Fists" and category~="Sword" then
        return false
    end

    self.WeaponCategory=category
    return true
end

function AutoFarm:GetWeaponCategory()
    return self.WeaponCategory
end

function AutoFarm:_folder()
    local quests=Workspace:FindFirstChild("Quests")
    return quests and quests:FindFirstChild("Enemies")
end

function AutoFarm:_npcId(model)
    local id=model:GetAttribute("NpcId")

    if type(id)=="string" and id~="" then
        return id
    end

    return model.Name
end

function AutoFarm:_modelIsland(model)
    local folder=self:_folder()

    if not folder or not model then
        return nil
    end

    local current=model

    while current and current.Parent~=folder do
        current=current.Parent
    end

    if current and current.Parent==folder then
        return current.Name
    end

    return nil
end

function AutoFarm:_catalogKey(island,id)
    return tostring(island or "Unknown").."::"..tostring(id)
end

function AutoFarm:_buildCatalog()
    local catalog={}
    local byKey={}

    local function add(meta)
        if type(meta.Id)~="string" or meta.Id=="" then
            return
        end

        local key=self:_catalogKey(meta.Island,meta.Id)
        local current=byKey[key]

        if not current then
            current={
                Id=meta.Id,
                Island=meta.Island or "Unknown",
                IslandOrder=meta.IslandOrder or math.huge,
                EnemyOrder=meta.EnemyOrder or math.huge,
                Boss=meta.Boss==true,
                Level=meta.Level,
                DisplayName=meta.DisplayName
            }
            byKey[key]=current
            catalog[#catalog+1]=current
            return
        end

        if typeof(meta.Level)=="number" then
            current.Level=meta.Level
        end

        if meta.Boss~=nil then
            current.Boss=meta.Boss==true
        end

        if type(meta.DisplayName)=="string" and meta.DisplayName~="" then
            current.DisplayName=meta.DisplayName
        end

        if meta.EnemyOrder and meta.EnemyOrder<current.EnemyOrder then
            current.EnemyOrder=meta.EnemyOrder
        end
    end

    if self.IslandData then
        for _,island in ipairs(self.IslandData.GetAll()) do
            for _,enemy in ipairs(island.Enemies or {}) do
                add({
                    Id=enemy.Id,
                    Island=island.Name,
                    IslandOrder=island.Order,
                    EnemyOrder=enemy.Order,
                    Boss=enemy.Boss,
                    Level=enemy.Level or enemy.QuestMinLevel
                })
            end
        end
    end

    local folder=self:_folder()

    if folder then
        for _,islandFolder in ipairs(folder:GetChildren()) do
            local islandData=self.IslandData and self.IslandData.Get(islandFolder.Name)

            for _,object in ipairs(islandFolder:GetDescendants()) do
                if object:IsA("Model") then
                    local id=object:GetAttribute("NpcId")
                    local hasInfo=type(id)=="string"
                        or object:GetAttribute("DisplayName")~=nil
                        or object:GetAttribute("Level")~=nil
                        or object:GetAttribute("Damage")~=nil
                        or object:GetAttribute("Boss")~=nil

                    if hasInfo then
                        add({
                            Id=self:_npcId(object),
                            Island=islandFolder.Name,
                            IslandOrder=islandData and islandData.Order or math.huge,
                            Boss=object:GetAttribute("Boss"),
                            Level=object:GetAttribute("Level"),
                            DisplayName=object:GetAttribute("DisplayName")
                        })
                    end
                end
            end
        end
    end

    table.sort(catalog,function(left,right)
        if typeof(left.Level)=="number" and typeof(right.Level)=="number" and left.Level~=right.Level then
            return left.Level<right.Level
        end

        if left.IslandOrder~=right.IslandOrder then
            return left.IslandOrder<right.IslandOrder
        end

        if left.EnemyOrder~=right.EnemyOrder then
            return left.EnemyOrder<right.EnemyOrder
        end

        return string.lower(left.Id)<string.lower(right.Id)
    end)

    self.EnemyCatalog=catalog
    return catalog
end

function AutoFarm:_option(meta)
    local value=meta.Id.." | "..meta.Island

    if meta.Boss then
        value=value.." | BOSS"
    end

    if typeof(meta.Level)=="number" then
        value=value.." | LV "..tostring(math.floor(meta.Level))
    end

    return value
end

function AutoFarm:GetEnemyTypes()
    local catalog=self:_buildCatalog()
    local values={}
    self.OptionLookup={}

    for _,meta in ipairs(catalog) do
        local option=self:_option(meta)
        values[#values+1]=option
        self.OptionLookup[option]=meta
    end

    if #values==0 then
        values[1]=self.SelectedEnemy
    end

    return values
end

function AutoFarm:_findMeta(id,island)
    for _,meta in ipairs(self.EnemyCatalog) do
        if meta.Id==id and (not island or meta.Island==island) then
            return meta
        end
    end

    return nil
end

function AutoFarm:SetSelectedEnemy(value)
    if type(value)~="string" or value=="" then
        return false
    end

    if #self.EnemyCatalog==0 then
        self:GetEnemyTypes()
    end

    local meta=self.OptionLookup[value]

    if not meta then
        meta=self:_findMeta(value)

        if not meta and self.IslandData then
            local island,enemy=self.IslandData.FindEnemy(value)

            if island and enemy then
                meta={
                    Id=enemy.Id,
                    Island=island.Name,
                    IslandOrder=island.Order,
                    EnemyOrder=enemy.Order,
                    Boss=enemy.Boss==true
                }
            end
        end
    end

    if meta then
        self.SelectedEnemy=meta.Id
        self.SelectedIsland=meta.Island
    else
        self.SelectedEnemy=value
        self.SelectedIsland=nil
    end

    self.Target=nil
    return true
end

function AutoFarm:GetSelectedEnemy()
    return self.SelectedEnemy
end

function AutoFarm:GetSelectedEnemyOption()
    self:GetEnemyTypes()
    local meta=self:_findMeta(self.SelectedEnemy,self.SelectedIsland)

    if meta then
        return self:_option(meta)
    end

    return self.SelectedEnemy
end

function AutoFarm:_valid(model)
    if not model then
        return false
    end

    local folder=self:_folder()

    if not folder or not model:IsDescendantOf(folder) then
        return false
    end

    if self:_npcId(model)~=self.SelectedEnemy then
        return false
    end

    if self.SelectedIsland and self:_modelIsland(model)~=self.SelectedIsland then
        return false
    end

    local humanoid=model:FindFirstChildOfClass("Humanoid")
    local root=model:FindFirstChild("HumanoidRootPart")

    return humanoid~=nil and humanoid.Health>0 and root~=nil
end

function AutoFarm:_nearest(root)
    local folder=self:_folder()

    if not folder then
        return nil
    end

    local nearest
    local nearestDistance=math.huge

    for _,object in ipairs(folder:GetDescendants()) do
        if object:IsA("Model") and self:_valid(object) then
            local enemyRoot=object:FindFirstChild("HumanoidRootPart")
            local distance=(root.Position-enemyRoot.Position).Magnitude

            if distance<nearestDistance then
                nearest=object
                nearestDistance=distance
            end
        end
    end

    return nearest
end

function AutoFarm:_face(root,enemyRoot)
    local target=Vector3.new(enemyRoot.Position.X,root.Position.Y,enemyRoot.Position.Z)

    if (target-root.Position).Magnitude>0.01 then
        root.CFrame=CFrame.lookAt(root.Position,target)
    end
end

function AutoFarm:_goal(enemyRoot,range)
    local desired=math.max(1,range-self.RangeMargin)
    local position=enemyRoot.Position-enemyRoot.CFrame.LookVector*desired
    position=Vector3.new(position.X,enemyRoot.Position.Y,position.Z)

    return CFrame.lookAt(
        position,
        Vector3.new(enemyRoot.Position.X,position.Y,enemyRoot.Position.Z)
    ),desired
end

function AutoFarm:_matchingEnemyModel(descendant)
    local folder=self:_folder()

    if not folder or not descendant then
        return nil
    end

    local current=descendant

    if not current:IsA("Model") then
        current=current.Parent
    end

    while current and current~=folder do
        if current:IsA("Model") and self:_valid(current) then
            return current
        end

        current=current.Parent
    end

    return nil
end

function AutoFarm:_approachIsland(root)
    if not self.SelectedIsland or not self.IslandData then
        return false
    end

    local existing=self:_nearest(root)

    if existing then
        self.Target=existing
        return false
    end

    local island=self.IslandData.Get(self.SelectedIsland)

    if not island or not island.CFrame then
        return false
    end

    local destination=island.CFrame*CFrame.new(0,3,0)
    self.AutoAttack:SetFarmReady(false)

    local folder=self:_folder()
    local connection

    local watching=true

    if folder then
        connection=folder.DescendantAdded:Connect(function(descendant)
            task.defer(function()
                if not watching or not self.Enabled or self.Paused then
                    return
                end

                local model=self:_matchingEnemyModel(descendant)

                if model then
                    self.Target=model
                    self.Movement:CancelOwner(MOVEMENT_OWNER,true)
                end
            end)
        end)
    end

    local moved=self.Movement:FlyTo(destination,nil,MOVEMENT_OWNER)
    watching=false

    if connection then
        connection:Disconnect()
    end

    task.wait(0.05)
    return moved or self.Target~=nil
end

function AutoFarm:_run(token)
    self.AutoAttack:SetFarmEnabled(true)
    self.AutoAttack:SetFarmReady(false)

    while self.Enabled and token==self.Token do
        if self.Paused then
            self.Target=nil
            self.AutoAttack:SetFarmReady(false)
            jitter(0.1)
            continue
        end

        local root=self:_character()

        if not root then
            self.Target=nil
            self.AutoAttack:SetFarmReady(false)
            jitter(0.25)
            continue
        end

        if not self:_valid(self.Target) then
            self.Target=self:_nearest(root)
        end

        local target=self.Target

        if not target then
            self.AutoAttack:SetFarmReady(false)

            if self:_approachIsland(root) then
                continue
            end

            jitter(0.4)
            continue
        end

        local enemyRoot=target:FindFirstChild("HumanoidRootPart")

        if not enemyRoot then
            self.Target=nil
            self.AutoAttack:SetFarmReady(false)
            jitter(0.1)
            continue
        end

        local range=self:_range()
        local goal,desired=self:_goal(enemyRoot,range)
        local goalDistance=(root.Position-goal.Position).Magnitude
        local targetDistance=(root.Position-enemyRoot.Position).Magnitude

        if goalDistance>self.Tolerance or targetDistance>range then
            self.AutoAttack:SetFarmReady(false)
            self.Movement:FlyTo(goal,nil,MOVEMENT_OWNER)
        else
            self:_face(root,enemyRoot)
            self.AutoAttack:SetFarmReady(
                targetDistance<=range
                and targetDistance>=math.max(0.5,desired-1.5)
            )
            jitter(0.05)
        end
    end

    if token==self.Token then
        self.Target=nil
        self.AutoAttack:SetFarmReady(false)
        self.AutoAttack:SetFarmEnabled(false)
    end
end

function AutoFarm:SetPaused(paused)
    paused=paused==true

    if self.Paused==paused then
        return
    end

    self.Paused=paused
    self.Target=nil
    self.AutoAttack:SetFarmReady(false)

    if paused and self.Movement then
        self.Movement:CancelOwner(MOVEMENT_OWNER,true)
    end
end

function AutoFarm:SetEnabled(enabled)
    enabled=enabled==true

    if self.Enabled==enabled then
        return
    end

    self.Enabled=enabled
    self.Token+=1

    if enabled then
        local token=self.Token

        task.spawn(function()
            self:_run(token)
        end)
    else
        self.Target=nil
        self.AutoAttack:SetFarmReady(false)
        self.AutoAttack:SetFarmEnabled(false)

        if self.Movement then
            self.Movement:CancelOwner(MOVEMENT_OWNER,true)
        end
    end
end

function AutoFarm:Destroy()
    self:SetEnabled(false)
end

return AutoFarm

]],
    ["src/games/features/noobpiece/autoquest.lua"] = [[
local Players=game:GetService("Players")
local ReplicatedStorage=game:GetService("ReplicatedStorage")
local Workspace=game:GetService("Workspace")

-- Humanised timing: vary each periodic wait so loops are not perfectly periodic.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local AutoQuest={}
AutoQuest.__index=AutoQuest

local MOVEMENT_OWNER="AutoQuest"

local function lower(value)
    return string.lower(tostring(value or ""))
end

function AutoQuest.new(movement,islandData,autoFarm)
    local events=ReplicatedStorage:FindFirstChild("Events") or ReplicatedStorage:WaitForChild("Events",8)
    assert(events,"Noob Piece: Events unavailable")
    local remotes={}
    for _,name in ipairs({"NpcInteract","OpenDialog","DialogChoice","QuestUpdate"}) do
        local remote=events:FindFirstChild(name) or events:WaitForChild(name,8)
        assert(remote and remote:IsA("RemoteEvent"),"Noob Piece: Events/"..name.." unavailable")
        remotes[name]=remote
    end

    local self=setmetatable({
        Player=Players.LocalPlayer,
        Movement=movement,
        IslandData=islandData,
        AutoFarm=autoFarm,
        NpcInteract=remotes.NpcInteract,
        OpenDialog=remotes.OpenDialog,
        DialogChoice=remotes.DialogChoice,
        QuestUpdate=remotes.QuestUpdate,
        Enabled=false,
        Token=0,
        SelectedEnemy="Noob",
        ActiveQuest=nil,
        Stage=nil,
        WaitingDialog=false,
        LastInteract=0,
        DialogMovement=nil,
        IgnoreHudUntil=0,
        Connections={}
    },AutoQuest)

    self.Connections[#self.Connections+1]=self.OpenDialog.OnClientEvent:Connect(function(data)
        self:_onDialog(data)
    end)

    self.Connections[#self.Connections+1]=self.QuestUpdate.OnClientEvent:Connect(function(data)
        self:_onQuestUpdate(data)
    end)

    self:_syncHud()
    return self
end

function AutoQuest:_character()
    local character=self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")

    if not character or not humanoid or humanoid.Health<=0 or not root then
        return nil
    end

    return character,humanoid,root
end

function AutoQuest:_syncHud()
    if os.clock()<self.IgnoreHudUntil then
        return
    end

    local playerGui=self.Player:FindFirstChild("PlayerGui")
    local hud=playerGui and playerGui:FindFirstChild("QuestHUD")
    local quest=hud and hud:FindFirstChild("Quest")

    if not quest or not quest.Visible then
        return
    end

    local header=quest:FindFirstChild("HeaderFrame")
    local background=quest:FindFirstChild("BackgroundFrame")
    local questLabel=header and header:FindFirstChild("QuestLabel")
    local counter=background and background:FindFirstChild("CounterLabel")
    local kills,required

    if counter and type(counter.Text)=="string" then
        kills,required=counter.Text:match("(%d+)%s*/%s*(%d+)")
        kills=tonumber(kills)
        required=tonumber(required)
    end

    self.ActiveQuest={
        QuestName=questLabel and questLabel.Text or nil,
        Kills=kills,
        Required=required,
        SeededFromHUD=true
    }
end

function AutoQuest:_onQuestUpdate(data)
    if typeof(data)~="table" then
        return
    end

    if data.Removed then
        if not self.ActiveQuest or not self.ActiveQuest.Id or self.ActiveQuest.Id==data.Id then
            self.ActiveQuest=nil
        end

        self.IgnoreHudUntil=os.clock()+0.6

        if self.Enabled then
            self.Stage=nil
            self.WaitingDialog=false
            self.Token+=1
            local token=self.Token
            task.delay(0.2,function()
                self:_run(token)
            end)
        end
        return
    end

    self.ActiveQuest=data
    self.Stage=nil
    self.WaitingDialog=false

    if self.AutoFarm then
        self.AutoFarm:SetPaused(self.Enabled and not self:_questMatches())
    end
end

function AutoQuest:_questInfo()
    if not self.IslandData then
        return nil
    end

    local island,enemy=self.IslandData.FindEnemy(self.SelectedEnemy)

    if not island or not enemy or type(enemy.QuestGiver)~="string" then
        return nil
    end

    return island,enemy
end

function AutoQuest:_questMatches()
    if not self.ActiveQuest then
        return false
    end

    local name=lower(self.ActiveQuest.QuestName)
    local selected=lower(self.SelectedEnemy)

    if name==selected then
        return true
    end

    local _,enemy=self:_questInfo()
    local expected=enemy and enemy.QuestId

    return expected~=nil and self.ActiveQuest.Id==expected
end

function AutoQuest:_findChoice(data,wanted)
    if typeof(data)~="table" or type(wanted)~="string" then
        return nil
    end

    for index,choice in ipairs(data.Choices or {}) do
        if lower(choice)==lower(wanted) then
            return index
        end
    end

    return nil
end

function AutoQuest:_captureDialogMovement()
    local _,humanoid=self:_character()

    if not humanoid then
        self.DialogMovement=nil
        return
    end

    local huds={}
    local playerGui=self.Player:FindFirstChild("PlayerGui")

    if playerGui then
        for _,name in ipairs({"StatsHUD","ButtonsHUD","CurrencyHUD","ProfileHUD"}) do
            local hud=playerGui:FindFirstChild(name)

            if hud then
                huds[hud]=hud.Enabled
            end
        end
    end

    self.DialogMovement={
        Humanoid=humanoid,
        WalkSpeed=humanoid.WalkSpeed,
        UseJumpPower=humanoid.UseJumpPower,
        JumpPower=humanoid.JumpPower,
        JumpHeight=humanoid.JumpHeight,
        Huds=huds
    }
end

function AutoQuest:_restoreDialog()
    task.defer(function()
        self.Player:SetAttribute("DialogOpen",false)

        local playerGui=self.Player:FindFirstChild("PlayerGui")
        local dialogs=playerGui and playerGui:FindFirstChild("DialogsHUD")

        if dialogs then
            for _,name in ipairs({"NPCDialog","QuestDialog","SelectedDialog"}) do
                local panel=dialogs:FindFirstChild(name)
                if panel then
                    panel.Visible=false
                end
            end
        end

        local state=self.DialogMovement
        local humanoid=state and state.Humanoid

        if humanoid and humanoid.Parent then
            humanoid.WalkSpeed=state.WalkSpeed

            if state.UseJumpPower then
                humanoid.JumpPower=state.JumpPower
            else
                humanoid.JumpHeight=state.JumpHeight
            end
        end

        if state and state.Huds then
            for hud,wasEnabled in pairs(state.Huds) do
                if hud and hud.Parent then
                    hud.Enabled=wasEnabled
                end
            end
        end
    end)
end

function AutoQuest:_onDialog(data)
    if not self.Enabled or not self.WaitingDialog or typeof(data)~="table" then
        return
    end

    local _,enemy=self:_questInfo()

    if not enemy then
        return
    end

    local choice

    if self.Stage=="select" then
        choice=self:_findChoice(data,enemy.QuestChoice or enemy.Id)

        if not choice then
            self.WaitingDialog=false
            self.Stage=nil
            self:_restoreDialog()
            return
        end

        self.Stage="accept"
    elseif self.Stage=="accept" then
        choice=self:_findChoice(data,"Accept")

        if not choice then
            self.WaitingDialog=false
            self.Stage=nil
            self:_restoreDialog()
            return
        end

        self.Stage="quest"
        self.WaitingDialog=false
    else
        return
    end

    self.DialogChoice:FireServer(data.Token,choice)
    self:_restoreDialog()
end

function AutoQuest:_giver(enemy)
    local quests=Workspace:FindFirstChild("Quests")
    local questGiver=quests and quests:FindFirstChild("QuestGiver")
    local normal=questGiver and questGiver:FindFirstChild("Normal")

    return normal and normal:FindFirstChild(enemy.QuestGiver)
end

function AutoQuest:_npcRoot(npc)
    if not npc then
        return nil
    end

    if npc:IsA("BasePart") then
        return npc
    end

    if npc:IsA("Model") then
        return npc:FindFirstChild("Torso")
            or npc:FindFirstChild("UpperTorso")
            or npc:FindFirstChild("HumanoidRootPart")
            or npc.PrimaryPart
            or npc:FindFirstChildWhichIsA("BasePart",true)
    end

    return nil
end

function AutoQuest:_moveNear(root,target)
    local distance=(root.Position-target.Position).Magnitude

    if distance<=10 then
        return true
    end

    local position=target.Position-target.CFrame.LookVector*6
    local goal=CFrame.lookAt(
        position,
        Vector3.new(target.Position.X,position.Y,target.Position.Z)
    )

    return self.Movement:FlyTo(goal,nil,MOVEMENT_OWNER)
end

function AutoQuest:_approachIsland(root,island)
    if not island or not island.CFrame then
        return false
    end

    local destination=island.CFrame*CFrame.new(0,3,0)

    if (root.Position-destination.Position).Magnitude<=100 then
        return false
    end

    return self.Movement:FlyTo(destination,nil,MOVEMENT_OWNER)
end

function AutoQuest:_requestQuest(island,enemy,token)
    local _,_,root=self:_character()

    if not root then
        return false
    end

    local giver=self:_giver(enemy)

    if not giver then
        self:_approachIsland(root,island)
        jitter(0.35)
        return false
    end

    local npcRoot=self:_npcRoot(giver)

    if not npcRoot then
        self:_approachIsland(root,island)
        jitter(0.2)
        return false
    end

    if not self:_moveNear(root,npcRoot) then
        return false
    end

    if not self.Enabled or token~=self.Token then
        return false
    end

    local now=os.clock()

    if now-self.LastInteract<0.6 then
        task.wait(0.6-(now-self.LastInteract))
    end

    self:_captureDialogMovement()
    self.Stage="select"
    self.WaitingDialog=true
    self.LastInteract=os.clock()
    self.NpcInteract:FireServer(giver)
    return true
end

function AutoQuest:_run(token)
    while self.Enabled and token==self.Token do
        self:_syncHud()

        if self.ActiveQuest then
            if self.AutoFarm then
                self.AutoFarm:SetPaused(not self:_questMatches())
            end
            return
        end

        local island,enemy=self:_questInfo()

        if not island or not enemy then
            if self.AutoFarm then
                self.AutoFarm:SetPaused(false)
            end
            return
        end

        if self.AutoFarm then
            self.AutoFarm:SetPaused(true)
        end

        if not self.WaitingDialog then
            self:_requestQuest(island,enemy,token)
        end

        local deadline=os.clock()+4

        while self.Enabled and token==self.Token and not self.ActiveQuest and os.clock()<deadline do
            jitter(0.1)
        end

        if self.ActiveQuest then
            if self.AutoFarm then
                self.AutoFarm:SetPaused(not self:_questMatches())
            end
            return
        end

        self.WaitingDialog=false
        self.Stage=nil
        jitter(0.35)
    end
end

function AutoQuest:SetSelectedEnemy(name)
    if type(name)~="string" or name=="" then
        return false
    end

    self.SelectedEnemy=name

    if self.Enabled then
        self.Token+=1
        local token=self.Token
        task.spawn(function()
            self:_run(token)
        end)
    end

    return true
end

function AutoQuest:SetEnabled(enabled)
    enabled=enabled==true

    if self.Enabled==enabled then
        return
    end

    self.Enabled=enabled
    self.Token+=1
    self.WaitingDialog=false
    self.Stage=nil

    if not enabled then
        if self.Movement then
            self.Movement:CancelOwner(MOVEMENT_OWNER,true)
        end

        if self.AutoFarm then
            self.AutoFarm:SetPaused(false)
        end

        if self.Player:GetAttribute("DialogOpen") then
            self:_restoreDialog()
        end

        self.DialogMovement=nil
        return
    end

    self:_syncHud()
    local token=self.Token

    task.spawn(function()
        self:_run(token)
    end)
end

function AutoQuest:GetActiveQuest()
    return self.ActiveQuest
end

function AutoQuest:Destroy()
    self:SetEnabled(false)

    for _,connection in ipairs(self.Connections) do
        pcall(connection.Disconnect,connection)
    end

    table.clear(self.Connections)
end

return AutoQuest


