    end

    local position=root.Position-root.CFrame.LookVector*self.Offset
    local goal=CFrame.lookAt(
        position,
        Vector3.new(root.Position.X,position.Y,root.Position.Z)
    )

    return self.Movement:FlyTo(goal,nil,MOVEMENT_OWNER)
end

